function labelFromMap(map, value) {
  const key = String(value || "");
  return map[key] || key || "-";
}

function smartMaskSecret(value) {
  const clean = String(value || "");
  if (!clean) return "";
  // Show only first 2 chars + fixed 4 asterisks — compact, no long strings
  const start = clean.slice(0, 2);
  return `${start}****`;
}

async function copyAccountApiKey(rawKey) {
  const clean = String(rawKey || "").trim();
  if (!clean) return false;
  try {
    if (navigator?.clipboard?.writeText) {
      await navigator.clipboard.writeText(clean);
      return true;
    }
  } catch (_error) {
    // Fallback below for hardened browser environments.
  }
  const textarea = document.createElement("textarea");
  textarea.value = clean;
  textarea.setAttribute("readonly", "readonly");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  document.body.appendChild(textarea);
  textarea.focus();
  textarea.select();
  let copied = false;
  try {
    copied = Boolean(document.execCommand("copy"));
  } catch (_error) {
    copied = false;
  }
  document.body.removeChild(textarea);
  return copied;
}

function getPermissions() {
  const fromWindow = window.APP_PERMISSIONS || {};
  const _b = (key, def) => Boolean(fromWindow[key] !== undefined ? fromWindow[key] : def);
  return {
    can_view_analytics: _b("can_view_analytics", true),
    can_view_settings:  _b("can_view_settings", true),
    can_view_supplies:    _b("can_view_supplies", false),
    can_view_any_supply:  _b("can_view_any_supply", false),
    can_view_wb_supplies: _b("can_view_wb_supplies", _b("can_view_supplies", false)),
    can_view_wb_fbs_supplies: _b("can_view_wb_fbs_supplies", false),
    can_view_wb_fbs_tsd: _b("can_view_wb_fbs_tsd", false),
    can_view_ozon_supplies: _b("can_view_ozon_supplies", _b("can_view_supplies", false)),
    can_view_feedback:  _b("can_view_feedback", true),
    can_view_reviews:   _b("can_view_reviews", true),
    can_view_questions: _b("can_view_questions", true),
    can_view_chats:     _b("can_view_chats", false),
    sync_chats_enabled: _b("sync_chats_enabled", false),
    can_supply_planning: _b("can_supply_planning", false),
    can_supply_stock: _b("can_supply_stock", false),
    can_stock_productions: (window.APP_PERMISSIONS || {}).can_stock_productions ?? null,
    can_view_salary:          _b("can_view_salary", false),
    can_view_salary_settings: _b("can_view_salary_settings", false),
    can_view_salary_report: _b("can_view_salary_report", false),
    can_view_salary_zp_export: _b("can_view_salary_zp_export", false),
    can_salary_productions: (window.APP_PERMISSIONS || {}).can_salary_productions ?? null,
    is_admin:           _b("is_admin", false),
  };
}

function isTenantOwner() {
  const fromWindow = window.APP_PERMISSIONS || {};
  return Boolean(fromWindow.is_tenant_owner || fromWindow.is_super_admin);
}

function isChatSyncEnabled() {
  // Marketplace chat sync kill-switch (reviews/questions unaffected).
  return Boolean(getPermissions().sync_chats_enabled) && Boolean(getPermissions().can_view_chats);
}

function canViewSection(section) {
  const permissions = getPermissions();
  if (section === "analytics")    return permissions.can_view_analytics;
  if (section === "settings")     return permissions.can_view_settings;
  if (section === "team")         return isTenantOwner();
  if (section === "reviews")      return permissions.can_view_reviews;
  if (section === "conversations") return permissions.can_view_questions;
  if (section === "chats")        return isChatSyncEnabled();
  if (section === "salary")         return permissions.can_view_salary || isTenantOwner();
  if (section === "salary-settings") return isTenantOwner() || permissions.can_view_salary_settings;
  if (section === "supplies-wb")  return permissions.can_view_wb_supplies || (permissions.can_view_supplies && isTenantOwner());
  if (section === "supplies-wb-fbs") return permissions.can_view_wb_fbs_supplies || (permissions.can_view_supplies && isTenantOwner());
  if (section === "supplies-ozon") return permissions.can_view_ozon_supplies || (permissions.can_view_supplies && isTenantOwner());
  if (section === "supplies-poa") return permissions.can_view_supplies;
  if (section === "supplies-certificates") return permissions.can_view_supplies;
  if (section === "supplies-settings") return permissions.can_view_settings || permissions.can_view_supplies;
  if (section === "supply-planning") return isTenantOwner() || permissions.can_supply_planning;
  if (section === "supplies-balances") return isTenantOwner() || permissions.can_supply_stock;
  return true;
}

function readStoredUiState(key) {
  try {
    return String(window.localStorage.getItem(key) || "");
  } catch (_error) {
    return "";
  }
}

function writeStoredUiState(key, value) {
  try {
    window.localStorage.setItem(key, String(value || ""));
  } catch (_error) {
    // noop: localStorage may be unavailable in hardened browser modes.
  }
}

