/** Full one-line driver documents for PoA / заявка / table. */
function driverDocumentsLine(d) {
  if (!d) return "";
  const series = String(d.doc_vu_series || "").trim();
  const number = String(d.doc_vu_number || "").trim();
  const issuer = String(d.doc_vu_issuer || "").trim();
  const dateVal = String(d.doc_vu_date || "").trim();
  const inn = String(d.doc_inn_fl || "").trim();
  const parts = [];
  // Issuer/date are suffixes only — do not emit a standalone «ВУ кем выд.» line
  // that would hide richer legacy documents text.
  if (series || number) {
    let vu = "ВУ";
    if (series && number) {
      vu = (series.length === 4 && /^\d+$/.test(series))
        ? `ВУ ${series.slice(0, 2)} ${series.slice(2)} ${number}`
        : `ВУ ${series} ${number}`;
    } else if (series) {
      vu = `ВУ серия ${series}`;
    } else {
      vu = `ВУ № ${number}`;
    }
    if (issuer) vu += ` кем выд. ${issuer}`;
    if (dateVal) vu += ` выд. ${dateVal}`;
    parts.push(vu);
  }
  if (inn) parts.push(`ИНН ${inn}`);
  const composed = parts.join(", ");
  const legacy = String(d.documents || "").trim();
  if (series || number) return composed || legacy;
  if (composed && !legacy) return composed;
  return legacy || composed;
}

