window.openSupplyBalancesVisibilityModal = openSupplyBalancesVisibilityModal;

function closeSupplyBalancesVisibilityModal() {
  setModalVisibility("supplyBalancesVisibilityModal", false);
}
window.closeSupplyBalancesVisibilityModal = closeSupplyBalancesVisibilityModal;

function renderSupplyBalancesVisibilityList() {
  const list = document.getElementById("supplyBalancesVisibilityList");
  if (!list) return;
  const materials = supplyBalancesState.visibilityItems.filter((x) => x.item_type === "material");
  const products = supplyBalancesState.visibilityItems.filter((x) => x.item_type === "product");
  const searchActive = !!_sbNormalizeSearch(
    document.getElementById("supplyBalancesVisibilitySearch")?.value || ""
  );
  const renderGroup = (title, rows, type) => {
    if (!rows.length) return "";
    return `<div class="sb-vis-group-title" data-vis-group="${esc(type)}">${esc(title)}</div>` + rows.map((row) => {
      const key = `${row.item_type}:${row.item_id}`;
      const on = row.visible !== false;
      const typeLabel = row.item_type === "material" ? "Материал" : "Товар";
      const searchBlob = [
        row.name,
        row.unit,
        typeLabel,
        row.supplier_article,
        row.wb_nmid,
        row.ozon_sku,
        ...(Array.isArray(row.barcodes) ? row.barcodes : []),
      ].map((x) => String(x || "")).filter(Boolean).join(" ");
      const minRaw = row.min_qty;
      const minVal = (minRaw === null || minRaw === undefined || minRaw === "")
        ? ""
        : String(minRaw);
      const dragAttrs = searchActive
        ? `draggable="false" class="sb-vis-row sb-vis-row-no-drag"`
        : `draggable="true" class="sb-vis-row"`;
      return `<div ${dragAttrs} data-vis-key="${esc(key)}" data-vis-type="${esc(row.item_type)}"
        data-vis-id="${Number(row.item_id)}" data-sb-search="${esc(searchBlob)}">
        <span class="sb-vis-handle" title="Перетащить" aria-hidden="true">⋮⋮</span>
        <div class="sb-vis-meta">
          <div class="sb-vis-name">${esc(row.name || "")}</div>
          <div class="sb-vis-sub">${esc(row.unit || "шт")} · ${typeLabel}</div>
        </div>
        <label class="sb-vis-min" title="Минимальный остаток">
          <span>Мин.</span>
          <input type="number" min="0" step="any" inputmode="decimal"
            data-vis-min-input="${esc(key)}" value="${esc(minVal)}" placeholder="—"
            oninput="onSupplyBalanceMinQtyInput('${esc(row.item_type)}', ${Number(row.item_id)}, this.value)"
            onclick="event.stopPropagation()" onmousedown="event.stopPropagation()" />
        </label>
        <button type="button" class="sb-vis-eye ${on ? "" : "is-off"}" title="${on ? "Скрыть" : "Показать"}"
          onclick="toggleSupplyBalanceVisibility('${esc(row.item_type)}', ${Number(row.item_id)})">${on ? "Вкл" : "Выкл"}</button>
      </div>`;
    }).join("");
  };
  const html = renderGroup("Материалы", materials, "material") + renderGroup("Товары", products, "product");
  list.innerHTML = html || `<div class="sb-doc-empty">Нет материалов и товаров в справочниках</div>`;
  applySupplyBalancesVisibilitySearch();
  _initSupplyBalancesVisibilityDnD(list);
}

let _sbVisDragging = null;

function _initSupplyBalancesVisibilityDnD(list) {
  if (!list || list.dataset.sbVisDndBound === "1") return;
  list.dataset.sbVisDndBound = "1";
  list.addEventListener("dragstart", (e) => {
    const row = e.target.closest(".sb-vis-row");
    if (!row || row.draggable === false || row.classList.contains("sb-vis-row-no-drag")) {
      e.preventDefault();
      return;
    }
    // Don't start drag from the eye toggle button or min-qty input.
    if (e.target.closest(".sb-vis-eye") || e.target.closest(".sb-vis-min")) {
      e.preventDefault();
      return;
    }
    const searchQ = _sbNormalizeSearch(
      document.getElementById("supplyBalancesVisibilitySearch")?.value || ""
    );
    if (searchQ) {
      e.preventDefault();
      return;
    }
    _sbVisDragging = row;
    row.classList.add("is-dragging");
    try {
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("text/plain", row.getAttribute("data-vis-key") || "");
    } catch (_err) {
      /* ignore */
    }
  });
  list.addEventListener("dragend", () => {
    if (_sbVisDragging) _sbVisDragging.classList.remove("is-dragging");
    list.querySelectorAll(".sb-vis-row.dnd-over").forEach((r) => r.classList.remove("dnd-over"));
    _sbVisDragging = null;
  });
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
    if (!_sbVisDragging) return;
    const over = e.target.closest(".sb-vis-row");
    list.querySelectorAll(".sb-vis-row.dnd-over").forEach((r) => r.classList.remove("dnd-over"));
    if (
      over &&
      over !== _sbVisDragging &&
      over.getAttribute("data-vis-type") === _sbVisDragging.getAttribute("data-vis-type")
    ) {
      over.classList.add("dnd-over");
    }
  });
  list.addEventListener("drop", (e) => {
    e.preventDefault();
    const over = e.target.closest(".sb-vis-row");
    if (!over || !_sbVisDragging || over === _sbVisDragging) return;
    const type = _sbVisDragging.getAttribute("data-vis-type");
    if (over.getAttribute("data-vis-type") !== type) return;
    const rows = Array.from(list.querySelectorAll(`.sb-vis-row[data-vis-type="${type}"]`));
    const fromIdx = rows.indexOf(_sbVisDragging);
    const toIdx = rows.indexOf(over);
    if (fromIdx < 0 || toIdx < 0) return;
    if (fromIdx < toIdx) over.after(_sbVisDragging);
    else over.before(_sbVisDragging);
    over.classList.remove("dnd-over");
    _syncSupplyBalancesVisibilityOrderFromDom();
  });
}

function _syncSupplyBalancesVisibilityOrderFromDom() {
  const list = document.getElementById("supplyBalancesVisibilityList");
  if (!list) return;
  const byKey = new Map(
    (supplyBalancesState.visibilityItems || []).map((x) => [
      `${x.item_type}:${x.item_id}`,
      x,
    ])
  );
  const ordered = [];
  ["material", "product"].forEach((type) => {
    const rows = Array.from(list.querySelectorAll(`.sb-vis-row[data-vis-type="${type}"]`));
    rows.forEach((el, idx) => {
      const key = el.getAttribute("data-vis-key") || "";
      const item = byKey.get(key);
      if (!item) return;
      item.sort_order = idx;
      ordered.push(item);
      byKey.delete(key);
    });
  });
  // Keep any leftover items (should not happen) at the end.
  byKey.forEach((item) => ordered.push(item));
  supplyBalancesState.visibilityItems = ordered;
}

function onSupplyBalancesVisibilitySearch() {
  applySupplyBalancesVisibilitySearch();
  const list = document.getElementById("supplyBalancesVisibilityList");
  if (!list) return;
  const q = _sbNormalizeSearch(
    document.getElementById("supplyBalancesVisibilitySearch")?.value || ""
  );
  list.querySelectorAll(".sb-vis-row").forEach((row) => {
    if (q) {
      row.draggable = false;
      row.classList.add("sb-vis-row-no-drag");
    } else {
      row.draggable = true;
      row.classList.remove("sb-vis-row-no-drag");
    }
  });
}
window.onSupplyBalancesVisibilitySearch = onSupplyBalancesVisibilitySearch;

function applySupplyBalancesVisibilitySearch() {
  const list = document.getElementById("supplyBalancesVisibilityList");
  const input = document.getElementById("supplyBalancesVisibilitySearch");
  const countEl = document.getElementById("supplyBalancesVisibilityFilterCount");
  if (!list) return;
  const q = _sbNormalizeSearch(input?.value || "");
  const itemRows = Array.from(list.querySelectorAll(".sb-vis-row"));
  let visible = 0;
  itemRows.forEach((tr) => {
    const hay = _sbNormalizeSearch(tr.getAttribute("data-sb-search") || "");
    const show = !q || hay.includes(q);
    tr.classList.toggle("hidden", !show);
    tr.hidden = !show;
    if (show) visible += 1;
  });
  list.querySelectorAll(".sb-vis-group-title").forEach((groupEl) => {
    let hasVisible = false;
    let el = groupEl.nextElementSibling;
    while (el && !el.classList.contains("sb-vis-group-title")) {
      if (el.classList.contains("sb-vis-row") && !el.hidden) {
        hasVisible = true;
        break;
      }
      el = el.nextElementSibling;
    }
    groupEl.classList.toggle("hidden", !hasVisible);
    groupEl.hidden = !hasVisible;
  });
  let emptyEl = list.querySelector(".sb-search-empty");
  if (q && itemRows.length && visible === 0) {
    if (!emptyEl) {
      emptyEl = document.createElement("div");
      emptyEl.className = "sb-doc-empty sb-search-empty";
      emptyEl.textContent = "Ничего не найдено";
      list.appendChild(emptyEl);
    }
    emptyEl.hidden = false;
  } else if (emptyEl) {
    emptyEl.hidden = true;
  }
  if (countEl) {
    if (q && itemRows.length) {
      countEl.hidden = false;
      countEl.textContent = `${visible} из ${itemRows.length}`;
    } else {
      countEl.hidden = true;
      countEl.textContent = "";
    }
  }
}

function toggleSupplyBalanceVisibility(itemType, itemId) {
  const row = supplyBalancesState.visibilityItems.find(
    (x) => x.item_type === itemType && Number(x.item_id) === Number(itemId)
  );
  if (!row) return;
  row.visible = !(row.visible !== false);
  // Update button in place to keep DnD order / scroll position.
  const list = document.getElementById("supplyBalancesVisibilityList");
  const el = list?.querySelector(
    `.sb-vis-row[data-vis-key="${itemType}:${Number(itemId)}"] .sb-vis-eye`
  );
  if (el) {
    const on = row.visible !== false;
    el.classList.toggle("is-off", !on);
    el.title = on ? "Скрыть" : "Показать";
    el.textContent = on ? "Вкл" : "Выкл";
  } else {
    renderSupplyBalancesVisibilityList();
  }
}
window.toggleSupplyBalanceVisibility = toggleSupplyBalanceVisibility;

function onSupplyBalanceMinQtyInput(itemType, itemId, raw) {
  const row = supplyBalancesState.visibilityItems.find(
    (x) => x.item_type === itemType && Number(x.item_id) === Number(itemId)
  );
  if (!row) return;
  const s = String(raw ?? "").trim();
  if (!s) {
    row.min_qty = null;
    return;
  }
  const n = Number(s);
  row.min_qty = Number.isFinite(n) && n >= 0 ? n : null;
}
window.onSupplyBalanceMinQtyInput = onSupplyBalanceMinQtyInput;

function _sbSyncVisibilityMinFromDom() {
  const list = document.getElementById("supplyBalancesVisibilityList");
  if (!list) return;
  list.querySelectorAll("[data-vis-min-input]").forEach((input) => {
    const key = String(input.getAttribute("data-vis-min-input") || "");
    const row = (supplyBalancesState.visibilityItems || []).find(
      (x) => `${x.item_type}:${x.item_id}` === key
    );
    if (!row) return;
    const s = String(input.value || "").trim();
    if (!s) {
      row.min_qty = null;
      return;
    }
    const n = Number(s);
    row.min_qty = Number.isFinite(n) && n >= 0 ? n : null;
  });
}

async function saveSupplyBalancesVisibility() {
  _syncSupplyBalancesVisibilityOrderFromDom();
  _sbSyncVisibilityMinFromDom();
  const items = [];
  ["material", "product"].forEach((type) => {
    const group = (supplyBalancesState.visibilityItems || []).filter(
      (x) => x.item_type === type
    );
    group.forEach((x, idx) => {
      items.push({
        item_type: x.item_type,
        item_id: Number(x.item_id),
        visible: x.visible !== false,
        sort_order: idx,
        min_qty: (x.min_qty === null || x.min_qty === undefined || x.min_qty === "")
          ? null
          : Number(x.min_qty),
      });
    });
  });
  try {
    const res = await fetch("/api/supply-balances/visibility", {
      method: "PUT",
      headers: jsonHeaders(),
      body: JSON.stringify({ items }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || "Ошибка сохранения");
    closeSupplyBalancesVisibilityModal();
    await loadSupplyBalancesData();
  } catch (e) {
    alert(String(e.message || e));
  }
}
window.saveSupplyBalancesVisibility = saveSupplyBalancesVisibility;

async function openSupplyStockMovementsModal(itemType, itemId) {
  const itype = String(itemType || "").trim().toLowerCase();
  const iid = Number(itemId || 0);
  if (!itype || !iid) return;
  const list = document.getElementById("supplyStockMovementsList");
  const lead = document.getElementById("supplyStockMovementsLead");
  const title = document.getElementById("supplyStockMovementsTitle");
  setModalVisibility("supplyStockMovementsModal", true);
  if (title) title.textContent = "Журнал движений";
  if (lead) lead.textContent = "Загрузка…";
  if (list) list.innerHTML = `<div class="sb-doc-empty">Загрузка…</div>`;
  try {
    const pid = Number(supplyBalancesState.productionId || 0);
    const params = new URLSearchParams({
      item_type: itype,
      item_id: String(iid),
      limit: "100",
    });
    if (pid) params.set("production_id", String(pid));
    const res = await fetch(`/api/supply-balances/movements?${params.toString()}`);
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      const detail = data.detail;
      const msg = typeof detail === "string"
        ? detail
        : (Array.isArray(detail)
          ? detail.map((x) => (x && (x.msg || x.detail)) || x).join("; ")
          : "Ошибка загрузки");
      throw new Error(msg || "Ошибка загрузки");
    }
    const name = String(data.name || "");
    const unit = String(data.unit || "шт");
    const balText = _sbQtyText(data.balance);
    if (title) title.textContent = name || "Журнал движений";
    if (lead) {
      lead.textContent = `Текущий остаток: ${balText} ${unit}. Показаны последние движения.`;
    }
    const items = Array.isArray(data.items) ? data.items : [];
    if (!items.length) {
      if (list) list.innerHTML = `<div class="sb-doc-empty">Движений пока нет</div>`;
      return;
    }
    if (list) {
      list.innerHTML = items.map((m) => {
        const qty = Number(m.qty);
        const qtyClass = !Number.isFinite(qty)
          ? ""
          : (qty < 0 ? "is-neg" : (qty > 0 ? "is-pos" : "is-zero"));
        const qtyText = Number.isFinite(qty)
          ? (qty > 0 ? `+${_sbQtyText(qty)}` : _sbQtyText(qty))
          : "—";
        const who = String(m.created_by_name || "").trim();
        const comment = String(m.comment || "").trim();
        const meta = [who, comment].filter(Boolean).join(" · ");
        return `<div class="sb-movements-row">
          <div class="sb-movements-date">${esc(_sbFormatDateLabel(m.movement_date))}</div>
          <div class="sb-movements-main">
            <div class="sb-movements-kind">${esc(m.kind_label || m.kind || "Движение")}</div>
            ${meta ? `<div class="sb-movements-meta">${esc(meta)}</div>` : ""}
          </div>
          <div class="sb-movements-qty ${qtyClass}">${esc(qtyText)} <span>${esc(unit)}</span></div>
        </div>`;
      }).join("");
    }
  } catch (e) {
    if (lead) lead.textContent = "";
    const rawDetail = e && e.message !== undefined ? e.message : e;
    const errText = typeof rawDetail === "string"
      ? rawDetail
      : (rawDetail && typeof rawDetail === "object" && rawDetail.detail
        ? String(rawDetail.detail)
        : "Ошибка загрузки");
    if (list) {
      list.innerHTML = `<div class="sb-doc-empty" style="color:#b91c1c">${esc(errText)}</div>`;
    }
  }
}
window.openSupplyStockMovementsModal = openSupplyStockMovementsModal;

function closeSupplyStockMovementsModal() {
  setModalVisibility("supplyStockMovementsModal", false);
}
window.closeSupplyStockMovementsModal = closeSupplyStockMovementsModal;

async function loadRecommendations() {
  const res = await fetch("/api/recommendations");
  const data = await res.json();
  const info = document.getElementById("recommendationsInfo");
  if (!res.ok) {
    if (info) info.textContent = "Ошибка: " + (data.detail || "не удалось загрузить рекомендации");
    return;
  }
  recommendationsState.rows = (data.items || []).map((item) => ({
    source_article: String(item.source_article || ""),
    targets_csv: String(item.targets_csv || ""),
  }));
  renderRecommendationsRows();
  if (info) info.textContent = "";
}

async function saveRecommendations() {
  const info = document.getElementById("recommendationsInfo");
  const payload = {
    rows: recommendationsState.rows.map((row) => ({
      source_article: String(row.source_article || "").trim(),
      targets_csv: String(row.targets_csv || "").trim(),
    })),
  };
  const res = await fetch("/api/recommendations", {
    method: "PUT",
    headers: jsonHeaders(),
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (!res.ok) {
    if (info) info.textContent = "Ошибка: " + (data.detail || "не удалось сохранить рекомендации");
    return;
  }
  if (info) info.textContent = `Сохранено связок: ${data.pairs || 0}`;
  await loadRecommendations();
}

function triggerRecommendationsImport() {
  const input = document.getElementById("recommendationsImportInput");
  if (!input) return;
  input.value = "";
  input.click();
}

async function importRecommendationsFile(inputElement) {
  const info = document.getElementById("recommendationsInfo");
  const file = inputElement?.files?.[0];
  if (!file) return;
  const formData = new FormData();
  formData.append("file", file);
  const res = await fetch("/api/recommendations/import", {
    method: "POST",
    headers: withCsrfHeaders(),
    body: formData,
  });
  const data = await res.json();
  if (!res.ok) {
    if (info) info.textContent = "Ошибка: " + (data.detail || "не удалось импортировать Excel");
    return;
  }
  if (info) info.textContent = `Импорт завершен. Источников: ${data.sources || 0}, связок: ${data.pairs || 0}`;
  await loadRecommendations();
}

function exportRecommendations() {
  window.location.href = "/api/recommendations/export";
}

async function queueManual(reviewId) {
  await fetch(`/api/reviews/${encodeURIComponent(reviewId)}/queue-manual`, {
    method: "POST",
    headers: withCsrfHeaders(),
  });
  await loadReviews();
}

async function autoReply(reviewId) {
  const res = await fetch(`/api/reviews/${encodeURIComponent(reviewId)}/auto-reply`, {
    method: "POST",
    headers: withCsrfHeaders(),
  });
  const data = await res.json();
  if (!res.ok) {
    alert(data.detail || "Ошибка автоответа");
    return;
  }
  alert("Автоответ: " + data.reply);
  await loadReviews();
}

async function manualReply(reviewId) {
  const operator = prompt("Имя оператора:");
  if (!operator) return;
  const text = prompt("Текст ручного ответа:");
  if (!text) return;
  const payload = { operator_name: operator, response_text: text };
  const res = await fetch(`/api/reviews/${encodeURIComponent(reviewId)}/manual-reply`, {
    method: "POST",
    headers: jsonHeaders(),
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (!res.ok) {
    alert(data.detail || "Ошибка ручного ответа");
    return;
  }
  await loadReviews();
}

async function loadProfile() {
  const res = await fetch("/api/profile");
  const data = await res.json();
  if (!res.ok) {
    document.getElementById("profileInfo").textContent = data.detail || "Ошибка загрузки профиля";
    return;
  }
  document.getElementById("profileFullName").value = data.full_name || "";
  document.getElementById("profileEmail").value = data.email || "";
  document.getElementById("profileCurrentPassword").value = "";
  document.getElementById("profileNewPassword").value = "";
  document.getElementById("profileNewPasswordRepeat").value = "";
  const userSyncDateInput = document.getElementById("userSyncStartDate");
  const userSyncInfo = document.getElementById("userSyncSettingsInfo");
  if (userSyncDateInput) {
    userSyncDateInput.value = data.sync_start_date || "";
    userSyncDateInput.disabled = false;
  }
  if (userSyncInfo) {
    userSyncInfo.textContent = "";
  }
  if (!Array.isArray(data.editable_template_variables)) {
    await loadUserTemplateVariables();
  }
  if (Array.isArray(data.editable_template_variables)) {
    userTemplateVariablesState.items = data.editable_template_variables.map((item) => ({
      ...item,
      value: String(item.value || item.default_value || ""),
    }));
    renderUserTemplateVariables();
  }
  setPasswordFieldsVisible(false);
  document.getElementById("profileInfo").textContent = "";
}

async function saveUserSyncSettings() {
  const input = document.getElementById("userSyncStartDate");
  const info = document.getElementById("userSyncSettingsInfo");
  if (!input || !info) return;
  const payload = {
    use_sync_start_date: true,
    sync_start_date: input.value || null,
  };
  const res = await fetch("/api/user-sync-settings", {
    method: "PUT",
    headers: jsonHeaders(),
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (!res.ok) {
    info.textContent = "Ошибка: " + (data.detail || "не удалось сохранить дату");
    return;
  }
  const settings = data.settings || {};
  input.value = settings.sync_start_date || "";
  input.disabled = false;
  info.textContent = "Сохранено";
}

function setPasswordFieldsVisible(visible) {
  const fields = document.getElementById("profilePasswordFields");
  const toggleLink = document.getElementById("profilePasswordToggle");
  if (!fields || !toggleLink) return;
  if (visible) {
    fields.classList.remove("hidden");
    toggleLink.textContent = "Скрыть смену пароля";
    return;
  }
  fields.classList.add("hidden");
  toggleLink.textContent = "Изменить пароль";
  document.getElementById("profileCurrentPassword").value = "";
  document.getElementById("profileNewPassword").value = "";
  document.getElementById("profileNewPasswordRepeat").value = "";
}

function togglePasswordFields(event) {
  if (event) event.preventDefault();
  const fields = document.getElementById("profilePasswordFields");
  const isHidden = fields?.classList.contains("hidden") ?? true;
  setPasswordFieldsVisible(isHidden);
}

async function saveProfile() {
  const payload = {
    full_name: document.getElementById("profileFullName").value.trim() || null,
    email: document.getElementById("profileEmail").value.trim() || null,
    current_password: document.getElementById("profileCurrentPassword").value || null,
    new_password: document.getElementById("profileNewPassword").value || null,
    new_password_repeat: document.getElementById("profileNewPasswordRepeat").value || null,
  };
  const res = await fetch("/api/profile", {
    method: "PUT",
    headers: jsonHeaders(),
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (!res.ok) {
    document.getElementById("profileInfo").textContent = "Ошибка: " + (data.detail || "не удалось обновить профиль");
    return;
  }
  document.getElementById("profileInfo").textContent = "Изменения сохранены";
  await loadProfile();
}

