// WB FBS Orders (marketplace-api) — isolated from FBW supplies
// ═══════════════════════════════════════════════════════════════════════════

const wbFbsState = {
  sourceId: null,
  sources: [],
  tab: "new",
  items: [],
  total: 0,
  page: 1,
  page_size: 50,
  counts: {},
  selected: new Set(),
  selectedMeta: {}, // orderId -> { supply_id }
  selectAllMatching: false,
  lastSearch: "",
  pollTimer: null,
  viewMode: "orders", // "orders" | "supplies-assembly" | "supplies-delivery"
  loadSeq: 0,
  loadAbort: null,
  // Exact order-id lookup across tabs / WB API (finished & cancelled escape hatch).
  lookupMode: false,
  lookupMeta: null, // { order_id, tab, source, message }
};

const WB_FBS_TAB_LABELS = {
  new: "Новые",
  assembly: "На сборке",
  delivery: "В доставке",
  finished: "Завершённые",
  cancelled: "Отменённые",
  archive: "Архив",
};

function _wbFbsParseOrderIdQuery(search) {
  const q = String(search || "").trim();
  if (!/^\d{6,}$/.test(q)) return null;
  const n = Number(q);
  return Number.isFinite(n) ? n : null;
}

function _wbFbsOrderRowMatchesNonId(row, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return false;
  if (String(row?.article || "").toLowerCase().includes(q)) return true;
  if (String(row?.supply_id || "").toLowerCase().includes(q)) return true;
  if (String(row?.nm_id || "").toLowerCase().includes(q)) return true;
  if (String(row?.product_name || "").toLowerCase().includes(q)) return true;
  const barcodes = Array.isArray(row?.barcodes)
    ? row.barcodes
    : (Array.isArray(row?.skus) ? row.skus : []);
  return barcodes.some((b) => String(b || "").toLowerCase().includes(q));
}

function _wbFbsSupplyRowMatchesNonOrderId(row, query, orderId) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return false;
  const sid = String(row?.supply_id || "").trim();
  if (sid && sid.toLowerCase().includes(q) && Number(sid) !== Number(orderId)) return true;
  if (sid && sid === String(orderId)) return true;
  if (String(row?.name || "").toLowerCase().includes(q)) return true;
  if (String(row?.warehouse_label || "").toLowerCase().includes(q)) return true;
  const offices = Array.isArray(row?.offices) ? row.offices : [];
  if (offices.some((o) => String(o || "").toLowerCase().includes(q))) return true;
  return false;
}

let _wbFbsSearchTimer = null;
function onWbFbsSearchInput() {
  if (_wbFbsSearchTimer) clearTimeout(_wbFbsSearchTimer);
  // Debounce: avoid WB API lookup on every digit while typing an order number.
  _wbFbsSearchTimer = setTimeout(() => {
    _wbFbsSearchTimer = null;
    loadWbFbsOrders(true);
  }, 400);
}
window.onWbFbsSearchInput = onWbFbsSearchInput;

function _wbFbsIsSuppliesTab() {
  // Exact order lookup always renders a single order row, even on assembly/delivery.
  if (wbFbsState.lookupMode) return false;
  return wbFbsState.tab === "delivery" || wbFbsState.tab === "assembly";
}

function _wbFbsRememberMeta(order) {
  const oid = Number(order?.order_id);
  if (!Number.isFinite(oid)) return;
  wbFbsState.selectedMeta[oid] = {
    supply_id: String(order.supply_id || "").trim(),
  };
}

function _wbFbsSelectedSupplyIds() {
  if (_wbFbsIsSuppliesTab()) {
    return [...wbFbsState.selected].map((x) => String(x || "").trim()).filter(Boolean);
  }
  const ids = [];
  for (const oid of wbFbsState.selected) {
    const meta = wbFbsState.selectedMeta[oid];
    const sid = String(meta?.supply_id || "").trim();
    if (sid) ids.push(sid);
  }
  // Fallback: current page items (for freshly checked rows)
  for (const o of wbFbsState.items) {
    const oid = Number(o.order_id);
    if (!wbFbsState.selected.has(oid)) continue;
    const sid = String(o.supply_id || "").trim();
    if (sid) ids.push(sid);
  }
  return [...new Set(ids)];
}

function _wbFbsSelectedOrderIdsFromSupplies() {
  const ids = [];
  for (const item of wbFbsState.items) {
    const sid = String(item.supply_id || "").trim();
    if (!wbFbsState.selected.has(sid)) continue;
    const orderIds = Array.isArray(item.order_ids) ? item.order_ids : [];
    for (const oid of orderIds) {
      const n = Number(oid);
      if (Number.isFinite(n)) ids.push(n);
    }
  }
  return [...new Set(ids)];
}

function _wbFbsEsc(s) {
  return esc(String(s ?? ""));
}

function _wbFbsAgo(iso) {
  if (!iso) return "";
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return "";
  const sec = Math.max(0, Math.floor((Date.now() - t) / 1000));
  if (sec < 60) return `${sec} сек назад`;
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min} мин назад`;
  const h = Math.floor(min / 60);
  const rem = min % 60;
  if (h < 48) return rem ? `${h} ч ${rem} мин назад` : `${h} ч назад`;
  const d = Math.floor(h / 24);
  return `${d} дн назад`;
}

function _wbFbsFmtDate(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toLocaleDateString("ru-RU", { day: "2-digit", month: "2-digit", year: "numeric" });
}

// Hidden for everyone (operators + owner): not needed for day-to-day work,
// and sync no longer spends API quota on these tabs.
const WB_FBS_HIDDEN_TABS = new Set(["finished", "cancelled", "archive"]);
// Back-compat alias for older references.
const WB_FBS_OWNER_ONLY_TABS = WB_FBS_HIDDEN_TABS;

function _wbFbsCanViewOwnerTabs() {
  return isTenantOwner();
}

function _wbFbsSyncOwnerOnlyTabs() {
  document.querySelectorAll("#wbFbsTabs .wb-fbs-tab").forEach((btn) => {
    const tab = String(btn.dataset.tab || "");
    if (!WB_FBS_HIDDEN_TABS.has(tab)) return;
    btn.hidden = true;
    btn.style.display = "none";
  });
  if (WB_FBS_HIDDEN_TABS.has(wbFbsState.tab)) {
    wbFbsState.tab = "new";
    document.querySelectorAll("#wbFbsTabs .wb-fbs-tab").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.tab === "new");
    });
  }
}

function _wbFbsSyncOwnerOnlyGear() {
  const btn = document.getElementById("wbFbsAutoSyncSettingsBtn");
  if (!btn) return;
  const can = _wbFbsCanViewOwnerTabs();
  btn.hidden = !can;
  btn.style.display = can ? "" : "none";
  if (!can) btn.classList.remove("is-auto-on");
}

function _wbFbsSyncOwnerOnlyKizBtn() {
  const btn = document.getElementById("wbFbsKizCirculationBtn");
  if (!btn) return;
  const can = _wbFbsCanViewOwnerTabs();
  btn.hidden = !can;
  btn.style.display = can ? "" : "none";
}

async function initWbFbsSection() {
  _wbFbsSyncOwnerOnlyTabs();
  _wbFbsSyncOwnerOnlyGear();
  _wbFbsSyncOwnerOnlyKizBtn();
  initWbFbsColumnResizer();
  _wbFbsSyncTableMode();
  await loadWbFbsSources();
  if (_wbFbsCanViewOwnerTabs()) _wbFbsRefreshAutoSyncGear();
  await loadWbFbsOrders(true);
}

// ── WB FBS column resizer (per-user localStorage) ──
const WB_FBS_COL_WIDTHS_PREFIX = "wb_fbs_col_widths_v2";
const WB_FBS_DEFAULT_WIDTHS = [24, 56, 20]; // order, product, warehouse (price column hidden in UI)
let _wbFbsColResizerInited = false;

function _wbFbsColWidthsKey() {
  const email = String(document.querySelector(".sidebar-user-email")?.textContent || "").trim().toLowerCase();
  return email ? `${WB_FBS_COL_WIDTHS_PREFIX}:${email}` : WB_FBS_COL_WIDTHS_PREFIX;
}

function _applyWbFbsColWidths(widths) {
  const cols = Array.from(document.querySelectorAll("#wbFbsColgroup col")).filter((c) => !c.dataset.fixed);
  cols.forEach((col, i) => {
    if (widths[i] !== undefined) col.style.width = `${widths[i]}%`;
  });
}

function _getWbFbsColWidths() {
  const cols = Array.from(document.querySelectorAll("#wbFbsColgroup col")).filter((c) => !c.dataset.fixed);
  return cols.map((col, i) => parseFloat(col.style.width) || WB_FBS_DEFAULT_WIDTHS[i] || 10);
}

function initWbFbsColumnResizer() {
  const table = document.getElementById("wbFbsOrdersTable");
  if (!table) return;
  // Supplies table has fixed columns; only restore widths in orders mode.
  if (!_wbFbsIsSuppliesTab()) {
    let widths = WB_FBS_DEFAULT_WIDTHS.slice();
    try {
      const saved = JSON.parse(localStorage.getItem(_wbFbsColWidthsKey()) || "null");
      if (Array.isArray(saved) && saved.length === widths.length) widths = saved;
      else if (Array.isArray(saved)) localStorage.removeItem(_wbFbsColWidthsKey());
    } catch (_) {}
    _applyWbFbsColWidths(widths);
  }

  if (_wbFbsColResizerInited) return;
  _wbFbsColResizerInited = true;

  let startX = 0;
  let colIdx = 0;
  let startWidths = [];
  let activeHandle = null;

  function onMouseMove(e) {
    const tableEl = document.getElementById("wbFbsOrdersTable");
    if (!tableEl || _wbFbsIsSuppliesTab()) return;
    const tableW = tableEl.offsetWidth || 1;
    const deltaPct = ((e.clientX - startX) / tableW) * 100;
    const newWidths = startWidths.slice();
    const minPct = 8;
    const nextIdx = colIdx < newWidths.length - 1 ? colIdx + 1 : colIdx - 1;
    let newCur = Math.max(minPct, startWidths[colIdx] + deltaPct);
    let newNext = Math.max(minPct, startWidths[nextIdx] - deltaPct);
    if (newNext < minPct) {
      newCur = startWidths[colIdx] + (startWidths[nextIdx] - minPct);
      newNext = minPct;
    }
    newWidths[colIdx] = Math.round(newCur * 10) / 10;
    newWidths[nextIdx] = Math.round(newNext * 10) / 10;
    _applyWbFbsColWidths(newWidths);
  }
  function onMouseUp() {
    document.removeEventListener("mousemove", onMouseMove);
    document.removeEventListener("mouseup", onMouseUp);
    document.body.style.cursor = "";
    document.body.style.userSelect = "";
    if (activeHandle) activeHandle.classList.remove("dragging");
    activeHandle = null;
    if (_wbFbsIsSuppliesTab()) return;
    try {
      localStorage.setItem(_wbFbsColWidthsKey(), JSON.stringify(_getWbFbsColWidths()));
    } catch (_) {}
  }

  table.addEventListener("mousedown", (e) => {
    const handle = e.target?.closest?.(".col-resize-handle");
    if (!handle || _wbFbsIsSuppliesTab()) return;
    e.preventDefault();
    e.stopPropagation();
    const th = handle.parentElement;
    colIdx = parseInt(th.getAttribute("data-col") || "0", 10);
    startX = e.clientX;
    startWidths = _getWbFbsColWidths();
    activeHandle = handle;
    document.addEventListener("mousemove", onMouseMove);
    document.addEventListener("mouseup", onMouseUp);
    document.body.style.cursor = "col-resize";
    document.body.style.userSelect = "none";
    handle.classList.add("dragging");
  });
}
window.initWbFbsColumnResizer = initWbFbsColumnResizer;

async function loadWbFbsSources() {
  const sel = document.getElementById("wbFbsSourceSelect");
  if (!sel) return;
  try {
    const res = await fetch("/api/wb-fbs/sources");
    const data = await res.json();
    wbFbsState.sources = Array.isArray(data) ? data : [];
    const prev = wbFbsState.sourceId;
    sel.innerHTML = wbFbsState.sources.length
      ? wbFbsState.sources.map((s) =>
          `<option value="${_wbFbsEsc(s.id)}">${_wbFbsEsc(s.name || ("Источник " + s.id))}</option>`
        ).join("")
      : '<option value="">Нет активных источников ВБ</option>';
    if (prev && wbFbsState.sources.some((s) => Number(s.id) === Number(prev))) {
      sel.value = String(prev);
      wbFbsState.sourceId = Number(prev);
    } else if (wbFbsState.sources.length) {
      wbFbsState.sourceId = Number(wbFbsState.sources[0].id);
      sel.value = String(wbFbsState.sourceId);
    } else {
      wbFbsState.sourceId = null;
    }
  } catch (e) {
    sel.innerHTML = '<option value="">Ошибка загрузки источников</option>';
    wbFbsState.sourceId = null;
  }
}

function onWbFbsSourceChange() {
  const sel = document.getElementById("wbFbsSourceSelect");
  wbFbsState.sourceId = sel?.value ? Number(sel.value) : null;
  closeWbFbsSelectionSupplyModal();
  clearWbFbsSelection();
  loadWbFbsOrders(true);
}
window.onWbFbsSourceChange = onWbFbsSourceChange;

function setWbFbsTab(tab) {
  let next = String(tab || "new");
  if (WB_FBS_HIDDEN_TABS.has(next)) {
    next = "new";
  }
  wbFbsState.tab = next;
  document.querySelectorAll("#wbFbsTabs .wb-fbs-tab").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.tab === next);
  });
  _wbFbsSyncTableMode();
  _wbFbsSyncCollectMgtBtn(wbFbsState.counts || {});
  closeWbFbsSelectionSupplyModal();
  clearWbFbsSelection();
  loadWbFbsOrders(true);
}
window.setWbFbsTab = setWbFbsTab;

function _wbFbsHasRowActions() {
  // No row ⋮ menu / actions column on New, Finished, and Cancelled tabs.
  return (
    wbFbsState.tab !== "cancelled"
    && wbFbsState.tab !== "new"
    && wbFbsState.tab !== "finished"
  );
}

function _wbFbsColspan() {
  if (wbFbsState.tab === "delivery") return 8;
  if (wbFbsState.tab === "assembly") return 6;
  return _wbFbsHasRowActions() ? 5 : 4;
}

function _wbFbsSyncActionsColumn() {
  const show = _wbFbsHasRowActions();
  const col = document.querySelector("#wbFbsColgroup .wb-fbs-col-act");
  const th = document.querySelector("#wbFbsOrdersTable .wb-fbs-th-act");
  if (col) col.style.display = show ? "" : "none";
  if (th) th.style.display = show ? "" : "none";
}

function _wbFbsSyncTableMode() {
  const supplies = _wbFbsIsSuppliesTab();
  const nextMode = supplies
    ? (wbFbsState.tab === "assembly" ? "supplies-assembly" : "supplies-delivery")
    : "orders";
  const modeChanged = wbFbsState.viewMode !== nextMode;
  wbFbsState.viewMode = nextMode;
  const table = document.getElementById("wbFbsOrdersTable");
  const colgroup = document.getElementById("wbFbsColgroup");
  const thead = table?.querySelector("thead tr");
  const search = document.getElementById("wbFbsSearchFilter");
  if (table) {
    table.classList.toggle("wb-fbs-table--supplies", supplies);
    table.classList.toggle("wb-fbs-table--assembly", wbFbsState.tab === "assembly");
  }
  if (search) {
    search.placeholder = supplies
      ? "Поиск по поставке, заказу, складу…"
      : "Поиск по заказу, артикулу, ШК…";
  }
  if (!colgroup || !thead) {
    _wbFbsSyncActionsColumn();
    return;
  }
  // Avoid rebuilding thead/colgroup on every fetch — only when tab mode changes.
  if (!modeChanged && colgroup.children.length) {
    if (!supplies) _wbFbsSyncActionsColumn();
    return;
  }
  if (supplies && wbFbsState.tab === "assembly") {
    // Portal «На сборке»: Поставка / QR / Заказы / Этап сборки / Склад
    // No ⋮ column — WB API cannot rename supplies; QR is only after delivery.
    colgroup.innerHTML = `
      <col data-fixed="1" class="wb-fbs-col-check" style="width:40px" />
      <col data-col="0" class="wb-fbs-col-supply" style="width:26%" />
      <col data-col="1" class="wb-fbs-col-qr" style="width:16%" />
      <col data-col="2" class="wb-fbs-col-orders" style="width:14%" />
      <col data-col="3" class="wb-fbs-col-status" style="width:16%" />
      <col data-col="4" class="wb-fbs-col-wh" style="width:24%" />
    `;
    thead.innerHTML = `
      <th class="wb-fbs-th-check"><input type="checkbox" id="wbFbsSelectAll" onchange="toggleSelectAllWbFbs(this.checked)" title="Выбрать все на странице" /></th>
      <th data-col="0">Поставка</th>
      <th data-col="1">QR-код поставки</th>
      <th data-col="2">Заказы и грузоместа</th>
      <th data-col="3">Этап сборки</th>
      <th data-col="4">Склад</th>
    `;
  } else if (supplies) {
    colgroup.innerHTML = `
      <col data-fixed="1" class="wb-fbs-col-check" style="width:40px" />
      <col data-col="0" class="wb-fbs-col-supply" style="width:20%" />
      <col data-col="1" class="wb-fbs-col-qr" style="width:14%" />
      <col data-col="2" class="wb-fbs-col-status" style="width:14%" />
      <col data-col="3" class="wb-fbs-col-scan" style="width:14%" />
      <col data-col="4" class="wb-fbs-col-orders" style="width:14%" />
      <col data-col="5" class="wb-fbs-col-wh" style="width:18%" />
      <col data-fixed="1" class="wb-fbs-col-act" style="width:48px" />
    `;
    thead.innerHTML = `
      <th class="wb-fbs-th-check"><input type="checkbox" id="wbFbsSelectAll" onchange="toggleSelectAllWbFbs(this.checked)" title="Выбрать все на странице" /></th>
      <th data-col="0">Поставка</th>
      <th data-col="1">QR-код поставки</th>
      <th data-col="2">Статус</th>
      <th data-col="3">Время сканирования QR-кода поставки</th>
      <th data-col="4">Заказы и грузоместа</th>
      <th data-col="5">Склад</th>
      <th class="wb-fbs-th-act"></th>
    `;
  } else {
    colgroup.innerHTML = `
      <col data-fixed="1" class="wb-fbs-col-check" style="width:40px" />
      <col data-col="0" class="wb-fbs-col-order" />
      <col data-col="1" class="wb-fbs-col-product" />
      <col data-col="2" class="wb-fbs-col-wh" />
      <col data-fixed="1" class="wb-fbs-col-act" style="width:48px" />
    `;
    thead.innerHTML = `
      <th class="wb-fbs-th-check"><input type="checkbox" id="wbFbsSelectAll" onchange="toggleSelectAllWbFbs(this.checked)" title="Выбрать все на странице" /></th>
      <th data-col="0">Заказ<span class="col-resize-handle"></span></th>
      <th data-col="1">Товар<span class="col-resize-handle"></span></th>
      <th data-col="2">Склад<span class="col-resize-handle"></span></th>
      <th class="wb-fbs-th-act"></th>
    `;
    initWbFbsColumnResizer();
    _wbFbsSyncActionsColumn();
  }
}

function _wbFbsClearLookupMode() {
  wbFbsState.lookupMode = false;
  wbFbsState.lookupMeta = null;
}

async function _wbFbsLookupOrderById(orderId, { signal, seq } = {}) {
  const params = new URLSearchParams({
    source_id: String(wbFbsState.sourceId),
    order_id: String(orderId),
  });
  const res = await fetch(
    `/api/wb-fbs/orders/lookup?${params}`,
    signal ? { signal } : undefined
  );
  const data = await res.json().catch(() => ({}));
  if (seq != null && seq !== wbFbsState.loadSeq) return null;
  if (!res.ok) {
    const detail = data && data.detail;
    throw new Error(
      typeof detail === "string" ? detail : "Не удалось найти заказ в WB"
    );
  }
  return data;
}

function _wbFbsApplyLookupResult(data, orderId) {
  const item = data && data.item;
  if (!data?.found || !item) {
    _wbFbsClearLookupMode();
    return false;
  }
  const tab = String(data.tab || item.tab || "").trim();
  wbFbsState.lookupMode = true;
  wbFbsState.lookupMeta = {
    order_id: Number(data.order_id || orderId),
    tab,
    source: String(data.source || ""),
    message: String(data.message || ""),
  };
  wbFbsState.items = [item];
  wbFbsState.total = 1;
  wbFbsState.page = 1;
  if (data.counts) {
    wbFbsState.counts = data.counts;
    _wbFbsUpdateCounts(wbFbsState.counts);
  }
  // Keep operator on an operational tab button; do not open hidden tabs.
  if (tab && !WB_FBS_HIDDEN_TABS.has(tab) && wbFbsState.tab !== tab) {
    wbFbsState.tab = tab;
    document.querySelectorAll("#wbFbsTabs .wb-fbs-tab").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.tab === tab);
    });
  }
  _wbFbsSyncTableMode();
  renderWbFbsOrdersTable();
  const info = document.getElementById("wbFbsInfo");
  if (info) {
    const tabLabel = WB_FBS_TAB_LABELS[tab] || tab || "—";
    const via = data.source === "remote" ? "загружен из WB API" : "найден в базе";
    info.textContent = `Заказ ${orderId}: ${tabLabel} · ${via}`;
  }
  const pageInfo = document.getElementById("wbFbsPageInfo");
  if (pageInfo) pageInfo.textContent = "1 / 1";
  const prevBtn = document.getElementById("wbFbsPrevBtn");
  const nextBtn = document.getElementById("wbFbsNextBtn");
  if (prevBtn) prevBtn.disabled = true;
  if (nextBtn) nextBtn.disabled = true;
  return true;
}

async function loadWbFbsOrders(resetPage = false) {
  if (resetPage) wbFbsState.page = 1;
  const info = document.getElementById("wbFbsInfo");
  const tbody = document.getElementById("wbFbsOrdersTbody");
  _wbFbsClearLookupMode();
  _wbFbsSyncTableMode();
  if (!wbFbsState.sourceId) {
    if (tbody) tbody.innerHTML = `<tr><td colspan="${_wbFbsColspan()}" class="small" style="padding:16px;color:#94a3b8">Выберите источник ВБ в Поставки → Настройки → Источники</td></tr>`;
    if (info) info.textContent = "";
    _wbFbsUpdateCounts({});
    return;
  }
  const search = document.getElementById("wbFbsSearchFilter")?.value.trim() || "";
  // Search/filter change invalidates «select all matching».
  if (search !== wbFbsState.lastSearch) {
    wbFbsState.lastSearch = search;
    if (wbFbsState.selectAllMatching) clearWbFbsSelection();
    else wbFbsState.selectAllMatching = false;
  }
  const params = new URLSearchParams({
    source_id: String(wbFbsState.sourceId),
    tab: wbFbsState.tab,
    page: String(wbFbsState.page),
    page_size: String(wbFbsState.page_size),
  });
  if (search) params.set("search", search);
  const suppliesMode = _wbFbsIsSuppliesTab();
  const url = suppliesMode ? `/api/wb-fbs/supplies?${params}` : `/api/wb-fbs/orders?${params}`;
  const seq = ++wbFbsState.loadSeq;
  if (wbFbsState.loadAbort) {
    try { wbFbsState.loadAbort.abort(); } catch (_) {}
  }
  wbFbsState.loadAbort = (typeof AbortController !== "undefined") ? new AbortController() : null;
  const signal = wbFbsState.loadAbort ? wbFbsState.loadAbort.signal : undefined;
  if (tbody) {
    tbody.innerHTML = `<tr><td colspan="${_wbFbsColspan()}" class="wb-fbs-empty">Загрузка…</td></tr>`;
  }
  try {
    const res = await fetch(url, signal ? { signal } : undefined);
    const data = await res.json();
    if (seq !== wbFbsState.loadSeq) return; // newer tab/load won
    if (!res.ok) throw new Error(data.detail || "Ошибка загрузки");
    wbFbsState.items = data.items || [];
    wbFbsState.total = data.total || 0;
    wbFbsState.page = data.page || 1;
    wbFbsState.counts = data.counts || {};
    _wbFbsUpdateCounts(wbFbsState.counts);

    // Exact order number: prefer exact hit; ignore order_id substring false-positives
    // (ILIKE), keep barcode/article hits, otherwise cross-tab / WB lookup.
    const orderIdQuery = _wbFbsParseOrderIdQuery(search);
    if (orderIdQuery) {
      let exactItems = [];
      let nonIdItems = [];
      if (suppliesMode) {
        exactItems = wbFbsState.items.filter((s) => {
          const ids = Array.isArray(s.order_ids) ? s.order_ids : [];
          if (ids.some((id) => Number(id) === orderIdQuery)) return true;
          return String(s.supply_id || "").trim() === String(orderIdQuery);
        });
        nonIdItems = wbFbsState.items.filter((s) =>
          _wbFbsSupplyRowMatchesNonOrderId(s, search, orderIdQuery)
        );
      } else {
        exactItems = wbFbsState.items.filter((o) => Number(o.order_id) === orderIdQuery);
        nonIdItems = wbFbsState.items.filter((o) => _wbFbsOrderRowMatchesNonId(o, search));
      }

      if (exactItems.length) {
        wbFbsState.items = exactItems;
        wbFbsState.total = exactItems.length;
      } else if (nonIdItems.length) {
        // Numeric query matched SKU/article/supply name — keep tab results.
        wbFbsState.items = nonIdItems;
        wbFbsState.total = nonIdItems.length;
      } else {
        if (tbody) {
          tbody.innerHTML = `<tr><td colspan="${_wbFbsColspan()}" class="wb-fbs-empty">Ищем заказ ${orderIdQuery} в WB…</td></tr>`;
        }
        if (info) info.textContent = `Поиск заказа ${orderIdQuery}…`;
        const lookup = await _wbFbsLookupOrderById(orderIdQuery, { signal, seq });
        if (seq !== wbFbsState.loadSeq) return;
        if (lookup && _wbFbsApplyLookupResult(lookup, orderIdQuery)) return;
        wbFbsState.items = [];
        wbFbsState.total = 0;
        _wbFbsSyncTableMode();
        if (suppliesMode) renderWbFbsSuppliesTable();
        else renderWbFbsOrdersTable();
        if (info) {
          info.textContent = lookup?.message
            || `Заказ ${orderIdQuery} не найден в Новые / На сборке / В доставке и в WB API`;
        }
        const pageInfoMiss = document.getElementById("wbFbsPageInfo");
        if (pageInfoMiss) pageInfoMiss.textContent = "1 / 1";
        const prevMiss = document.getElementById("wbFbsPrevBtn");
        const nextMiss = document.getElementById("wbFbsNextBtn");
        if (prevMiss) prevMiss.disabled = true;
        if (nextMiss) nextMiss.disabled = true;
        return;
      }
    }

    if (suppliesMode) renderWbFbsSuppliesTable();
    else renderWbFbsOrdersTable();
    const totalPages = Math.max(1, Math.ceil(wbFbsState.total / wbFbsState.page_size));
    if (info) {
      info.textContent = suppliesMode
        ? `Поставок: ${wbFbsState.total}`
        : `Заказов: ${wbFbsState.total}`;
    }
    const pageInfo = document.getElementById("wbFbsPageInfo");
    if (pageInfo) pageInfo.textContent = `${wbFbsState.page} / ${totalPages}`;
    const prevBtn = document.getElementById("wbFbsPrevBtn");
    const nextBtn = document.getElementById("wbFbsNextBtn");
    if (prevBtn) prevBtn.disabled = wbFbsState.page <= 1;
    if (nextBtn) nextBtn.disabled = wbFbsState.page >= totalPages;
  } catch (e) {
    if (e && (e.name === "AbortError" || String(e.message || "").includes("aborted"))) return;
    if (seq !== wbFbsState.loadSeq) return;
    if (tbody) tbody.innerHTML = `<tr><td colspan="${_wbFbsColspan()}" class="small" style="padding:16px;color:#b91c1c">${_wbFbsEsc(e.message || e)}</td></tr>`;
  }
}
window.loadWbFbsOrders = loadWbFbsOrders;

function _wbFbsUpdateCounts(counts) {
  const map = {
    new: "wbFbsCountNew",
    assembly: "wbFbsCountAssembly",
    delivery: "wbFbsCountDelivery",
    finished: "wbFbsCountFinished",
    cancelled: "wbFbsCountCancelled",
    archive: "wbFbsCountArchive",
  };
  for (const [tab, id] of Object.entries(map)) {
    const el = document.getElementById(id);
    if (el) el.textContent = String(counts[tab] || 0);
  }
  _wbFbsSyncCollectMgtBtn(counts);
}

function _wbFbsSyncCollectMgtBtn(counts) {
  const btn = document.getElementById("wbFbsCollectMgtBtn");
  if (!btn) return;
  const mgtNew = Number((counts && counts.mgt_new) || 0);
  // Collects MGT from «Новые», but the control is also available on assembly/delivery.
  const tabOk = wbFbsState.tab === "new"
    || wbFbsState.tab === "assembly"
    || wbFbsState.tab === "delivery";
  const show = tabOk && mgtNew > 0 && !!wbFbsState.sourceId;
  btn.classList.toggle("hidden", !show);
}

function closeWbFbsSyncInfo() {
  const info = document.getElementById("wbFbsSyncInfo");
  if (!info) return;
  info.hidden = true;
  info.classList.remove("is-error", "is-ok");
  const textEl = document.getElementById("wbFbsSyncInfoText");
  const palletsEl = document.getElementById("wbFbsSyncInfoPallets");
  if (textEl) textEl.textContent = "";
  if (palletsEl) {
    palletsEl.innerHTML = "";
    palletsEl.hidden = true;
  }
}
window.closeWbFbsSyncInfo = closeWbFbsSyncInfo;

function _wbFbsSetSyncInfo(text, kind = "", palletSummary = null) {
  const info = document.getElementById("wbFbsSyncInfo");
  if (!info) return;
  const msg = String(text || "").trim();
  const textEl = document.getElementById("wbFbsSyncInfoText");
  const palletsEl = document.getElementById("wbFbsSyncInfoPallets");
  if (textEl) textEl.textContent = msg;
  else info.textContent = msg;

  const rows = Array.isArray(palletSummary) ? palletSummary : [];
  if (palletsEl) {
    if (rows.length && (kind === "ok" || /готово/i.test(msg))) {
      palletsEl.innerHTML = rows.map((row) => {
        const name = _wbFbsEsc(row?.name || `Источник ${row?.source_id || ""}`);
        const label = _wbFbsEsc(
          row?.pallets_label
          || `${Number(row?.pallets || 0).toFixed(2).replace(".", ",")} паллета`
        );
        return `<div class="wb-fbs-sync-info-pallet-row">${name} — ${label}</div>`;
      }).join("");
      palletsEl.hidden = false;
    } else {
      palletsEl.innerHTML = "";
      palletsEl.hidden = true;
    }
  }

  info.hidden = !msg;
  info.classList.toggle("is-error", kind === "error");
  info.classList.toggle("is-ok", kind === "ok");
  info.style.color = "";
}

function _wbFbsRestoreRowMenu(menu) {
  if (!menu) return;
  menu.classList.remove("open");
  menu.style.top = "";
  menu.style.left = "";
  const wrapId = menu.dataset.wrapId;
  const wrap = wrapId ? document.getElementById(wrapId) : null;
  if (wrap && menu.parentElement !== wrap) wrap.appendChild(menu);
}

function _wbFbsCloseRowMenus(exceptId = null) {
  document.querySelectorAll(".wb-fbs-row-menu.open, .wb-fbs-row-menu[data-ported='1']").forEach((menu) => {
    if (exceptId != null && menu.dataset.orderId === String(exceptId) && menu.classList.contains("open")) {
      return;
    }
    menu.dataset.ported = "";
    _wbFbsRestoreRowMenu(menu);
  });
}

function _wbFbsPositionRowMenu(menu, anchorEl) {
  const rect = anchorEl.getBoundingClientRect();
  const menuW = Math.max(menu.offsetWidth || 220, 220);
  const menuH = menu.offsetHeight || 96;
  let left = rect.right - menuW;
  if (left < 8) left = 8;
  if (left + menuW > window.innerWidth - 8) left = Math.max(8, window.innerWidth - menuW - 8);
  let top = rect.bottom + 4;
  if (top + menuH > window.innerHeight - 8) {
    top = Math.max(8, rect.top - menuH - 4);
  }
  menu.style.top = `${Math.round(top)}px`;
  menu.style.left = `${Math.round(left)}px`;
}

function toggleWbFbsRowMenu(event, orderId) {
  event.stopPropagation();
  const btn = event.currentTarget || event.target?.closest?.(".wb-fbs-row-menu-btn");
  const menu = document.getElementById(`wbFbsRowMenu_${orderId}`);
  if (!menu || !btn) return;
  const willOpen = !menu.classList.contains("open");
  _wbFbsCloseRowMenus(willOpen ? orderId : null);
  if (!willOpen) {
    menu.dataset.ported = "";
    _wbFbsRestoreRowMenu(menu);
    return;
  }
  const wrap = menu.closest(".wb-fbs-row-menu-wrap") || menu.parentElement;
  if (wrap) {
    if (!wrap.id) wrap.id = `wbFbsRowMenuWrap_${orderId}`;
    menu.dataset.wrapId = wrap.id;
  }
  // Move to body so panel/table overflow and backdrop-filter cannot clip it.
  document.body.appendChild(menu);
  menu.dataset.ported = "1";
  menu.classList.add("open");
  _wbFbsPositionRowMenu(menu, btn);
  requestAnimationFrame(() => _wbFbsPositionRowMenu(menu, btn));
}
window.toggleWbFbsRowMenu = toggleWbFbsRowMenu;

function _wbFbsCanCancelOrder() {
  // Cancel is owner/admin only — assigned managers must not see it.
  return isTenantOwner() || Boolean((window.APP_PERMISSIONS || {}).is_admin);
}

function _wbFbsRowActionsHtml(oid) {
  if (!_wbFbsHasRowActions()) return "";
  return `<div class="wb-fbs-row-menu-wrap">
    <button type="button" class="icon-btn secondary wb-fbs-row-menu-btn" title="Действия"
            onclick="toggleWbFbsRowMenu(event, ${oid})" aria-haspopup="menu">⋮</button>
    <div id="wbFbsRowMenu_${oid}" class="wb-fbs-row-menu" data-order-id="${oid}" role="menu">
      <button type="button" class="wb-fbs-row-menu-item" role="menuitem"
              onclick="wbFbsPrintOneOrderSticker(${oid})">Стикер товара</button>
      <button type="button" class="wb-fbs-row-menu-item" role="menuitem"
              onclick="wbFbsPrintSupplySticker()">Стикер поставки</button>
      <button type="button" class="wb-fbs-row-menu-item" role="menuitem"
              onclick="wbFbsPrintBoxStickers()">Стикеры коробов</button>
    </div>
  </div>`;
}

function _wbFbsQrMenuIconHtml() {
  return `<span class="wb-fbs-menu-ico wb-fbs-menu-ico-qr" aria-hidden="true">
    <svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M2 2h5v5H2V2zm1.5 1.5v2h2v-2h-2zM11 2h5v5h-5V2zm1.5 1.5v2h2v-2h-2zM2 11h5v5H2v-5zm1.5 1.5v2h2v-2h-2z" fill="currentColor"/>
      <path d="M11 11h2v2h-2v-2zm3 0h2v2h-2v-2zm-3 3h2v2h-2v-2zm3 0h1v1h-1v-1zm1 1h1v2h-2v-1h1v-1z" fill="currentColor"/>
    </svg>
  </span>`;
}

function _wbFbsSupplyRowActionsHtml(supplyId) {
  const sid = String(supplyId || "").trim();
  if (!sid) return "";
  // На «На сборке» меню нет: WB API не умеет переименовывать поставки.
  if (wbFbsState.tab === "assembly") return "";
  const safeKey = sid.replace(/[^a-zA-Z0-9_-]/g, "_");
  return `<div class="wb-fbs-row-menu-wrap">
    <button type="button" class="icon-btn secondary wb-fbs-row-menu-btn" title="Действия"
            onclick="toggleWbFbsRowMenu(event, '${_wbFbsEsc(safeKey)}')" aria-haspopup="menu">⋮</button>
    <div id="wbFbsRowMenu_${safeKey}" class="wb-fbs-row-menu" data-order-id="${_wbFbsEsc(safeKey)}" data-supply-id="${_wbFbsEsc(sid)}" role="menu">
      <button type="button" class="wb-fbs-row-menu-item" role="menuitem"
              onclick="wbFbsOpenSupplyQr('${_wbFbsEsc(sid)}').catch((e)=>alert(e.message||e))">
        ${_wbFbsQrMenuIconHtml()}
        Напечатать QR-код поставки
      </button>
    </div>
  </div>`;
}

const wbFbsDetailState = {
  supplyId: "",
  supply: null,
  selected: new Set(),
  trbxBusy: false,
  trbxBoxes: [],
  trbxRemaining: 0,
  trbxLoaded: false,
  trbxLoading: false,
  /** False until supply detail (orders) finished loading. */
  ordersReady: false,
};

const _WB_FBS_DETAIL_ACTION_IDS = [
  "wbFbsSupplyDetailPickingBtn",
  "wbFbsSupplyDetailPickingMenuBtn",
  "wbFbsSupplyDetailStickersBtn",
  "wbFbsSupplyDetailStickersMenuBtn",
  "wbFbsSupplyDetailKizBtn",
  "wbFbsSupplyDetailKizRefreshBtn",
  "wbFbsSupplyDetailPickVerifyBtn",
  "wbFbsSupplyDetailTrbxBtn",
  "wbFbsSupplyDetailCancelledBtn",
];

function _wbFbsSupplyDetailActionsReady() {
  return !!wbFbsDetailState.ordersReady;
}

/**
 * Disable supply-detail action buttons until orders are loaded.
 * Uses aria-disabled (not native disabled) so the hover tooltip still works.
 */
function _wbFbsSupplyDetailSetActionsReady(ready) {
  wbFbsDetailState.ordersReady = !!ready;
  const tip = "Дождитесь загрузки заказов";
  _WB_FBS_DETAIL_ACTION_IDS.forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (!ready) {
      if (el.dataset.waitTitleSaved === undefined) {
        el.dataset.waitTitleSaved = el.getAttribute("title") || "";
      }
      el.setAttribute("aria-disabled", "true");
      el.classList.add("is-wait-orders");
      el.setAttribute("title", tip);
      el.tabIndex = -1;
    } else {
      el.removeAttribute("aria-disabled");
      el.classList.remove("is-wait-orders");
      el.removeAttribute("tabindex");
      const saved = el.dataset.waitTitleSaved;
      if (saved !== undefined) {
        if (saved) el.setAttribute("title", saved);
        else el.removeAttribute("title");
        delete el.dataset.waitTitleSaved;
      }
    }
  });
  if (!ready) {
    _wbFbsClosePickingMenu();
    _wbFbsCloseStickersMenu();
  }
  _wbFbsSyncPickVerifyBtn();
}

function _wbFbsSupplyDetailResetSearch() {
  const search = document.getElementById("wbFbsSupplyDetailSearchFilter");
  if (search) search.value = "";
}

function closeWbFbsSupplyDetailModal() {
  // Nested modals first — abort supply close if operator keeps unsaved edits.
  // Marking close is async (awaits silent local autosave); chain the rest.
  if (_wbFbsKizModalIsOpen()) {
    return Promise.resolve(closeWbFbsKizModal()).then((ok) => {
      if (!ok) return;
      return closeWbFbsSupplyDetailModal();
    });
  }
  if (_wbFbsPickModalIsOpen()) {
    return Promise.resolve(closeWbFbsPickVerifyModal()).then((ok) => {
      if (!ok) return;
      return closeWbFbsSupplyDetailModal();
    });
  }

  wbFbsDetailState.supplyId = "";
  wbFbsDetailState.supply = null;
  wbFbsDetailState.selected.clear();
  wbFbsDetailState.trbxBusy = false;
  wbFbsDetailState.trbxBoxes = [];
  wbFbsDetailState.trbxRemaining = 0;
  wbFbsDetailState.trbxLoaded = false;
  wbFbsDetailState.trbxLoading = false;
  _wbFbsSupplyDetailSetActionsReady(false);
  _wbFbsKizSplitSetTone("");
  _wbFbsCloseRowMenus();
  _wbFbsClosePickingMenu();
  _wbFbsCloseStickersMenu();
  _wbFbsSupplyDetailResetSearch();
  closeWbFbsCreateTrbxModal();
  closeWbFbsCancelledOrdersModal();
  closeWbFbsStickersByCategoryModal();
  setModalVisibility("wbFbsSupplyDetailModal", false);
}
window.closeWbFbsSupplyDetailModal = closeWbFbsSupplyDetailModal;

function _wbFbsTrbxMaxAmount() {
  // Prefer live remaining from last WB list; fall back to supply detail meta.
  if (wbFbsDetailState.trbxLoaded) {
    return Math.max(0, Math.min(1000, Number(wbFbsDetailState.trbxRemaining) || 0));
  }
  const supply = wbFbsDetailState.supply || {};
  const orders = Number(supply.order_count || 0);
  const existing = Number(supply.boxes_count || 0);
  // WB: total boxes ≤ items in supply + 1 (remaining = limit − already created).
  const maxTotal = Math.max(1, orders + 1);
  return Math.max(0, Math.min(1000, maxTotal - existing));
}

function _wbFbsCreateTrbxSetInfo(text, kind = "") {
  const el = document.getElementById("wbFbsCreateTrbxInfo");
  if (!el) return;
  const msg = String(text || "").trim();
  el.hidden = !msg;
  el.textContent = msg;
  el.classList.toggle("is-error", kind === "error");
  el.classList.toggle("is-ok", kind === "ok");
}

function _wbFbsTrbxSetCreateEnabled(enabled) {
  const input = document.getElementById("wbFbsCreateTrbxAmount");
  const steppers = document.querySelectorAll(".wb-fbs-trbx-stepper-btn");
  steppers.forEach((btn) => { btn.disabled = !enabled || !!wbFbsDetailState.trbxBusy; });
  if (input) input.disabled = !enabled || !!wbFbsDetailState.trbxBusy;
}

function _wbFbsTrbxAmountValue() {
  const input = document.getElementById("wbFbsCreateTrbxAmount");
  if (!input) return 0;
  const raw = String(input.value || "").trim();
  if (!raw) return 0;
  const n = Math.floor(Number(raw));
  return Number.isFinite(n) ? n : 0;
}

function wbFbsTrbxAmountChanged() {
  const input = document.getElementById("wbFbsCreateTrbxAmount");
  const btn = document.getElementById("wbFbsCreateTrbxSubmitBtn");
  if (!input) return;
  const raw = String(input.value || "").trim();
  const max = _wbFbsTrbxMaxAmount();
  let n = 0;
  if (raw !== "") {
    n = Math.floor(Number(raw));
    if (!Number.isFinite(n) || n < 0) n = 0;
    if (n > max) n = max;
    // Keep empty for 0 so "0" stays a placeholder, not a typed value.
    input.value = n > 0 ? String(n) : "";
  }
  const closed = !!(wbFbsDetailState.supply || {}).done;
  const canCreate = !closed
    && max >= 1
    && !wbFbsDetailState.trbxBusy
    && !wbFbsDetailState.trbxLoading;
  _wbFbsTrbxSetCreateEnabled(canCreate);
  if (btn) btn.disabled = n < 1 || !canCreate;
}
window.wbFbsTrbxAmountChanged = wbFbsTrbxAmountChanged;

function wbFbsTrbxStep(delta) {
  const input = document.getElementById("wbFbsCreateTrbxAmount");
  if (!input || wbFbsDetailState.trbxBusy || input.disabled) return;
  const cur = _wbFbsTrbxAmountValue();
  const next = Math.max(0, cur + Number(delta || 0));
  input.value = next > 0 ? String(next) : "";
  wbFbsTrbxAmountChanged();
}
window.wbFbsTrbxStep = wbFbsTrbxStep;

function _wbFbsTrbxModalOpen() {
  const modal = document.getElementById("wbFbsCreateTrbxModal");
  return !!(modal && !modal.classList.contains("hidden"));
}

function _wbFbsTrbxApiError(data, status) {
  const d = data && data.detail;
  if (typeof d === "string" && d.trim()) return d;
  if (Array.isArray(d) && d.length) {
    const first = d[0];
    if (typeof first === "string") return first;
    if (first && typeof first.msg === "string") return first.msg;
  }
  if (data && typeof data.message === "string" && data.message.trim()) return data.message;
  return `Ошибка ${status || ""}`.trim();
}

function _wbFbsTrbxApplyListPayload(data) {
  if (!data || typeof data !== "object") return;
  const remaining = Math.max(0, Number(data.remaining || 0));
  wbFbsDetailState.trbxRemaining = remaining;
  wbFbsDetailState.trbxLoaded = true;
  _wbFbsRenderTrbxBoxesList(data.boxes || []);
  if (wbFbsDetailState.supply) {
    wbFbsDetailState.supply.boxes_count = Number(data.boxes_count || 0);
    if (Number.isFinite(Number(data.order_count))) {
      wbFbsDetailState.supply.order_count = Number(data.order_count);
    }
  }
  const input = document.getElementById("wbFbsCreateTrbxAmount");
  if (input) input.max = String(remaining);
  // Refresh chips in the supply modal without reopening/covering this modal.
  try {
    if (wbFbsDetailState.supply) renderWbFbsSupplyDetail(wbFbsDetailState.supply);
  } catch (_) {}
}

function _wbFbsRenderTrbxBoxesList(boxes) {
  const section = document.getElementById("wbFbsTrbxPrintSection");
  const list = document.getElementById("wbFbsTrbxBoxesList");
  const printAll = document.getElementById("wbFbsTrbxPrintAllBtn");
  const deleteAll = document.getElementById("wbFbsTrbxDeleteAllBtn");
  if (!section || !list) return;
  const items = Array.isArray(boxes) ? boxes : [];
  wbFbsDetailState.trbxBoxes = items.map((b) => ({
    id: String((b && b.id) || "").trim(),
  })).filter((b) => b.id);
  if (!wbFbsDetailState.trbxBoxes.length) {
    section.hidden = true;
    list.innerHTML = "";
    if (printAll) printAll.disabled = true;
    if (deleteAll) deleteAll.disabled = true;
    return;
  }
  section.hidden = false;
  const printSupply = document.getElementById("wbFbsTrbxPrintSupplyQrBtn");
  if (printAll) printAll.disabled = !!wbFbsDetailState.trbxBusy;
  if (printSupply) printSupply.disabled = !!wbFbsDetailState.trbxBusy;
  if (deleteAll) deleteAll.disabled = !!wbFbsDetailState.trbxBusy;
  list.innerHTML = wbFbsDetailState.trbxBoxes.map((b) => {
    const safeAttr = _wbFbsEsc(b.id);
    const safeJs = JSON.stringify(b.id);
    const busy = wbFbsDetailState.trbxBusy ? "disabled" : "";
    return `<tr>
      <td><span class="wb-fbs-trbx-box-id">${safeAttr}</span></td>
      <td class="wb-fbs-trbx-boxes-col-act">
        <div class="wb-fbs-trbx-box-actions">
          <button type="button" class="wb-fbs-trbx-box-print" title="Печать QR"
                  aria-label="Печать ${safeAttr}" ${busy}
                  onclick='wbFbsPrintTrbxStickers(${safeJs})'>⎙</button>
          <button type="button" class="wb-fbs-trbx-box-delete" title="Удалить короб"
                  aria-label="Удалить ${safeAttr}" ${busy}
                  onclick='wbFbsDeleteTrbxBox(${safeJs})'>✕</button>
        </div>
      </td>
    </tr>`;
  }).join("");
}

async function loadWbFbsTrbxBoxes({ keepInfo = false } = {}) {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId) return null;
  wbFbsDetailState.trbxLoading = true;
  wbFbsTrbxAmountChanged();
  if (!keepInfo) _wbFbsCreateTrbxSetInfo("Загружаем грузоместа с портала…");
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/trbx?${params}`
    );
    const data = await res.json().catch(() => ({}));
    if (!_wbFbsTrbxModalOpen() || wbFbsDetailState.supplyId !== sid) return null;
    if (!res.ok || !data.ok) {
      throw new Error(_wbFbsTrbxApiError(data, res.status));
    }
    _wbFbsTrbxApplyListPayload(data);
    const remaining = Math.max(0, Number(data.remaining || 0));
    if (!keepInfo) {
      if (remaining < 1) {
        _wbFbsCreateTrbxSetInfo(
          `Лимит грузомест достигнут (макс. ${Number(data.max_total || 0)} = заказы+1)`
        );
      } else {
        _wbFbsCreateTrbxSetInfo(`Можно добавить ещё: ${remaining}`);
      }
    }
    return data;
  } catch (e) {
    if (_wbFbsTrbxModalOpen() && wbFbsDetailState.supplyId === sid && !keepInfo) {
      _wbFbsCreateTrbxSetInfo(String(e.message || e), "error");
    }
    throw e;
  } finally {
    if (wbFbsDetailState.supplyId === sid) {
      wbFbsDetailState.trbxLoading = false;
      wbFbsTrbxAmountChanged();
    }
  }
}

function openWbFbsCreateTrbxModal() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady()) return;
  const supply = wbFbsDetailState.supply || {};
  const closed = !!supply.done;
  const modal = document.getElementById("wbFbsCreateTrbxModal");
  if (!modal) return;
  wbFbsDetailState.trbxBoxes = [];
  wbFbsDetailState.trbxLoaded = false;
  wbFbsDetailState.trbxRemaining = 0;
  const input = document.getElementById("wbFbsCreateTrbxAmount");
  if (input) {
    input.value = "";
    input.max = String(_wbFbsTrbxMaxAmount());
  }
  _wbFbsRenderTrbxBoxesList([]);
  if (closed) {
    _wbFbsCreateTrbxSetInfo(
      "Поставка уже закрыта — создать грузоместа нельзя. Можно распечатать QR существующих.",
      "error",
    );
  } else {
    _wbFbsCreateTrbxSetInfo("Загружаем грузоместа с портала…");
  }
  wbFbsTrbxAmountChanged();
  // Disable create controls on closed supplies (print/delete still available when boxes load).
  if (closed) _wbFbsTrbxSetCreateEnabled(false);
  modal.classList.remove("hidden");
  modal.style.display = "flex";
  modal.setAttribute("aria-hidden", "false");
  loadWbFbsTrbxBoxes({ keepInfo: closed }).catch(() => {});
}
window.openWbFbsCreateTrbxModal = openWbFbsCreateTrbxModal;

function closeWbFbsCreateTrbxModal() {
  if (wbFbsDetailState.trbxBusy) return;
  closeWbFbsTrbxDeleteAllConfirm();
  const modal = document.getElementById("wbFbsCreateTrbxModal");
  if (modal) {
    modal.classList.add("hidden");
    modal.style.display = "none";
  }
  _wbFbsCreateTrbxSetInfo("");
  wbFbsDetailState.trbxBoxes = [];
  wbFbsDetailState.trbxLoaded = false;
  wbFbsDetailState.trbxRemaining = 0;
  const list = document.getElementById("wbFbsTrbxBoxesList");
  if (list) list.innerHTML = "";
  const section = document.getElementById("wbFbsTrbxPrintSection");
  if (section) section.hidden = true;
}
window.closeWbFbsCreateTrbxModal = closeWbFbsCreateTrbxModal;

function wbFbsPrintTrbxStickers(boxId) {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId) return;
  const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
  const one = String(boxId || "").trim();
  if (one) params.set("box_ids", one);
  const url =
    `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/trbx/stickers-print?${params}`;
  const win = window.open(url, "_blank");
  if (!win) alert("Разрешите всплывающие окна для печати QR грузомест");
}
window.wbFbsPrintTrbxStickers = wbFbsPrintTrbxStickers;

async function wbFbsPrintSupplyQrFromTrbx() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid) return;
  const btn = document.getElementById("wbFbsTrbxPrintSupplyQrBtn");
  if (btn) btn.disabled = true;
  try {
    await wbFbsOpenSupplyQr(sid);
  } catch (e) {
    const msg = String(e.message || e || "").trim()
      || "Не удалось сформировать QR-код поставки";
    if (_wbFbsTrbxModalOpen()) _wbFbsCreateTrbxSetInfo(msg, "error");
    else alert(msg);
  } finally {
    if (btn && !wbFbsDetailState.trbxBusy) btn.disabled = false;
  }
}
window.wbFbsPrintSupplyQrFromTrbx = wbFbsPrintSupplyQrFromTrbx;

async function _wbFbsDeleteTrbxBoxes(boxIds, { okMessage = "Грузоместа удалены" } = {}) {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  const ids = (Array.isArray(boxIds) ? boxIds : [])
    .map((x) => String(x || "").trim())
    .filter(Boolean);
  if (!sid || !ids.length || !wbFbsState.sourceId || wbFbsDetailState.trbxBusy) return false;
  wbFbsDetailState.trbxBusy = true;
  _wbFbsTrbxSetCreateEnabled(false);
  _wbFbsRenderTrbxBoxesList(wbFbsDetailState.trbxBoxes);
  _wbFbsCreateTrbxSetInfo(ids.length === 1 ? "Удаляем грузоместо…" : "Удаляем грузоместа…");
  try {
    const res = await fetch(`/api/wb-fbs/supplies/${encodeURIComponent(sid)}/trbx`, {
      method: "DELETE",
      headers: jsonHeaders(),
      body: JSON.stringify({ source_id: wbFbsState.sourceId, box_ids: ids }),
    });
    const data = await res.json().catch(() => ({}));
    if (!_wbFbsTrbxModalOpen() || wbFbsDetailState.supplyId !== sid) return false;
    if (!res.ok || !data.ok) {
      throw new Error(_wbFbsTrbxApiError(data, res.status));
    }
    _wbFbsTrbxApplyListPayload(data);
    _wbFbsCreateTrbxSetInfo(okMessage, "ok");
    return true;
  } catch (e) {
    if (_wbFbsTrbxModalOpen() && wbFbsDetailState.supplyId === sid) {
      _wbFbsCreateTrbxSetInfo(String(e.message || e), "error");
    }
    return false;
  } finally {
    wbFbsDetailState.trbxBusy = false;
    if (_wbFbsTrbxModalOpen() && wbFbsDetailState.supplyId === sid) {
      wbFbsTrbxAmountChanged();
      _wbFbsRenderTrbxBoxesList(wbFbsDetailState.trbxBoxes);
    }
  }
}

async function wbFbsDeleteTrbxBox(boxId) {
  const bid = String(boxId || "").trim();
  if (!bid) return;
  if (!confirm(`Удалить грузоместо ${bid}?`)) return;
  await _wbFbsDeleteTrbxBoxes([bid], { okMessage: "Грузоместо удалено" });
}
window.wbFbsDeleteTrbxBox = wbFbsDeleteTrbxBox;

function openWbFbsTrbxDeleteAllConfirm() {
  if (wbFbsDetailState.trbxBusy || !wbFbsDetailState.trbxBoxes.length) return;
  const modal = document.getElementById("wbFbsTrbxDeleteAllConfirmModal");
  if (!modal) return;
  modal.classList.remove("hidden");
  modal.style.display = "flex";
  modal.setAttribute("aria-hidden", "false");
}
window.openWbFbsTrbxDeleteAllConfirm = openWbFbsTrbxDeleteAllConfirm;

function closeWbFbsTrbxDeleteAllConfirm() {
  const modal = document.getElementById("wbFbsTrbxDeleteAllConfirmModal");
  if (!modal) return;
  modal.classList.add("hidden");
  modal.style.display = "none";
  modal.setAttribute("aria-hidden", "true");
  const yesBtn = document.getElementById("wbFbsTrbxDeleteAllConfirmYesBtn");
  if (yesBtn) yesBtn.disabled = false;
}
window.closeWbFbsTrbxDeleteAllConfirm = closeWbFbsTrbxDeleteAllConfirm;

async function confirmWbFbsDeleteAllTrbx() {
  const ids = (wbFbsDetailState.trbxBoxes || []).map((b) => b.id).filter(Boolean);
  if (!ids.length || wbFbsDetailState.trbxBusy) {
    closeWbFbsTrbxDeleteAllConfirm();
    return;
  }
  const yesBtn = document.getElementById("wbFbsTrbxDeleteAllConfirmYesBtn");
  if (yesBtn) yesBtn.disabled = true;
  closeWbFbsTrbxDeleteAllConfirm();
  await _wbFbsDeleteTrbxBoxes(ids, { okMessage: "Все грузоместа удалены" });
}
window.confirmWbFbsDeleteAllTrbx = confirmWbFbsDeleteAllTrbx;

async function submitWbFbsCreateTrbx() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || wbFbsDetailState.trbxBusy) return;
  const amount = _wbFbsTrbxAmountValue();
  if (amount < 1) return;
  const submitBtn = document.getElementById("wbFbsCreateTrbxSubmitBtn");
  wbFbsDetailState.trbxBusy = true;
  if (submitBtn) submitBtn.disabled = true;
  _wbFbsTrbxSetCreateEnabled(false);
  _wbFbsCreateTrbxSetInfo("Создаём грузоместа…");
  try {
    const res = await fetch(`/api/wb-fbs/supplies/${encodeURIComponent(sid)}/trbx`, {
      method: "POST",
      headers: jsonHeaders(),
      body: JSON.stringify({ source_id: wbFbsState.sourceId, amount }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data.ok) {
      throw new Error(_wbFbsTrbxApiError(data, res.status));
    }
    // Defensive: never auto-download stickers from create response.
    // User may have closed the modal while the request was in flight.
    if (!_wbFbsTrbxModalOpen() || wbFbsDetailState.supplyId !== sid) return;
    const input = document.getElementById("wbFbsCreateTrbxAmount");
    if (input) input.value = "";
    _wbFbsCreateTrbxSetInfo("Грузоместа на портале созданы", "ok");
    try {
      await loadWbFbsTrbxBoxes({ keepInfo: true });
    } catch (_) {}
    // Do NOT reopen/refetch supply-detail modal here: same z-index overlays
    // made the create modal look closed. Meta chips update via list payload.
    if (wbFbsState.tab === "assembly") {
      try { loadWbFbsOrders(false); } catch (_) {}
    }
  } catch (e) {
    if (_wbFbsTrbxModalOpen() && wbFbsDetailState.supplyId === sid) {
      _wbFbsCreateTrbxSetInfo(String(e.message || e), "error");
    }
  } finally {
    wbFbsDetailState.trbxBusy = false;
    if (_wbFbsTrbxModalOpen() && wbFbsDetailState.supplyId === sid) {
      wbFbsTrbxAmountChanged();
      _wbFbsRenderTrbxBoxesList(wbFbsDetailState.trbxBoxes);
    }
  }
}
window.submitWbFbsCreateTrbx = submitWbFbsCreateTrbx;

async function openWbFbsSupplyDetailModal(supplyId) {
  _wbFbsCloseRowMenus();
  const sid = String(supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId) return;
  wbFbsDetailState.supplyId = sid;
  wbFbsDetailState.selected.clear();
  _wbFbsSupplyDetailSetActionsReady(false);
  _wbFbsKizSplitSetTone("");
  const kizSplitOpen = document.getElementById("wbFbsKizSplit");
  if (kizSplitOpen) kizSplitOpen.hidden = true;
  const pickBtnOpen = document.getElementById("wbFbsSupplyDetailPickVerifyBtn");
  if (pickBtnOpen) {
    pickBtnOpen.hidden = true;
    pickBtnOpen.style.display = "none";
  }
  _wbFbsSupplyDetailResetSearch();
  setModalVisibility("wbFbsSupplyDetailModal", true);
  const title = document.getElementById("wbFbsSupplyDetailTitle");
  const wh = document.getElementById("wbFbsSupplyDetailWarehouse");
  const meta = document.getElementById("wbFbsSupplyDetailMeta");
  const info = document.getElementById("wbFbsSupplyDetailInfo");
  const tbody = document.getElementById("wbFbsSupplyDetailTbody");
  if (title) title.textContent = "Загрузка…";
  if (wh) wh.textContent = "—";
  if (meta) meta.innerHTML = "";
  if (info) {
    info.hidden = true;
    info.textContent = "";
  }
  if (tbody) tbody.innerHTML = `<tr><td colspan="4" class="wb-fbs-empty">Загрузка…</td></tr>`;
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(`/api/wb-fbs/supplies/${encodeURIComponent(sid)}/detail?${params}`);
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    if (wbFbsDetailState.supplyId !== sid) return;
    wbFbsDetailState.supply = data;
    renderWbFbsSupplyDetail(data);
    _wbFbsSupplyDetailSetActionsReady(true);
  } catch (e) {
    if (wbFbsDetailState.supplyId === sid) {
      _wbFbsSupplyDetailSetActionsReady(false);
    }
    if (info) {
      info.hidden = false;
      info.textContent = String(e.message || e);
    }
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="4" class="wb-fbs-empty" style="color:#b91c1c">${_wbFbsEsc(e.message || e)}</td></tr>`;
    }
  }
}
window.openWbFbsSupplyDetailModal = openWbFbsSupplyDetailModal;

function renderWbFbsSupplyDetail(data) {
  const supply = data || wbFbsDetailState.supply;
  if (!supply) return;
  if (data) wbFbsDetailState.supply = data;
  const title = document.getElementById("wbFbsSupplyDetailTitle");
  const wh = document.getElementById("wbFbsSupplyDetailWarehouse");
  const meta = document.getElementById("wbFbsSupplyDetailMeta");
  const tbody = document.getElementById("wbFbsSupplyDetailTbody");
  const sid = String(supply.supply_id || "").trim();
  if (title) title.textContent = supply.name || (`Поставка ${sid}`);
  if (wh) wh.textContent = String(supply.warehouse_label || "—").trim() || "—";
  if (meta) {
    const chips = [];
    if (supply.cargo_label) chips.push(`<span class="wb-fbs-sd-chip">${_wbFbsEsc(supply.cargo_label)}</span>`);
    chips.push(`<span class="wb-fbs-sd-chip">Заказы ${_wbFbsEsc(supply.order_count || 0)}</span>`);
    chips.push(`<span class="wb-fbs-sd-chip">Грузоместа ${_wbFbsEsc(supply.boxes_count || 0)}</span>`);
    chips.push(`<span class="wb-fbs-sd-chip">Создана ${_wbFbsEsc(supply.created_date || "—")}</span>`);
    if (sid) {
      chips.push(
        `<span class="wb-fbs-sd-chip wb-fbs-sd-chip-qr">` +
          `<span class="wb-fbs-sd-qr-text">QR поставки ${_wbFbsEsc(sid)}</span>` +
          `<button type="button" class="wb-fbs-sd-qr-print" ` +
          `title="Распечатать QR-код поставки" ` +
          `aria-label="Распечатать QR-код поставки ${_wbFbsEsc(sid)}" ` +
          `onclick="wbFbsOpenSupplyQr('${_wbFbsEsc(sid)}').catch((e)=>alert(e.message||e))">` +
          `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">` +
          `<path d="M4 6V2.5A.5.5 0 0 1 4.5 2h7a.5.5 0 0 1 .5.5V6M4 12H3a1.5 1.5 0 0 1-1.5-1.5v-3A1.5 1.5 0 0 1 3 6h10a1.5 1.5 0 0 1 1.5 1.5v3A1.5 1.5 0 0 1 13 12h-1" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/>` +
          `<path d="M4 10.5h8V14a.5.5 0 0 1-.5.5h-7A.5.5 0 0 1 4 14v-3.5z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/>` +
          `<path d="M11.5 8.25h.01" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>` +
          `</svg>` +
          `</button>` +
        `</span>`
      );
    }
    meta.innerHTML = chips.join("");
  }
  const allOrders = Array.isArray(supply.orders) ? supply.orders : [];
  const searchQ = document.getElementById("wbFbsSupplyDetailSearchFilter")?.value || "";
  const orders = String(searchQ || "").trim()
    ? allOrders.filter((o) => _wbFbsKizRowMatchesSearch(o, searchQ))
    : allOrders;
  const kizSplit = document.getElementById("wbFbsKizSplit");
  if (kizSplit) {
    // Show Маркировка + refresh only when at least one order accepts sgtin/КИЗ.
    const needsKiz = allOrders.some((o) => o && o.kiz_required);
    kizSplit.hidden = !needsKiz;
    if (!needsKiz) _wbFbsKizSplitSetTone("");
  }
  _wbFbsSyncPickVerifyBtn();
  const trbxBtn = document.getElementById("wbFbsSupplyDetailTrbxBtn");
  if (trbxBtn) {
    // Always show: owner needs print/create even when WB already has boxes.
    // Hiding on done made the button disappear for the main account while
    // employees (fewer toolbar buttons) still saw it — and blocked print.
    trbxBtn.hidden = false;
    trbxBtn.style.display = "";
    trbxBtn.style.visibility = "visible";
    const closed = !!supply.done;
    trbxBtn.title = closed
      ? "Грузоместа: просмотр и печать QR (поставка уже закрыта — создать нельзя)"
      : "Создать грузоместа (короба) для ПВЗ";
  }
  if (!tbody) return;
  if (!allOrders.length) {
    tbody.innerHTML = `<tr><td colspan="4" class="wb-fbs-empty">В поставке нет заказов</td></tr>`;
    return;
  }
  if (!orders.length) {
    tbody.innerHTML = `<tr><td colspan="4" class="wb-fbs-empty">Нет заказов по выбранному фильтру</td></tr>`;
    const selAllEmpty = document.getElementById("wbFbsSupplyDetailSelectAll");
    if (selAllEmpty) {
      selAllEmpty.checked = false;
      selAllEmpty.indeterminate = false;
    }
    return;
  }
  tbody.innerHTML = orders.map((o) => {
    const oid = Number(o.order_id);
    const checked = wbFbsDetailState.selected.has(oid) ? "checked" : "";
    const photo = o.product_photo
      ? `<img class="wb-fbs-product-photo" src="${_wbFbsEsc(o.product_photo)}" alt="" width="72" height="72" loading="lazy">`
      : `<span class="wb-fbs-product-ph" aria-hidden="true"></span>`;
    const badges = [];
    if (o.created_ago) badges.push(`<span class="wb-fbs-badge time">${_wbFbsEsc(o.created_ago)}</span>`);
    if (o.pickup_allowed) badges.push(`<span class="wb-fbs-badge pvz">Можно в ПВЗ</span>`);
    const barcodes = Array.isArray(o.barcodes)
      ? o.barcodes
      : (Array.isArray(o.skus) ? o.skus : []);
    const barcodeHtml = barcodes.length
      ? `<div class="wb-fbs-barcodes" title="Штрихкод товара">${barcodes.map((b) =>
          `<div class="wb-fbs-barcode">${_wbFbsEsc(b)}</div>`
        ).join("")}</div>`
      : "";
    const cancelBadgeHtml = _wbFbsKizCancelBadgeHtml(o);
    // КИЗ: empty (gray) → pending (на проверке) → ok (green) / error (red).
    const kizHtml = o.kiz_required ? _wbFbsKizBadgeHtml(o) : "";
    const safeKey = `sd_${oid}`;
    const stickerHtml = _wbFbsKizStickerHtml(o);
    return `<tr class="wb-fbs-sd-click-row">
      <td><input type="checkbox" class="wb-fbs-sd-cb" data-order-id="${oid}" ${checked} onchange="onWbFbsDetailCheckboxChange()" /></td>
      <td>
        <div class="wb-fbs-sd-order-id">${_wbFbsEsc(oid)}</div>
        <div class="wb-fbs-sd-sticker">${stickerHtml}</div>
        <div class="wb-fbs-order-meta">от ${_wbFbsEsc(o.created_date || "—")}</div>
        ${badges.length ? `<div class="wb-fbs-badges">${badges.join("")}</div>` : ""}
      </td>
      <td>
        <div class="wb-fbs-product">
          ${photo}
          <div class="wb-fbs-product-text">
            <div class="wb-fbs-product-name" title="${_wbFbsEsc(o.product_name || o.article || "")}">${_wbFbsEsc(o.product_name || o.article || "—")}</div>
            <div class="wb-fbs-product-sub">Арт. ${_wbFbsEsc(o.article || "—")}${o.nm_id ? " · nmId " + _wbFbsEsc(o.nm_id) : ""}</div>
            ${barcodeHtml}
            ${cancelBadgeHtml}
            ${kizHtml}
          </div>
        </div>
      </td>
      <td>
        <div class="wb-fbs-row-menu-wrap">
          <button type="button" class="icon-btn secondary wb-fbs-row-menu-btn" title="Действия"
                  onclick="toggleWbFbsRowMenu(event, '${safeKey}')" aria-haspopup="menu">⋮</button>
          <div id="wbFbsRowMenu_${safeKey}" class="wb-fbs-row-menu" data-order-id="${safeKey}" role="menu">
            <button type="button" class="wb-fbs-row-menu-item" role="menuitem"
                    onclick="wbFbsPrintOneOrderStickerFromDetail(${oid})">
              ${_wbFbsQrMenuIconHtml()}
              Напечатать стикер
            </button>
          </div>
        </div>
      </td>
    </tr>`;
  }).join("");
  const selAll = document.getElementById("wbFbsSupplyDetailSelectAll");
  if (selAll) {
    const ids = orders.map((x) => Number(x.order_id));
    selAll.checked = ids.length > 0 && ids.every((id) => wbFbsDetailState.selected.has(id));
    selAll.indeterminate = !selAll.checked && ids.some((id) => wbFbsDetailState.selected.has(id));
  }
}
window.renderWbFbsSupplyDetail = renderWbFbsSupplyDetail;

function onWbFbsDetailCheckboxChange() {
  document.querySelectorAll(".wb-fbs-sd-cb").forEach((cb) => {
    const id = Number(cb.dataset.orderId);
    if (!Number.isFinite(id)) return;
    if (cb.checked) wbFbsDetailState.selected.add(id);
    else wbFbsDetailState.selected.delete(id);
  });
  const selAll = document.getElementById("wbFbsSupplyDetailSelectAll");
  const orders = Array.isArray(wbFbsDetailState.supply?.orders) ? wbFbsDetailState.supply.orders : [];
  const ids = orders.map((x) => Number(x.order_id));
  if (selAll) {
    selAll.checked = ids.length > 0 && ids.every((id) => wbFbsDetailState.selected.has(id));
    selAll.indeterminate = !selAll.checked && ids.some((id) => wbFbsDetailState.selected.has(id));
  }
}
window.onWbFbsDetailCheckboxChange = onWbFbsDetailCheckboxChange;

function toggleSelectAllWbFbsDetail(checked) {
  wbFbsDetailState.selected.clear();
  document.querySelectorAll(".wb-fbs-sd-cb").forEach((cb) => {
    cb.checked = !!checked;
    const id = Number(cb.dataset.orderId);
    if (checked && Number.isFinite(id)) wbFbsDetailState.selected.add(id);
  });
  const selAll = document.getElementById("wbFbsSupplyDetailSelectAll");
  if (selAll) selAll.indeterminate = false;
}
window.toggleSelectAllWbFbsDetail = toggleSelectAllWbFbsDetail;

function _wbFbsClosePickingMenu() {
  const menu = document.getElementById("wbFbsPickingMenu");
  const caret = document.getElementById("wbFbsSupplyDetailPickingMenuBtn");
  if (menu) menu.hidden = true;
  if (caret) caret.setAttribute("aria-expanded", "false");
}

function toggleWbFbsPickingMenu(event) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  if (!_wbFbsSupplyDetailActionsReady()) return;
  _wbFbsCloseStickersMenu();
  const menu = document.getElementById("wbFbsPickingMenu");
  const caret = document.getElementById("wbFbsSupplyDetailPickingMenuBtn");
  if (!menu || !caret) return;
  const willOpen = menu.hidden;
  menu.hidden = !willOpen;
  caret.setAttribute("aria-expanded", willOpen ? "true" : "false");
}
window.toggleWbFbsPickingMenu = toggleWbFbsPickingMenu;

function wbFbsOpenPickingList(variant) {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady()) return;
  const mode = String(variant || "summary").trim().toLowerCase() === "extended"
    ? "extended"
    : "summary";
  _wbFbsClosePickingMenu();
  const btn = document.getElementById("wbFbsSupplyDetailPickingBtn");
  const caret = document.getElementById("wbFbsSupplyDetailPickingMenuBtn");
  if (btn) btn.disabled = true;
  if (caret) caret.disabled = true;
  // HTML print page (browser CSS). LibreOffice PDF breaks the layout.
  const url =
    `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/picking-list` +
    `?source_id=${wbFbsState.sourceId}&variant=${encodeURIComponent(mode)}`;
  const win = window.open(url, "_blank");
  if (!win) alert("Разрешите всплывающие окна для листа подбора");
  setTimeout(() => {
    if (!_wbFbsSupplyDetailActionsReady()) return;
    if (btn) btn.disabled = false;
    if (caret) caret.disabled = false;
  }, 1500);
}
window.wbFbsOpenPickingList = wbFbsOpenPickingList;

function _wbFbsCloseStickersMenu() {
  const menu = document.getElementById("wbFbsStickersMenu");
  const caret = document.getElementById("wbFbsSupplyDetailStickersMenuBtn");
  if (menu) menu.hidden = true;
  if (caret) caret.setAttribute("aria-expanded", "false");
}

function toggleWbFbsStickersMenu(event) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  if (!_wbFbsSupplyDetailActionsReady()) return;
  _wbFbsClosePickingMenu();
  const menu = document.getElementById("wbFbsStickersMenu");
  const caret = document.getElementById("wbFbsSupplyDetailStickersMenuBtn");
  if (!menu || !caret) return;
  const willOpen = menu.hidden;
  menu.hidden = !willOpen;
  caret.setAttribute("aria-expanded", willOpen ? "true" : "false");
}
window.toggleWbFbsStickersMenu = toggleWbFbsStickersMenu;

function wbFbsOpenStickersPrint(orderIds) {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady()) return;
  _wbFbsCloseStickersMenu();
  const btn = document.getElementById("wbFbsSupplyDetailStickersBtn");
  const caret = document.getElementById("wbFbsSupplyDetailStickersMenuBtn");
  if (btn) btn.disabled = true;
  if (caret) caret.disabled = true;
  const ids = Array.isArray(orderIds)
    ? orderIds.map((x) => Number(x)).filter((n) => Number.isFinite(n) && n > 0)
    : [];
  let url =
    `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/stickers-print` +
    `?source_id=${wbFbsState.sourceId}`;
  if (ids.length) url += `&order_ids=${encodeURIComponent(ids.join(","))}`;
  const win = window.open(url, "_blank");
  if (!win) alert("Разрешите всплывающие окна для стикеров");
  setTimeout(() => {
    if (!_wbFbsSupplyDetailActionsReady()) return;
    if (btn) btn.disabled = false;
    if (caret) caret.disabled = false;
  }, 1500);
}
window.wbFbsOpenStickersPrint = wbFbsOpenStickersPrint;

const wbFbsStickersCategoryState = {
  groups: [],
  selected: new Set(),
  loading: false,
};

function _wbFbsStickersCategorySetInfo(text, kind) {
  const el = document.getElementById("wbFbsStickersCategoryInfo");
  if (!el) return;
  const msg = String(text || "").trim();
  if (!msg) {
    el.hidden = true;
    el.textContent = "";
    el.classList.remove("is-error", "is-ok");
    return;
  }
  el.hidden = false;
  el.textContent = msg;
  el.classList.toggle("is-error", kind === "error");
  el.classList.toggle("is-ok", kind === "ok");
}

function _wbFbsStickersCategoryWord(n) {
  const abs = Math.abs(Number(n) || 0) % 100;
  const last = abs % 10;
  if (abs > 10 && abs < 20) return "категорий";
  if (last === 1) return "категория";
  if (last >= 2 && last <= 4) return "категории";
  return "категорий";
}

function _wbFbsStickersCategorySyncUi() {
  const selected = wbFbsStickersCategoryState.selected;
  const selectedCount = selected.size;
  let ordersTotal = 0;
  for (const g of wbFbsStickersCategoryState.groups || []) {
    if (!selected.has(String(g.group_key || ""))) continue;
    const fromIds = Array.isArray(g.order_ids) ? g.order_ids.length : 0;
    const qty = Number(g.qty);
    ordersTotal += Number.isFinite(qty) && qty > 0 ? qty : fromIds;
  }
  const selEl = document.getElementById("wbFbsStickersCategorySelected");
  if (selEl) {
    selEl.textContent =
      `Выбрано: ${selectedCount} ${_wbFbsStickersCategoryWord(selectedCount)}, ` +
      `Заказов: ${ordersTotal} шт.`;
  }
  const printBtn = document.getElementById("wbFbsStickersCategoryPrintBtn");
  if (printBtn) printBtn.disabled = selectedCount <= 0 || wbFbsStickersCategoryState.loading;
  document.querySelectorAll(".wb-fbs-stickers-cat-row").forEach((row) => {
    const key = String(row.dataset.groupKey || "");
    const checked = selected.has(key);
    row.classList.toggle("is-checked", checked);
    const cb = row.querySelector('input[type="checkbox"]');
    if (cb) cb.checked = checked;
    const fillBtn = row.querySelector(".wb-fbs-stickers-cat-fill");
    if (fillBtn) fillBtn.hidden = !checked;
  });
}

function _wbFbsStickersCategoryRender() {
  const box = document.getElementById("wbFbsStickersCategoryList");
  if (!box) return;
  const groups = wbFbsStickersCategoryState.groups || [];
  if (!groups.length) {
    box.innerHTML = `<div class="wb-fbs-empty">${wbFbsStickersCategoryState.loading ? "Загрузка…" : "Нет товаров для печати"}</div>`;
    _wbFbsStickersCategorySyncUi();
    return;
  }
  box.innerHTML = groups.map((g, idx) => {
    const key = _wbFbsEsc(String(g.group_key || ""));
    const name = _wbFbsEsc(String(g.product_name || "—"));
    const qty = Number(g.qty || 0);
    return `<div class="wb-fbs-stickers-cat-row" data-group-key="${key}" data-index="${idx}">
      <input type="checkbox" id="wbFbsStickersCatCb_${idx}"
             onchange="onWbFbsStickersCategoryToggleAt(${idx}, this.checked)" />
      <label for="wbFbsStickersCatCb_${idx}">
        <span class="wb-fbs-stickers-cat-name">${name} — ${qty} шт.</span>
      </label>
      <button type="button" class="wb-fbs-stickers-cat-fill" hidden
              title="Выделить все ниже"
              aria-label="Выделить все ниже"
              onclick="wbFbsStickersCategoryFillDownAt(${idx})">
        <svg width="14" height="14" viewBox="0 0 12 8" fill="none" aria-hidden="true">
          <path d="M1 1.5L6 6.5L11 1.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </button>
    </div>`;
  }).join("");
  _wbFbsStickersCategorySyncUi();
}

function onWbFbsStickersCategoryToggleAt(index, checked) {
  const g = (wbFbsStickersCategoryState.groups || [])[Number(index)];
  const key = String((g && g.group_key) || "");
  if (!key) return;
  if (checked) wbFbsStickersCategoryState.selected.add(key);
  else wbFbsStickersCategoryState.selected.delete(key);
  _wbFbsStickersCategorySyncUi();
}
window.onWbFbsStickersCategoryToggleAt = onWbFbsStickersCategoryToggleAt;

function wbFbsStickersCategorySelectAll() {
  wbFbsStickersCategoryState.selected = new Set(
    (wbFbsStickersCategoryState.groups || []).map((g) => String(g.group_key || "")).filter(Boolean)
  );
  _wbFbsStickersCategorySyncUi();
}
window.wbFbsStickersCategorySelectAll = wbFbsStickersCategorySelectAll;

function wbFbsStickersCategoryClearAll() {
  wbFbsStickersCategoryState.selected.clear();
  _wbFbsStickersCategorySyncUi();
}
window.wbFbsStickersCategoryClearAll = wbFbsStickersCategoryClearAll;

function wbFbsStickersCategoryFillDownAt(index) {
  const groups = wbFbsStickersCategoryState.groups || [];
  const start = Number(index);
  if (!Number.isFinite(start) || start < 0 || start >= groups.length) return;
  for (let i = start; i < groups.length; i += 1) {
    const gk = String(groups[i].group_key || "");
    if (gk) wbFbsStickersCategoryState.selected.add(gk);
  }
  _wbFbsStickersCategorySyncUi();
}
window.wbFbsStickersCategoryFillDownAt = wbFbsStickersCategoryFillDownAt;

async function openWbFbsStickersByCategoryModal() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady()) return;
  _wbFbsCloseStickersMenu();
  if (!document.getElementById("wbFbsStickersCategoryModal")) return;
  setModalVisibility("wbFbsStickersCategoryModal", true);
  wbFbsStickersCategoryState.groups = [];
  wbFbsStickersCategoryState.selected.clear();
  wbFbsStickersCategoryState.loading = true;
  _wbFbsStickersCategorySetInfo("");
  _wbFbsStickersCategoryRender();
  try {
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/sticker-groups?source_id=${wbFbsState.sourceId}`
    );
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    wbFbsStickersCategoryState.groups = Array.isArray(data.groups) ? data.groups : [];
    if (!wbFbsStickersCategoryState.groups.length) {
      _wbFbsStickersCategorySetInfo("В поставке нет товаров для печати", "error");
    } else {
      _wbFbsStickersCategorySetInfo("");
    }
  } catch (e) {
    _wbFbsStickersCategorySetInfo(String(e.message || e), "error");
  } finally {
    wbFbsStickersCategoryState.loading = false;
    _wbFbsStickersCategoryRender();
  }
}
window.openWbFbsStickersByCategoryModal = openWbFbsStickersByCategoryModal;

function closeWbFbsStickersByCategoryModal() {
  setModalVisibility("wbFbsStickersCategoryModal", false);
  wbFbsStickersCategoryState.groups = [];
  wbFbsStickersCategoryState.selected.clear();
  wbFbsStickersCategoryState.loading = false;
  _wbFbsStickersCategorySetInfo("");
  const box = document.getElementById("wbFbsStickersCategoryList");
  if (box) box.innerHTML = "";
  const printBtn = document.getElementById("wbFbsStickersCategoryPrintBtn");
  if (printBtn) printBtn.disabled = true;
}
window.closeWbFbsStickersByCategoryModal = closeWbFbsStickersByCategoryModal;

function wbFbsPrintStickersByCategory() {
  if (wbFbsStickersCategoryState.loading) return;
  const selected = wbFbsStickersCategoryState.selected;
  if (!selected.size) {
    alert("Выберите хотя бы один товар");
    return;
  }
  const orderIds = [];
  for (const g of wbFbsStickersCategoryState.groups || []) {
    if (!selected.has(String(g.group_key || ""))) continue;
    for (const oid of g.order_ids || []) {
      const n = Number(oid);
      if (Number.isFinite(n) && n > 0) orderIds.push(n);
    }
  }
  if (!orderIds.length) {
    alert("У выбранных товаров нет заказов для печати");
    return;
  }
  closeWbFbsStickersByCategoryModal();
  wbFbsOpenStickersPrint(orderIds);
}
window.wbFbsPrintStickersByCategory = wbFbsPrintStickersByCategory;

function openWbFbsSupplyPortal() {
  const sid = String(wbFbsDetailState.supplyId || wbFbsDetailState.supply?.supply_id || "").trim();
  if (!sid) return;
  const url =
    "https://seller.wildberries.ru/marketplace-orders-fbs/supply-detail/packaging" +
    `?supplyID=${encodeURIComponent(sid)}`;
  const win = window.open(url, "_blank", "noopener,noreferrer");
  if (!win) alert("Разрешите всплывающие окна для перехода на портал");
}
window.openWbFbsSupplyPortal = openWbFbsSupplyPortal;

const wbFbsCancelledState = {
  rows: [],
  loading: false,
  lastError: "",
  refreshGen: 0,
};

function _wbFbsCancelledSetInfo(text, kind) {
  const el = document.getElementById("wbFbsCancelledOrdersInfo");
  if (!el) return;
  const msg = String(text || "").trim();
  el.hidden = !msg;
  el.textContent = msg;
  el.classList.toggle("is-ok", !!msg && kind === "ok");
}

function _wbFbsCancelledMergeIntoDetail(rows) {
  const supply = wbFbsDetailState.supply;
  if (!supply || !Array.isArray(supply.orders) || !Array.isArray(rows)) return;
  const byId = new Map();
  rows.forEach((row) => {
    const oid = Number(row?.order_id);
    if (Number.isFinite(oid) && oid > 0) byId.set(oid, row);
  });
  if (!byId.size) return;
  let changed = false;
  supply.orders.forEach((o) => {
    const oid = Number(o?.order_id);
    const upd = byId.get(oid);
    if (!upd) return;
    const label = String(upd.cancel_reason_label || "").trim();
    if (label) {
      o.cancel_reason_label = label;
      changed = true;
    }
    if (upd.supplier_status) o.supplier_status = String(upd.supplier_status);
    if (upd.wb_status) o.wb_status = String(upd.wb_status);
  });
  if (changed) renderWbFbsSupplyDetail(supply);
}

function renderWbFbsCancelledOrdersTable() {
  const tbody = document.getElementById("wbFbsCancelledOrdersTbody");
  if (!tbody) return;
  const rows = Array.isArray(wbFbsCancelledState.rows) ? wbFbsCancelledState.rows : [];
  if (!rows.length) {
    let emptyMsg = "Отменённых заказов в поставке нет";
    if (wbFbsCancelledState.loading) emptyMsg = "Проверяем статусы на Wildberries…";
    else if (wbFbsCancelledState.lastError) emptyMsg = "Не удалось проверить статусы";
    tbody.innerHTML = `<tr><td colspan="2" class="wb-fbs-empty">${emptyMsg}</td></tr>`;
    return;
  }
  tbody.innerHTML = rows.map((r) => {
    const oid = Number(r.order_id);
    const photo = r.product_photo
      ? `<img class="wb-fbs-product-photo" src="${_wbFbsEsc(r.product_photo)}" alt="" width="56" height="56" loading="lazy">`
      : `<span class="wb-fbs-product-ph" aria-hidden="true"></span>`;
    const brandArt = [r.brand, r.article ? `Арт. ${r.article}` : ""].filter(Boolean).join(" · ");
    const barcodes = Array.isArray(r.barcodes)
      ? r.barcodes
      : (Array.isArray(r.skus) ? r.skus : []);
    const barcodeHtml = barcodes.length
      ? `<div class="wb-fbs-kiz-barcodes" title="Штрихкод товара">${barcodes.map((b) =>
          `<div class="wb-fbs-kiz-barcode">${_wbFbsEsc(b)}</div>`
        ).join("")}</div>`
      : "";
    const cancelBadgeHtml = _wbFbsKizCancelBadgeHtml(r);
    const stickerHtml = _wbFbsKizStickerHtml(r);
    return `<tr class="wb-fbs-kiz-row" data-order-id="${oid}">
      <td>
        <div class="wb-fbs-kiz-order-id">${_wbFbsEsc(oid)}</div>
        <div class="wb-fbs-kiz-order-sticker">${stickerHtml}</div>
        <div class="wb-fbs-kiz-order-date">от ${_wbFbsEsc(r.created_date || "—")}</div>
      </td>
      <td>
        <div class="wb-fbs-product">
          ${photo}
          <div class="wb-fbs-product-text">
            <div class="wb-fbs-product-name" title="${_wbFbsEsc(r.product_name || r.article || "")}">${_wbFbsEsc(r.product_name || r.article || "—")}</div>
            <div class="wb-fbs-product-sub">${_wbFbsEsc(brandArt || "—")}</div>
            ${barcodeHtml}
            ${cancelBadgeHtml}
          </div>
        </div>
      </td>
    </tr>`;
  }).join("");
}
window.renderWbFbsCancelledOrdersTable = renderWbFbsCancelledOrdersTable;

async function refreshWbFbsCancelledOrders() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || wbFbsCancelledState.loading) return;
  const refreshGen = Number(wbFbsCancelledState.refreshGen || 0) + 1;
  wbFbsCancelledState.refreshGen = refreshGen;
  wbFbsCancelledState.loading = true;
  wbFbsCancelledState.lastError = "";
  const btn = document.getElementById("wbFbsCancelledOrdersRefreshBtn");
  if (btn) btn.disabled = true;
  _wbFbsCancelledSetInfo("");
  if (!wbFbsCancelledState.rows.length) {
    renderWbFbsCancelledOrdersTable();
  }
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/cancelled?${params}`
    );
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data.ok === false) {
      const detail = data.detail;
      const msg = Array.isArray(detail)
        ? (detail.map((x) => x?.msg || x).filter(Boolean).join("; ") || `Ошибка ${res.status}`)
        : (detail || `Ошибка ${res.status}`);
      throw new Error(msg);
    }
    if (wbFbsCancelledState.refreshGen !== refreshGen) return;
    wbFbsCancelledState.lastError = "";
    wbFbsCancelledState.rows = Array.isArray(data.rows) ? data.rows : [];
    renderWbFbsCancelledOrdersTable();
    _wbFbsCancelledMergeIntoDetail(wbFbsCancelledState.rows);
  } catch (e) {
    if (wbFbsCancelledState.refreshGen !== refreshGen) return;
    const msg = String(e.message || e);
    wbFbsCancelledState.lastError = msg;
    // Keep previous successful rows; only clear the empty-state message path.
    if (!wbFbsCancelledState.rows.length) renderWbFbsCancelledOrdersTable();
    _wbFbsCancelledSetInfo(msg);
  } finally {
    if (wbFbsCancelledState.refreshGen === refreshGen) {
      wbFbsCancelledState.loading = false;
      if (btn) btn.disabled = false;
      if (!wbFbsCancelledState.rows.length) renderWbFbsCancelledOrdersTable();
    }
  }
}
window.refreshWbFbsCancelledOrders = refreshWbFbsCancelledOrders;

function openWbFbsCancelledOrdersModal() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady()) return;
  setModalVisibility("wbFbsCancelledOrdersModal", true);
  wbFbsCancelledState.rows = [];
  wbFbsCancelledState.lastError = "";
  wbFbsCancelledState.loading = true;
  _wbFbsCancelledSetInfo("");
  renderWbFbsCancelledOrdersTable();
  // Allow refresh() to take over the in-flight load.
  wbFbsCancelledState.loading = false;
  refreshWbFbsCancelledOrders().catch(() => {});
}
window.openWbFbsCancelledOrdersModal = openWbFbsCancelledOrdersModal;

function closeWbFbsCancelledOrdersModal() {
  wbFbsCancelledState.refreshGen = Number(wbFbsCancelledState.refreshGen || 0) + 1;
  wbFbsCancelledState.loading = false;
  wbFbsCancelledState.lastError = "";
  wbFbsCancelledState.rows = [];
  const btn = document.getElementById("wbFbsCancelledOrdersRefreshBtn");
  if (btn) btn.disabled = false;
  _wbFbsCancelledSetInfo("");
  setModalVisibility("wbFbsCancelledOrdersModal", false);
}
window.closeWbFbsCancelledOrdersModal = closeWbFbsCancelledOrdersModal;

const wbFbsKizState = {
  rows: [],
  errors: {},
  pendingOrderId: null,
  saving: false,
  /** False until KIZ modal rows finished loading. */
  rowsReady: false,
  /** True while supply-detail refresh control is polling WB meta. */
  statusRefreshing: false,
  /** Monotonic token so a stale refresh cannot re-enable the wrong modal. */
  statusRefreshGen: 0,
  /** Input id to refocus after RU-layout warning is dismissed. */
  ruLayoutFocusId: null,
  /** Timestamp when RU-layout warning opened (ignore scanner Enter briefly). */
  ruLayoutOpenedAt: 0,
  /**
   * Snapshot of normalized КИЗ lists by order_id at modal open / after WB-ok
   * save. Used to skip unchanged rows on the next Save.
   */
  baselineByOrder: {},
  /** After optimistic-concurrency conflict, next save for these order_ids is forced. */
  forceSaveByOrder: {},
  /** Interval id for live «Сохранение…» status text (UI only). */
  saveProgressTimer: 0,
  /**
   * Silent FeedPilot-only autosave after scan/clear.
   * Serial queue so scans stay snappy; never blocks the scan UI path.
   */
  localAutosaveChain: Promise.resolve(),
  localAutosaveSeqByOrder: {},
  localAutosaveInflight: 0,
};

function _wbFbsKizOrdersWord(n) {
  const abs = Math.abs(Number(n) || 0) % 100;
  const last = abs % 10;
  if (abs > 10 && abs < 20) return "заказов";
  if (last === 1) return "заказ";
  if (last >= 2 && last <= 4) return "заказа";
  return "заказов";
}

/** Live status while Save is in flight — does not change API / save logic. */
function _wbFbsKizStartSaveProgress(itemCount) {
  _wbFbsKizStopSaveProgress();
  const n = Math.max(0, Number(itemCount) || 0);
  const word = _wbFbsKizOrdersWord(n);
  const started = Date.now();
  const tick = () => {
    if (!wbFbsKizState.saving) return;
    const elapsed = Date.now() - started;
    let msg = `Сохраняем ${n} ${word} в FeedPilot…`;
    if (elapsed >= 400 && elapsed < 2500) {
      msg = `Отправляем КИЗ в Wildberries (${n} ${word})…`;
    } else if (elapsed >= 2500) {
      msg = `Ещё отправляем в WB — подождите (${n} ${word})…`;
    }
    _wbFbsKizSetInfo(msg);
  };
  tick();
  wbFbsKizState.saveProgressTimer = window.setInterval(tick, 450);
}

function _wbFbsKizStopSaveProgress() {
  if (wbFbsKizState.saveProgressTimer) {
    window.clearInterval(wbFbsKizState.saveProgressTimer);
    wbFbsKizState.saveProgressTimer = 0;
  }
}

/**
 * Disable KIZ toolbar filters until rows are loaded.
 * Search / sticker scan use readonly (not disabled) so the hover tooltip still works.
 */
function _wbFbsKizSetFiltersReady(ready) {
  wbFbsKizState.rowsReady = !!ready;
  const tip = "Дождитесь загрузки заказов";
  const filled = document.getElementById("wbFbsKizFilterFilled");
  const empty = document.getElementById("wbFbsKizFilterEmpty");
  const errors = document.getElementById("wbFbsKizFilterErrors");
  const cancelled = document.getElementById("wbFbsKizFilterCancelled");
  const filledLabel = document.getElementById("wbFbsKizFilterFilledLabel")
    || (filled && filled.closest("label"));
  const emptyLabel = document.getElementById("wbFbsKizFilterEmptyLabel")
    || (empty && empty.closest("label"));
  const errorsLabel = document.getElementById("wbFbsKizFilterErrorsLabel")
    || (errors && errors.closest("label"));
  const cancelledLabel = document.getElementById("wbFbsKizFilterCancelledLabel")
    || (cancelled && cancelled.closest("label"));
  const search = document.getElementById("wbFbsKizSearchFilter");
  const sticker = document.getElementById("wbFbsKizStickerScan");

  const setLabelWait = (label, on) => {
    if (!label) return;
    if (on) {
      if (label.dataset.waitTitleSaved === undefined) {
        label.dataset.waitTitleSaved = label.getAttribute("title") || "";
      }
      label.classList.add("is-wait-rows");
      label.setAttribute("title", tip);
    } else {
      label.classList.remove("is-wait-rows");
      const saved = label.dataset.waitTitleSaved;
      if (saved !== undefined) {
        if (saved) label.setAttribute("title", saved);
        else label.removeAttribute("title");
        delete label.dataset.waitTitleSaved;
      }
    }
  };

  const setInputWait = (input, on) => {
    if (!input) return;
    if (on) {
      if (input.dataset.waitTitleSaved === undefined) {
        input.dataset.waitTitleSaved = input.getAttribute("title") || "";
      }
      input.readOnly = true;
      input.setAttribute("aria-disabled", "true");
      input.classList.add("is-wait-rows");
      input.setAttribute("title", tip);
      input.tabIndex = -1;
      if (document.activeElement === input) {
        try { input.blur(); } catch (_) {}
      }
    } else {
      input.readOnly = false;
      input.removeAttribute("aria-disabled");
      input.classList.remove("is-wait-rows");
      input.removeAttribute("tabindex");
      const saved = input.dataset.waitTitleSaved;
      if (saved !== undefined) {
        if (saved) input.setAttribute("title", saved);
        else input.removeAttribute("title");
        delete input.dataset.waitTitleSaved;
      }
    }
  };

  if (filled) filled.disabled = !ready;
  if (empty) empty.disabled = !ready;
  if (errors) errors.disabled = !ready;
  if (cancelled) cancelled.disabled = !ready;
  setLabelWait(filledLabel, !ready);
  setLabelWait(emptyLabel, !ready);
  setLabelWait(errorsLabel, !ready);
  setLabelWait(cancelledLabel, !ready);
  setInputWait(search, !ready);
  setInputWait(sticker, !ready);
}

function _wbFbsKizSplitSetTone(tone) {
  const split = document.getElementById("wbFbsKizSplit");
  if (!split) return;
  split.classList.remove("is-ok", "is-error");
  const t = String(tone || "").trim().toLowerCase();
  if (t === "ok") split.classList.add("is-ok");
  else if (t === "error") split.classList.add("is-error");
  // pending / none / unknown → leave default secondary styling
}

function _wbFbsKizClearOrderFields(order) {
  if (!order || typeof order !== "object") return;
  order.kiz_required = false;
  order.kiz_bound = false;
  order.kiz_codes = [];
  order.kiz_decision = "";
  order.kiz_status = "empty";
}

function _wbFbsKizMergeStatusIntoDetail(orders) {
  const supply = wbFbsDetailState.supply;
  if (!supply || !Array.isArray(supply.orders) || !Array.isArray(orders)) return;
  const byId = new Map();
  orders.forEach((row) => {
    const oid = Number(row?.order_id);
    if (Number.isFinite(oid) && oid > 0) byId.set(oid, row);
  });
  // Empty live result ⇒ no KIZ-required orders left in supply.
  if (!byId.size) {
    supply.orders.forEach((o) => {
      const keepCancel = String(o?.cancel_reason_label || "").trim();
      _wbFbsKizClearOrderFields(o);
      if (keepCancel) o.cancel_reason_label = keepCancel;
    });
    return;
  }
  supply.orders.forEach((o) => {
    const oid = Number(o?.order_id);
    const upd = byId.get(oid);
    if (!upd) {
      // Order disappeared from live supply composition.
      const keepCancel = String(o?.cancel_reason_label || "").trim();
      _wbFbsKizClearOrderFields(o);
      if (keepCancel) o.cancel_reason_label = keepCancel;
      return;
    }
    o.kiz_required = !!upd.kiz_required;
    o.kiz_bound = !!upd.kiz_bound;
    o.kiz_codes = Array.isArray(upd.kiz_codes) ? upd.kiz_codes.slice() : [];
    o.kiz_decision = String(upd.kiz_decision || "");
    o.kiz_status = String(upd.kiz_status || "empty");
    if (upd.cancelled || upd.cancel_reason_label) {
      o.cancel_reason_label = String(
        upd.cancel_reason_label || o.cancel_reason_label || "Отменен"
      ).trim() || "Отменен";
    }
  });
}

async function refreshWbFbsKizStatus(event) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady() || wbFbsKizState.statusRefreshing) {
    return;
  }
  const refreshBtn = document.getElementById("wbFbsSupplyDetailKizRefreshBtn");
  const kizBtn = document.getElementById("wbFbsSupplyDetailKizBtn");
  const refreshGen = Number(wbFbsKizState.statusRefreshGen || 0) + 1;
  wbFbsKizState.statusRefreshGen = refreshGen;
  wbFbsKizState.statusRefreshing = true;
  if (refreshBtn) {
    refreshBtn.disabled = true;
    refreshBtn.classList.add("is-spinning");
  }
  if (kizBtn) kizBtn.disabled = true;
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/kiz/status?${params}`
    );
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data.ok === false) {
      throw new Error(data.detail || `Ошибка ${res.status}`);
    }
    if (wbFbsDetailState.supplyId !== sid) return;
    if (wbFbsKizState.statusRefreshGen !== refreshGen) return;
    _wbFbsKizMergeStatusIntoDetail(data.orders || []);
    const info = document.getElementById("wbFbsSupplyDetailInfo");
    if (info) {
      info.hidden = true;
      info.textContent = "";
    }
    // Render first, then apply tone — render must not wipe the refresh color.
    if (wbFbsDetailState.supply) renderWbFbsSupplyDetail(wbFbsDetailState.supply);
    _wbFbsKizSplitSetTone(data.status);
  } catch (e) {
    if (
      wbFbsDetailState.supplyId === sid
      && wbFbsKizState.statusRefreshGen === refreshGen
    ) {
      const info = document.getElementById("wbFbsSupplyDetailInfo");
      if (info) {
        info.hidden = false;
        info.textContent = String(e.message || e);
      }
    }
  } finally {
    if (wbFbsKizState.statusRefreshGen === refreshGen) {
      wbFbsKizState.statusRefreshing = false;
      if (refreshBtn) {
        refreshBtn.disabled = false;
        refreshBtn.classList.remove("is-spinning");
      }
      if (kizBtn) kizBtn.disabled = false;
    }
  }
}
window.refreshWbFbsKizStatus = refreshWbFbsKizStatus;

function _wbFbsKizBadgeHtml(order) {
  // Codes without a WB decision → pending (not green).
  const status = String(order?.kiz_status || (order?.kiz_bound ? "pending" : "empty"));
  const decision = String(order?.kiz_decision || "").trim();
  let cls = "is-empty";
  let label = "КИЗ";
  let title = "Требуется маркировка (КИЗ). Код ещё не привязан";
  if (status === "pending") {
    cls = "is-pending";
    label = "На проверке";
    title = "КИЗ отправлен, ожидается проверка Wildberries / Честный знак";
  } else if (status === "ok") {
    cls = "is-ok";
    label = "КИЗ";
    title = "Проверка КИЗ пройдена";
  } else if (status === "error") {
    cls = "is-error";
    label = "КИЗ";
    title = "Проверка КИЗ не пройдена (ошибка)";
  }
  if (decision) title += ` · WB decision: ${decision}`;
  return `<div class="wb-fbs-kiz ${cls}" title="${_wbFbsEsc(title)}">${_wbFbsEsc(label)}</div>`;
}

function _wbFbsKizSetInfo(text, ok, opts) {
  const el = document.getElementById("wbFbsKizInfo");
  if (!el) return;
  const asHtml = !!(opts && opts.html);
  const msg = String(text || "").trim();
  if (!msg) {
    el.hidden = true;
    el.textContent = "";
    el.classList.remove("is-ok");
    return;
  }
  el.hidden = false;
  if (asHtml) el.innerHTML = msg;
  else el.textContent = msg;
  el.classList.toggle("is-ok", !!ok);
}

function _wbFbsKizCancelBadgeHtml(row) {
  const label = String(row?.cancel_reason_label || "").trim();
  if (!label) return "";
  return `<div class="wb-fbs-cancel-reason" title="${_wbFbsEsc(label)}">${_wbFbsEsc(label)}</div>`;
}

function wbFbsKizFocusOrderInSearch(orderId) {
  const oid = String(orderId || "").trim();
  if (!oid) return;
  const filled = document.getElementById("wbFbsKizFilterFilled");
  const empty = document.getElementById("wbFbsKizFilterEmpty");
  const errors = document.getElementById("wbFbsKizFilterErrors");
  const cancelled = document.getElementById("wbFbsKizFilterCancelled");
  if (filled) filled.checked = false;
  if (empty) empty.checked = false;
  if (errors) errors.checked = false;
  if (cancelled) cancelled.checked = false;
  const search = document.getElementById("wbFbsKizSearchFilter");
  if (search) {
    search.value = oid;
    try { search.focus(); } catch (_) {}
  }
  renderWbFbsKizTable({ skipCollect: true });
}
window.wbFbsKizFocusOrderInSearch = wbFbsKizFocusOrderInSearch;

function _wbFbsKizOrderLinkHtml(orderId) {
  const oid = String(orderId || "").trim();
  if (!oid) return "";
  return `<button type="button" class="wb-fbs-kiz-order-link" ` +
    `onclick="wbFbsKizFocusOrderInSearch('${_wbFbsEsc(oid)}')">${_wbFbsEsc(oid)}</button>`;
}

function _wbFbsKizFormatCancelledSaveHtml(cancelledIds) {
  const ids = (cancelledIds || [])
    .map((x) => Number(x))
    .filter((x) => Number.isFinite(x) && x > 0);
  if (!ids.length) return "";
  const links = ids.map((id) => _wbFbsKizOrderLinkHtml(id)).join(", ");
  if (ids.length === 1) {
    return `Заказ ${links} отменен.`;
  }
  return `Заказы ${links} отменены.`;
}

/**
 * Keyboard-wedge scanners type as a keyboard. With RU layout, Latin sticker
 * barcodes (e.g. !uKEtQZVx) arrive as Cyrillic on the same physical keys.
 * Map ЙЦУКЕН → QWERTY before order lookup.
 */
const _WB_FBS_RU_LAYOUT_TO_EN = {
  "й": "q", "ц": "w", "у": "e", "к": "r", "е": "t", "н": "y", "г": "u", "ш": "i",
  "щ": "o", "з": "p", "х": "[", "ъ": "]",
  "ф": "a", "ы": "s", "в": "d", "а": "f", "п": "g", "р": "h", "о": "j", "л": "k",
  "д": "l", "ж": ";", "э": "'",
  "я": "z", "ч": "x", "с": "c", "м": "v", "и": "b", "т": "n", "ь": "m", "б": ",",
  "ю": ".", "ё": "`",
  "Й": "Q", "Ц": "W", "У": "E", "К": "R", "Е": "T", "Н": "Y", "Г": "U", "Ш": "I",
  "Щ": "O", "З": "P", "Х": "{", "Ъ": "}",
  "Ф": "A", "Ы": "S", "В": "D", "А": "F", "П": "G", "Р": "H", "О": "J", "Л": "K",
  "Д": "L", "Ж": ":", "Э": "\"",
  "Я": "Z", "Ч": "X", "С": "C", "М": "V", "И": "B", "Т": "N", "Ь": "M", "Б": "<",
  "Ю": ">", "Ё": "~",
};

function _wbFbsFixRuKeyboardLayout(value) {
  const text = String(value || "");
  if (!/[а-яёА-ЯЁ]/.test(text)) return text;
  let out = "";
  for (const ch of text) {
    out += Object.prototype.hasOwnProperty.call(_WB_FBS_RU_LAYOUT_TO_EN, ch)
      ? _WB_FBS_RU_LAYOUT_TO_EN[ch]
      : ch;
  }
  return out;
}

function _wbFbsKizHasCyrillic(value) {
  return /[а-яёА-ЯЁ]/.test(String(value || ""));
}

/** Block scan when RU layout produced Cyrillic; operator must switch to EN. */
function _wbFbsKizBlockRuLayout(inputEl) {
  const focusId = String(inputEl?.id || "");
  if (inputEl) inputEl.value = "";
  wbFbsKizState.ruLayoutFocusId = focusId || null;
  wbFbsKizState.ruLayoutOpenedAt = Date.now();
  setModalVisibility("wbFbsKizRuLayoutModal", true);
  // Do not focus OK: wedge scanners end with Enter and would auto-dismiss.
  document.removeEventListener("keydown", _wbFbsKizRuLayoutSwallowKeys, true);
  document.addEventListener("keydown", _wbFbsKizRuLayoutSwallowKeys, true);
  return true;
}

/** Swallow trailing scanner keystrokes while the RU-layout warning is open. */
function _wbFbsKizRuLayoutSwallowKeys(event) {
  if (!_wbFbsKizRuLayoutModalOpen()) return;
  const elapsed = Date.now() - Number(wbFbsKizState.ruLayoutOpenedAt || 0);
  // First ~500ms: ignore everything (scanner finishing the same read).
  if (elapsed < 500) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  // Later: still ignore printable keys / Enter so focus doesn't fill fields under the modal.
  const key = String(event.key || "");
  if (key === "Enter" || key === "Tab" || key.length === 1) {
    event.preventDefault();
    event.stopPropagation();
  }
}

function dismissWbFbsKizRuLayoutWarning() {
  // Ignore accidental Enter from the same scanner burst that triggered the warning.
  if (Date.now() - Number(wbFbsKizState.ruLayoutOpenedAt || 0) < 500) return;
  document.removeEventListener("keydown", _wbFbsKizRuLayoutSwallowKeys, true);
  setModalVisibility("wbFbsKizRuLayoutModal", false);
  const id = wbFbsKizState.ruLayoutFocusId;
  wbFbsKizState.ruLayoutFocusId = null;
  wbFbsKizState.ruLayoutOpenedAt = 0;
  const el = id ? document.getElementById(id) : null;
  if (el) {
    el.value = "";
    setTimeout(() => el.focus(), 40);
  }
}
window.dismissWbFbsKizRuLayoutWarning = dismissWbFbsKizRuLayoutWarning;

function _wbFbsKizRuLayoutModalOpen() {
  const modal = document.getElementById("wbFbsKizRuLayoutModal");
  return !!(modal && !modal.classList.contains("hidden"));
}

function clearWbFbsKizScanField(inputId) {
  const el = document.getElementById(String(inputId || ""));
  if (!el || el.readOnly || el.disabled) return;
  el.value = "";
  el.focus();
}
window.clearWbFbsKizScanField = clearWbFbsKizScanField;

/** Live check while the wedge scanner types into sticker / КИЗ scan fields. */
function onWbFbsKizScanInputCheck(event) {
  const input = event?.target;
  if (!input) return;
  if (_wbFbsKizRuLayoutModalOpen()) {
    input.value = "";
    return;
  }
  if (!_wbFbsKizHasCyrillic(input.value)) return;
  _wbFbsKizBlockRuLayout(input);
}
window.onWbFbsKizScanInputCheck = onWbFbsKizScanInputCheck;

function _wbFbsKizNormalizeScan(value) {
  return _wbFbsFixRuKeyboardLayout(String(value || "").replace(/\s+/g, "")).trim();
}

/** КИЗ / Data Matrix: scanners often emit ↔ instead of GS (\\u001D). */
function _wbFbsKizNormalizeMark(value) {
  // Also fix RU keyboard layout: crypto/tail letters of sgtin arrive as Cyrillic
  // when the OS layout is Russian (same wedge-scanner issue as sticker QR).
  return _wbFbsFixRuKeyboardLayout(
    String(value || "")
      .replace(/\u2194/g, "\u001D") // ↔
      .replace(/\r?\n/g, "")
  ).trim();
}

/** GS1 AI 01 → 14-digit GTIN from the start of a КИЗ / sgtin payload. */
function _wbFbsKizExtractGtin14(mark) {
  const raw = _wbFbsKizNormalizeMark(mark);
  if (!raw) return "";
  const m = raw.match(/^01(\d{14})/);
  if (m) return m[1];
  const m2 = raw.match(/(?:^|[\u001D])01(\d{14})/);
  return m2 ? m2[1] : "";
}

/** Product ШК candidates from GTIN-14: drop leading 0 → EAN-13 (0467… → 467…). */
function _wbFbsKizGtinToProductSkus(gtin14) {
  const g = String(gtin14 || "").replace(/\D/g, "");
  if (g.length !== 14) return [];
  const out = [g];
  if (g.startsWith("0")) out.push(g.slice(1));
  return out;
}

function _wbFbsKizOrderSkuSet(row) {
  const set = new Set();
  for (const b of row?.barcodes || []) {
    const raw = String(b || "").trim();
    if (raw) set.add(raw);
    const digits = raw.replace(/\D/g, "");
    if (digits) set.add(digits);
  }
  return set;
}

/**
 * Before putting a mark into the order row: GTIN (without leading 0) must match
 * one of the order product barcodes (ШК).
 */
function _wbFbsKizValidateMarkForOrder(mark, row) {
  const gtin14 = _wbFbsKizExtractGtin14(mark);
  if (!gtin14) {
    return {
      ok: false,
      error: "Не удалось выделить GTIN из кода маркировки (ожидается префикс 01 и 14 цифр).",
    };
  }
  // Product catalog flag: skip GTIN↔ШК match only (still require a parseable GTIN).
  if (row && row.skip_kiz_gtin_check) {
    return { ok: true, gtin14 };
  }
  const candidates = _wbFbsKizGtinToProductSkus(gtin14);
  const orderSkus = _wbFbsKizOrderSkuSet(row);
  if (!orderSkus.size) {
    return {
      ok: false,
      error: "У заказа нет штрихкодов товара — нельзя сверить GTIN маркировки.",
    };
  }
  if (!candidates.some((c) => orderSkus.has(c))) {
    const shown = gtin14.startsWith("0") ? gtin14.slice(1) : gtin14;
    const skuList = [...orderSkus].filter((s) => /^\d+$/.test(s)).slice(0, 6).join(", ");
    return {
      ok: false,
      error: `GTIN ${shown} не совпадает ни с одним ШК товара в заказе${skuList ? ` (${skuList})` : ""}.`,
    };
  }
  return { ok: true, gtin14 };
}

/** Find an already-filled КИЗ in the modal (same or another order). */
function _wbFbsKizFindExistingMark(mark) {
  const key = _wbFbsKizNormalizeMark(mark);
  if (!key) return null;
  for (const row of wbFbsKizState.rows || []) {
    const codes = Array.isArray(row.kiz_codes) ? row.kiz_codes : [];
    for (const c of codes) {
      const n = _wbFbsKizNormalizeMark(c);
      if (n && n === key) {
        return { order_id: Number(row.order_id), code: n };
      }
    }
  }
  return null;
}

function _wbFbsKizResetFilters() {
  const filled = document.getElementById("wbFbsKizFilterFilled");
  const empty = document.getElementById("wbFbsKizFilterEmpty");
  const errors = document.getElementById("wbFbsKizFilterErrors");
  const cancelled = document.getElementById("wbFbsKizFilterCancelled");
  const search = document.getElementById("wbFbsKizSearchFilter");
  if (filled) filled.checked = false;
  if (empty) empty.checked = false;
  if (errors) errors.checked = false;
  if (cancelled) cancelled.checked = false;
  if (search) search.value = "";
}

/** «Заполненные» и «Незаполненные» взаимоисключающие. */
function onWbFbsKizFilterFilledChange() {
  const filled = document.getElementById("wbFbsKizFilterFilled");
  const empty = document.getElementById("wbFbsKizFilterEmpty");
  if (filled?.checked && empty) empty.checked = false;
  renderWbFbsKizTable();
}
window.onWbFbsKizFilterFilledChange = onWbFbsKizFilterFilledChange;

function onWbFbsKizFilterEmptyChange() {
  const filled = document.getElementById("wbFbsKizFilterFilled");
  const empty = document.getElementById("wbFbsKizFilterEmpty");
  if (empty?.checked && filled) filled.checked = false;
  renderWbFbsKizTable();
}
window.onWbFbsKizFilterEmptyChange = onWbFbsKizFilterEmptyChange;

async function closeWbFbsKizModal(opts) {
  const force = !!(opts && opts.force);
  // Finish silent local autosaves so reload/reopen keeps scanned codes.
  if (!force) {
    try {
      await _wbFbsKizAwaitLocalAutosaves();
    } catch (_e) {
      /* keep going — confirm below if still dirty */
    }
  }
  if (!force && _wbFbsKizModalIsOpen() && _wbFbsKizHasUnsavedChanges()) {
    if (!confirm("Есть несохранённые изменения. Закрыть без сохранения?")) {
      return false;
    }
  }
  cancelWbFbsKizMarkScan();
  _wbFbsCloseRowMenus();
  document.removeEventListener("keydown", _wbFbsKizRuLayoutSwallowKeys, true);
  setModalVisibility("wbFbsKizRuLayoutModal", false);
  setModalVisibility("wbFbsKizScanPrompt", false);
  setModalVisibility("wbFbsKizModal", false);
  wbFbsKizState.rows = [];
  wbFbsKizState.errors = {};
  wbFbsKizState.pendingOrderId = null;
  wbFbsKizState.ruLayoutFocusId = null;
  wbFbsKizState.ruLayoutOpenedAt = 0;
  wbFbsKizState.baselineByOrder = {};
  wbFbsKizState.forceSaveByOrder = {};
  wbFbsKizState.localAutosaveSeqByOrder = {};
  _wbFbsKizResetFilters();
  _wbFbsKizSetFiltersReady(false);
  _wbFbsKizSetInfo("");
  return true;
}
window.closeWbFbsKizModal = closeWbFbsKizModal;

async function openWbFbsKizModal() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady()) return;
  setModalVisibility("wbFbsKizModal", true);
  wbFbsKizState.rows = [];
  wbFbsKizState.errors = {};
  wbFbsKizState.pendingOrderId = null;
  wbFbsKizState.baselineByOrder = {};
  wbFbsKizState.forceSaveByOrder = {};
  wbFbsKizState.localAutosaveSeqByOrder = {};
  _wbFbsKizResetFilters();
  _wbFbsKizSetFiltersReady(false);
  _wbFbsKizSetInfo("");
  const tbody = document.getElementById("wbFbsKizTbody");
  if (tbody) tbody.innerHTML = `<tr><td colspan="4" class="wb-fbs-empty">Загрузка…</td></tr>`;
  const saveBtn = document.getElementById("wbFbsKizSaveBtn");
  if (saveBtn) saveBtn.disabled = true;
  const scan = document.getElementById("wbFbsKizStickerScan");
  if (scan) scan.value = "";
  let loadOk = false;
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(`/api/wb-fbs/supplies/${encodeURIComponent(sid)}/kiz?${params}`);
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    wbFbsKizState.rows = Array.isArray(data.rows) ? data.rows.map((r) => ({
      ...r,
      kiz_codes: Array.isArray(r.kiz_codes) && r.kiz_codes.length ? r.kiz_codes.slice() : [""],
    })) : [];
    _wbFbsKizCaptureBaseline();
    renderWbFbsKizTable();
    if (!wbFbsKizState.rows.length) {
      _wbFbsKizSetInfo("В поставке нет заказов, требующих маркировки КИЗ");
    }
    loadOk = true;
  } catch (e) {
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="4" class="wb-fbs-empty" style="color:#b91c1c">${_wbFbsEsc(e.message || e)}</td></tr>`;
    }
    _wbFbsKizSetInfo(String(e.message || e));
  } finally {
    if (saveBtn) saveBtn.disabled = false;
    // Unlock filters + sticker after load attempt (success or error).
    if (document.getElementById("wbFbsKizModal")
      && !document.getElementById("wbFbsKizModal").classList.contains("hidden")) {
      _wbFbsKizSetFiltersReady(true);
      if (loadOk && scan) {
        setTimeout(() => {
          try { scan.focus(); } catch (_) {}
        }, 50);
      }
    }
  }
}
window.openWbFbsKizModal = openWbFbsKizModal;

/** Sticker number: prefix + last 4 digits (partB) larger. */
function _wbFbsKizStickerHtml(row) {
  const partA = String(row?.sticker_part_a || "").trim();
  const partB = String(row?.sticker_part_b || "").trim();
  const full = String(row?.sticker_number || "").trim();
  let head = partA;
  let tail = partB;
  if ((!head || !tail) && full) {
    if (full.length > 4) {
      head = full.slice(0, -4);
      tail = full.slice(-4);
    } else {
      head = "";
      tail = full;
    }
  }
  if (!head && !tail) {
    return `<div class="wb-fbs-kiz-sticker">—</div>`;
  }
  if (!tail) {
    return `<div class="wb-fbs-kiz-sticker">${_wbFbsEsc(head)}</div>`;
  }
  return `<div class="wb-fbs-kiz-sticker">` +
    (head ? `<span class="wb-fbs-kiz-sticker-head">${_wbFbsEsc(head)}</span>` : "") +
    `<span class="wb-fbs-kiz-sticker-tail">${_wbFbsEsc(tail)}</span>` +
    `</div>`;
}

function _wbFbsKizCollectFromDom() {
  const byId = {};
  for (const row of wbFbsKizState.rows) {
    byId[Number(row.order_id)] = row;
  }
  document.querySelectorAll(".wb-fbs-kiz-code-input").forEach((input) => {
    const oid = Number(input.dataset.orderId);
    const idx = Number(input.dataset.idx);
    const row = byId[oid];
    if (!row || !Number.isFinite(idx)) return;
    if (!Array.isArray(row.kiz_codes)) row.kiz_codes = [];
    row.kiz_codes[idx] = _wbFbsKizNormalizeMark(input.value);
  });
}

/** N = filled KIZ inputs; M = all KIZ input slots (empty + filled), filters ignored. */
function _wbFbsKizUpdateScanCounter() {
  const el = document.getElementById("wbFbsKizScanCount");
  if (!el) return;
  let filled = 0;
  let total = 0;
  for (const row of wbFbsKizState.rows) {
    const codes = Array.isArray(row?.kiz_codes) && row.kiz_codes.length
      ? row.kiz_codes
      : [""];
    total += codes.length;
    for (const code of codes) {
      if (String(code || "").trim()) filled += 1;
    }
  }
  el.textContent = `Просканировано ${filled} из ${total} КИЗ`;
}

/** Highlight pending scan row without rebuilding the whole table. */
function _wbFbsKizClearPendingHighlight() {
  document.querySelectorAll("#wbFbsKizTbody tr.wb-fbs-kiz-row.is-active").forEach((tr) => {
    tr.classList.remove("is-active");
  });
}

function _wbFbsKizSetPendingHighlight(orderId) {
  _wbFbsKizClearPendingHighlight();
  const oid = Number(orderId);
  if (!Number.isFinite(oid)) return false;
  const tr = document.querySelector(`#wbFbsKizTbody tr.wb-fbs-kiz-row[data-order-id="${oid}"]`);
  if (!tr) return false;
  tr.classList.add("is-active");
  return true;
}

/**
 * Patch one code cell after a successful wedge scan.
 * Returns false when DOM cannot represent the new state → caller should full-render.
 */
function _wbFbsKizPatchScannedCode(orderId, codeIdx, mark) {
  const oid = Number(orderId);
  const idx = Number(codeIdx);
  if (!Number.isFinite(oid) || !Number.isFinite(idx) || idx < 0) return false;
  const tr = document.querySelector(`#wbFbsKizTbody tr.wb-fbs-kiz-row[data-order-id="${oid}"]`);
  if (!tr) return false;
  const input = tr.querySelector(`.wb-fbs-kiz-code-input[data-order-id="${oid}"][data-idx="${idx}"]`);
  if (!input) return false;
  // Assign via property so GS (\\u001D) survives — same as renderWbFbsKizTable.
  input.value = String(mark || "");
  const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
  // Mirror full render: refresh every code block in this row (errors[oid] already cleared).
  tr.querySelectorAll(".wb-fbs-kiz-code-block").forEach((block) => {
    const inp = block.querySelector(".wb-fbs-kiz-code-input");
    if (!inp) return;
    inp.classList.remove("is-error");
    block.querySelectorAll(".wb-fbs-kiz-code-status").forEach((node) => node.remove());
    const codeVal = Number(inp.dataset.idx) === idx ? mark : inp.value;
    const chipHtml = _wbFbsKizCodeStatusChip(row, codeVal, "");
    if (chipHtml) block.insertAdjacentHTML("beforeend", chipHtml);
  });
  _wbFbsKizClearPendingHighlight();
  _wbFbsKizUpdateScanCounter();
  return true;
}

function _wbFbsKizRowIsEmpty(row) {
  const codes = Array.isArray(row?.kiz_codes) ? row.kiz_codes : [];
  return !codes.some((c) => String(c || "").trim());
}

/** Normalize + dedupe КИЗ list the same way Save / WB push does. */
function _wbFbsKizNormalizeCodesList(codes) {
  const seen = new Set();
  const out = [];
  for (const c of Array.isArray(codes) ? codes : []) {
    const n = _wbFbsKizNormalizeMark(c);
    if (!n || seen.has(n)) continue;
    seen.add(n);
    out.push(n);
  }
  return out;
}

function _wbFbsKizCaptureBaseline() {
  const map = {};
  for (const r of wbFbsKizState.rows) {
    const oid = Number(r.order_id);
    if (!Number.isFinite(oid)) continue;
    map[oid] = _wbFbsKizNormalizeCodesList(r.kiz_codes);
  }
  wbFbsKizState.baselineByOrder = map;
}

function _wbFbsKizBaselineEquals(orderId, codes) {
  const oid = Number(orderId);
  const base = wbFbsKizState.baselineByOrder?.[oid];
  if (!Array.isArray(base)) return false;
  const cur = _wbFbsKizNormalizeCodesList(codes);
  if (base.length !== cur.length) return false;
  for (let i = 0; i < base.length; i += 1) {
    if (base[i] !== cur[i]) return false;
  }
  return true;
}

function _wbFbsKizModalIsOpen() {
  const modal = document.getElementById("wbFbsKizModal");
  return !!(modal && !modal.classList.contains("hidden"));
}

/** True when in-memory / DOM КИЗ codes differ from last load/save baseline. */
function _wbFbsKizHasUnsavedChanges() {
  if (!Array.isArray(wbFbsKizState.rows) || !wbFbsKizState.rows.length) return false;
  if (!wbFbsKizState.baselineByOrder || !Object.keys(wbFbsKizState.baselineByOrder).length) {
    return false; // still loading — nothing to discard yet
  }
  _wbFbsKizCollectFromDom();
  for (const r of wbFbsKizState.rows) {
    const oid = Number(r.order_id);
    if (!Number.isFinite(oid)) continue;
    if (!Object.prototype.hasOwnProperty.call(wbFbsKizState.baselineByOrder, oid)) continue;
    if (!_wbFbsKizBaselineEquals(oid, r.kiz_codes)) return true;
  }
  return false;
}

/**
 * Queue a silent FeedPilot-only save for one order (no WB, no UI spinner).
 * Coalesces rapid scans on the same order; never awaits in the scan path.
 */
function _wbFbsKizScheduleLocalAutosave(orderId) {
  const oid = Number(orderId);
  if (!Number.isFinite(oid) || oid <= 0) return;
  if (!wbFbsKizState.localAutosaveSeqByOrder) wbFbsKizState.localAutosaveSeqByOrder = {};
  const seq = (Number(wbFbsKizState.localAutosaveSeqByOrder[oid]) || 0) + 1;
  wbFbsKizState.localAutosaveSeqByOrder[oid] = seq;
  const run = () => _wbFbsKizFlushLocalAutosave(oid, seq);
  wbFbsKizState.localAutosaveChain = (wbFbsKizState.localAutosaveChain || Promise.resolve())
    .then(run, run)
    .catch(() => {});
}

function _wbFbsKizAwaitLocalAutosaves() {
  // Re-check the chain tip: new scans during await extend localAutosaveChain.
  return (async () => {
    for (let i = 0; i < 40; i += 1) {
      const tip = wbFbsKizState.localAutosaveChain || Promise.resolve();
      try {
        await tip;
      } catch (_e) {
        /* ignore autosave faults — Save/close confirm still cover drafts */
      }
      const latest = wbFbsKizState.localAutosaveChain || tip;
      const inflight = Number(wbFbsKizState.localAutosaveInflight) || 0;
      if (tip === latest && inflight <= 0) return;
    }
  })();
}

async function _wbFbsKizFlushLocalAutosave(orderId, seq, attempt = 0) {
  const oid = Number(orderId);
  if (!Number.isFinite(oid)) return;
  // A newer scan for this order supersedes this job.
  if ((Number(wbFbsKizState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
  if (!_wbFbsKizModalIsOpen()) return;
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId) return;
  const row = (wbFbsKizState.rows || []).find((r) => Number(r.order_id) === oid);
  if (!row) return;
  const codes = _wbFbsKizNormalizeCodesList(row.kiz_codes);
  const wasBound = !!row.kiz_bound;
  const hadLocal = !!row.kiz_local;
  const clear = !codes.length && (wasBound || hadLocal);
  if (!codes.length && !clear) return;
  // Already mirrored in FeedPilot for this baseline — skip.
  if (_wbFbsKizBaselineEquals(oid, codes)) return;

  const item = {
    order_id: oid,
    kiz_codes: codes,
    clear,
    local_only: true,
    expected_saved_at: String(row.kiz_saved_at || ""),
    force: !!(wbFbsKizState.forceSaveByOrder && wbFbsKizState.forceSaveByOrder[oid]),
  };

  wbFbsKizState.localAutosaveInflight = (Number(wbFbsKizState.localAutosaveInflight) || 0) + 1;
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/kiz?${params}`,
      {
        method: "PUT",
        headers: jsonHeaders(),
        body: JSON.stringify({ items: [item] }),
        keepalive: true,
      }
    );
    // Superseded while in flight — ignore result.
    if ((Number(wbFbsKizState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    const result = (data.results || []).find((r) => Number(r.order_id) === oid) || null;
    if (!result) return;
    if (result.conflict) {
      row.kiz_saved_at = String(result.kiz_saved_at || row.kiz_saved_at || "");
      if (!wbFbsKizState.forceSaveByOrder) wbFbsKizState.forceSaveByOrder = {};
      wbFbsKizState.forceSaveByOrder[oid] = true;
      // Rare — only surface so the operator can reconcile before WB Save.
      _wbFbsKizSetInfo(
        result.error
          || "Заказ уже сохранён другим оператором — проверьте КИЗ и сохраните снова"
      );
      return;
    }
    if (!result.ok && !result.local_ok) {
      // Silent retry once for transient local faults.
      if (attempt < 1) {
        await new Promise((r) => setTimeout(r, 120));
        if ((Number(wbFbsKizState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
        return _wbFbsKizFlushLocalAutosave(oid, seq, attempt + 1);
      }
      return;
    }
    if (result.kiz_saved_at) row.kiz_saved_at = String(result.kiz_saved_at);
    row.kiz_local = true;
    row.kiz_wb_synced = false;
    if (!wbFbsKizState.baselineByOrder) wbFbsKizState.baselineByOrder = {};
    wbFbsKizState.baselineByOrder[oid] = codes.slice();
    if (wbFbsKizState.forceSaveByOrder) delete wbFbsKizState.forceSaveByOrder[oid];
  } catch (_e) {
    // Keep draft in UI; Save / close confirm still cover the edge case.
    if (attempt < 1) {
      await new Promise((r) => setTimeout(r, 120));
      if ((Number(wbFbsKizState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
      return _wbFbsKizFlushLocalAutosave(oid, seq, attempt + 1);
    }
  } finally {
    wbFbsKizState.localAutosaveInflight = Math.max(
      0,
      (Number(wbFbsKizState.localAutosaveInflight) || 1) - 1
    );
  }
}

function _wbFbsKizRowMatchesSearch(row, query) {
  const q = String(query || "").trim().toLocaleLowerCase("en-US");
  if (!q) return true;
  const barcodes = Array.isArray(row?.barcodes)
    ? row.barcodes
    : (Array.isArray(row?.skus) ? row.skus : []);
  const hay = [
    row?.order_id,
    row?.sticker_number,
    row?.sticker_part_a,
    row?.sticker_part_b,
    row?.sticker_barcode,
    row?.product_name,
    row?.article,
    row?.brand,
    row?.nm_id,
    ...barcodes,
  ]
    .map((x) => String(x || "").trim().toLocaleLowerCase("en-US"))
    .filter(Boolean);
  return hay.some((v) => v.includes(q));
}

/** Status chip under a filled КИЗ code in the marking modal (never for empty). */
function _wbFbsKizCodeStatusChip(row, codeValue, saveError) {
  const filled = String(codeValue || "").trim();
  if (!filled) return "";
  let status = String(row?.kiz_status || "").trim();
  if ((!status || status === "empty") && saveError) status = "error";
  if (!status || status === "empty") return "";
  const decision = String(row?.kiz_decision || "").trim();
  let cls = "is-pending";
  let label = "На проверке";
  if (status === "ok") {
    cls = "is-ok";
    label = "Проверка пройдена";
  } else if (status === "error") {
    cls = "is-error";
    label = saveError
      ? `Ошибка: ${saveError}`
      : (decision ? `Ошибка проверки (${decision})` : "Ошибка проверки");
  } else if (status === "pending") {
    cls = "is-pending";
    label = "На проверке";
  } else {
    return "";
  }
  return `<div class="wb-fbs-kiz-code-status ${cls}">${_wbFbsEsc(label)}</div>`;
}

function renderWbFbsKizTable(opts) {
  // After programmatic state updates (scan/CSV/save) skip DOM collect —
  // otherwise empty inputs overwrite the just-assigned КИЗ codes.
  if (!(opts && opts.skipCollect)) _wbFbsKizCollectFromDom();
  const tbody = document.getElementById("wbFbsKizTbody");
  if (!tbody) return;
  const onlyFilled = !!document.getElementById("wbFbsKizFilterFilled")?.checked;
  const onlyEmpty = !!document.getElementById("wbFbsKizFilterEmpty")?.checked;
  const onlyErrors = !!document.getElementById("wbFbsKizFilterErrors")?.checked;
  const onlyCancelled = !!document.getElementById("wbFbsKizFilterCancelled")?.checked;
  const searchQ = document.getElementById("wbFbsKizSearchFilter")?.value || "";
  const pending = wbFbsKizState.pendingOrderId;
  let rows = wbFbsKizState.rows.slice();
  if (onlyFilled) rows = rows.filter((r) => !_wbFbsKizRowIsEmpty(r));
  if (onlyEmpty) rows = rows.filter((r) => _wbFbsKizRowIsEmpty(r));
  if (onlyErrors) {
    rows = rows.filter((r) => {
      const oid = Number(r.order_id);
      return wbFbsKizState.errors[oid] || String(r.kiz_status || "") === "error";
    });
  }
  if (onlyCancelled) {
    rows = rows.filter((r) => !!String(r?.cancel_reason_label || "").trim());
  }
  if (String(searchQ || "").trim()) {
    rows = rows.filter((r) => _wbFbsKizRowMatchesSearch(r, searchQ));
  }
  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="4" class="wb-fbs-empty">${
      wbFbsKizState.rows.length ? "Нет строк по выбранным фильтрам" : "Нет заказов с КИЗ"
    }</td></tr>`;
    _wbFbsKizUpdateScanCounter();
    return;
  }
  tbody.innerHTML = rows.map((r) => {
    const oid = Number(r.order_id);
    const codes = Array.isArray(r.kiz_codes) && r.kiz_codes.length ? r.kiz_codes : [""];
    const err = String(wbFbsKizState.errors[oid] || "").trim();
    const photo = r.product_photo
      ? `<img class="wb-fbs-product-photo" src="${_wbFbsEsc(r.product_photo)}" alt="" width="56" height="56" loading="lazy">`
      : `<span class="wb-fbs-product-ph" aria-hidden="true"></span>`;
    const brandArt = [r.brand, r.article ? `Арт. ${r.article}` : ""].filter(Boolean).join(" · ");
    const barcodes = Array.isArray(r.barcodes)
      ? r.barcodes
      : (Array.isArray(r.skus) ? r.skus : []);
    const barcodeHtml = barcodes.length
      ? `<div class="wb-fbs-kiz-barcodes" title="Штрихкод товара">${barcodes.map((b) =>
          `<div class="wb-fbs-kiz-barcode">${_wbFbsEsc(b)}</div>`
        ).join("")}</div>`
      : "";
    const cancelBadgeHtml = _wbFbsKizCancelBadgeHtml(r);
    // Do not put КИЗ into value="" via innerHTML — \\u001D is dropped by HTML parser.
    const canRemoveRow = codes.length > 1;
    const codeHtml = codes.map((code, idx) => {
      const statusChip = _wbFbsKizCodeStatusChip(r, code, err);
      const clearTitle = canRemoveRow ? "Удалить строку КИЗ" : "Очистить маркировку";
      return `
      <div class="wb-fbs-kiz-code-block">
        <div class="wb-fbs-kiz-code-row">
          <span class="wb-fbs-kiz-code-idx">${idx + 1}</span>
          <input id="wbFbsKizCode_${oid}_${idx}"
                 class="wb-fbs-kiz-code-input${err && String(code || "").trim() ? " is-error" : ""}" type="text"
                 data-order-id="${oid}" data-idx="${idx}"
                 autocomplete="off"
                 oninput="onWbFbsKizCodeInput(${oid}, event)"
                 onblur="onWbFbsKizCodeBlur(${oid}, event)"
                 onkeydown="onWbFbsKizCodeKey(${oid}, event)" />
          <button type="button" class="wb-fbs-kiz-remove" title="${clearTitle}"
                  aria-label="${clearTitle}"
                  onclick="removeWbFbsKizCode(${oid}, ${idx})">×</button>
        </div>
        ${statusChip}
      </div>`;
    }).join("");
    const stickerHtml = _wbFbsKizStickerHtml(r);
    const safeKey = `kiz_${oid}`;
    return `<tr class="wb-fbs-kiz-row${pending === oid ? " is-active" : ""}" data-order-id="${oid}">
      <td>
        <div class="wb-fbs-kiz-order-id">${_wbFbsEsc(oid)}</div>
        <div class="wb-fbs-kiz-order-sticker">${stickerHtml}</div>
        <div class="wb-fbs-kiz-order-date">от ${_wbFbsEsc(r.created_date || "—")}</div>
      </td>
      <td>
        <div class="wb-fbs-product">
          ${photo}
          <div class="wb-fbs-product-text">
            <div class="wb-fbs-product-name" title="${_wbFbsEsc(r.product_name || r.article || "")}">${_wbFbsEsc(r.product_name || r.article || "—")}</div>
            <div class="wb-fbs-product-sub">${_wbFbsEsc(brandArt || "—")}</div>
            ${barcodeHtml}
            ${cancelBadgeHtml}
          </div>
        </div>
      </td>
      <td>
        <div class="wb-fbs-kiz-codes">${codeHtml}</div>
        <button type="button" class="wb-fbs-kiz-add" onclick="addWbFbsKizCode(${oid})">+ Добавить КИЗ</button>
      </td>
      <td>
        <div class="wb-fbs-row-menu-wrap">
          <button type="button" class="icon-btn secondary wb-fbs-row-menu-btn" title="Действия"
                  onclick="toggleWbFbsRowMenu(event, '${safeKey}')" aria-haspopup="menu">⋮</button>
          <div id="wbFbsRowMenu_${safeKey}" class="wb-fbs-row-menu" data-order-id="${safeKey}" role="menu">
            <button type="button" class="wb-fbs-row-menu-item" role="menuitem"
                    onclick="wbFbsPrintOneOrderStickerFromDetail(${oid})">
              ${_wbFbsQrMenuIconHtml()}
              Напечатать стикер
            </button>
          </div>
        </div>
      </td>
    </tr>`;
  }).join("");
  // Assign codes via DOM property so GS (\\u001D) survives.
  tbody.querySelectorAll(".wb-fbs-kiz-code-input").forEach((input) => {
    const oid = Number(input.dataset.orderId);
    const idx = Number(input.dataset.idx);
    const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
    if (!row || !Number.isFinite(idx)) return;
    const codes = Array.isArray(row.kiz_codes) ? row.kiz_codes : [];
    input.value = String(codes[idx] ?? "");
  });
  _wbFbsKizUpdateScanCounter();
}
window.renderWbFbsKizTable = renderWbFbsKizTable;

function onWbFbsKizCodeInput(orderId, event) {
  const oid = Number(orderId);
  const input = event?.target;
  // Same RU-layout gate as sticker / mark scan — first and extra КИЗ rows.
  if (input) {
    if (_wbFbsKizRuLayoutModalOpen()) {
      input.value = "";
      return;
    }
    if (_wbFbsKizHasCyrillic(input.value)) {
      const idx = Number(input.dataset.idx);
      const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
      if (row && Array.isArray(row.kiz_codes) && Number.isFinite(idx) && idx >= 0) {
        row.kiz_codes[idx] = "";
      }
      if (wbFbsKizState.errors[oid]) delete wbFbsKizState.errors[oid];
      _wbFbsKizBlockRuLayout(input);
      // Counter reads state, not the cleared input — refresh after wipe.
      _wbFbsKizUpdateScanCounter();
      return;
    }
  }
  if (wbFbsKizState.errors[oid]) {
    delete wbFbsKizState.errors[oid];
  }
  _wbFbsKizCollectFromDom();
  const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
  if (row) {
    const codes = _wbFbsKizNormalizeCodesList(row.kiz_codes);
    // Empty KIZ field: drop save/API error chip; keep cancel badge separately.
    if (!codes.length) {
      delete wbFbsKizState.errors[oid];
      if (String(row.kiz_status || "") === "error") row.kiz_status = "empty";
    }
  }
  _wbFbsKizUpdateScanCounter();
}
window.onWbFbsKizCodeInput = onWbFbsKizCodeInput;

/** Manual КИЗ entry: silent FeedPilot autosave when leaving the field. */
function onWbFbsKizCodeBlur(orderId, _event) {
  const oid = Number(orderId);
  if (!Number.isFinite(oid) || oid <= 0) return;
  if (!_wbFbsKizModalIsOpen()) return;
  _wbFbsKizCollectFromDom();
  _wbFbsKizScheduleLocalAutosave(oid);
}
window.onWbFbsKizCodeBlur = onWbFbsKizCodeBlur;

/** Enter after manual paste/type → save locally and move to sticker scan. */
function onWbFbsKizCodeKey(orderId, event) {
  if (!event || event.key !== "Enter") return;
  event.preventDefault();
  const oid = Number(orderId);
  if (!Number.isFinite(oid) || oid <= 0) return;
  _wbFbsKizCollectFromDom();
  _wbFbsKizScheduleLocalAutosave(oid);
  const sticker = document.getElementById("wbFbsKizStickerScan");
  if (sticker) {
    sticker.focus();
    sticker.select?.();
  }
}
window.onWbFbsKizCodeKey = onWbFbsKizCodeKey;

function addWbFbsKizCode(orderId) {
  _wbFbsKizCollectFromDom();
  const oid = Number(orderId);
  const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
  if (!row) return;
  if (!Array.isArray(row.kiz_codes)) row.kiz_codes = [""];
  row.kiz_codes.push("");
  renderWbFbsKizTable({ skipCollect: true });
  const inputs = document.querySelectorAll(`.wb-fbs-kiz-code-input[data-order-id="${oid}"]`);
  const last = inputs[inputs.length - 1];
  if (last) last.focus();
}
window.addWbFbsKizCode = addWbFbsKizCode;

function removeWbFbsKizCode(orderId, idx) {
  _wbFbsKizCollectFromDom();
  const oid = Number(orderId);
  const removeIdx = Number(idx);
  const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
  if (!row || !Number.isFinite(removeIdx)) return;
  if (!Array.isArray(row.kiz_codes)) row.kiz_codes = [""];
  if (row.kiz_codes.length <= 1) {
    // Always keep one empty field.
    row.kiz_codes = [""];
  } else {
    row.kiz_codes.splice(removeIdx, 1);
    if (!row.kiz_codes.length) row.kiz_codes = [""];
  }
  delete wbFbsKizState.errors[oid];
  if (!_wbFbsKizNormalizeCodesList(row.kiz_codes).length) {
    if (String(row.kiz_status || "") === "error") row.kiz_status = "empty";
  }
  renderWbFbsKizTable({ skipCollect: true });
  _wbFbsKizScheduleLocalAutosave(oid);
}
window.removeWbFbsKizCode = removeWbFbsKizCode;

function _wbFbsKizScanKey(value) {
  // WB sticker barcodes are case-sensitive on their side, but scanners / manual
  // entry often flip the last letter (e.g. *DTFHq/hj vs *DTFHq/hJ).
  return _wbFbsKizNormalizeScan(value).toLocaleLowerCase("en-US");
}

function _wbFbsKizFindBySticker(scan) {
  const raw = _wbFbsKizNormalizeScan(scan);
  if (!raw) return { row: null, ambiguous: false };
  const rawKey = _wbFbsKizScanKey(raw);
  // Primary: QR / 1D scan value from WB stickers.barcode (e.g. !uKEtQZVx).
  const byBarcode = [];
  for (const row of wbFbsKizState.rows) {
    const bc = _wbFbsKizNormalizeScan(row.sticker_barcode);
    if (bc && _wbFbsKizScanKey(bc) === rawKey) byBarcode.push(row);
  }
  if (byBarcode.length === 1) return { row: byBarcode[0], ambiguous: false };
  if (byBarcode.length > 1) {
    return { row: null, ambiguous: true, matches: byBarcode };
  }

  // Fallback: human-readable partA+partB / partB (portal sticker number).
  const digits = raw.replace(/\D+/g, "");
  const matches = [];
  for (const row of wbFbsKizState.rows) {
    const full = _wbFbsKizNormalizeScan(row.sticker_number);
    const partA = _wbFbsKizNormalizeScan(row.sticker_part_a);
    const partB = _wbFbsKizNormalizeScan(row.sticker_part_b);
    if (
      (full && (rawKey === _wbFbsKizScanKey(full) || digits === full.replace(/\D+/g, ""))) ||
      (partA && partB && digits === `${partA}${partB}`.replace(/\D+/g, "")) ||
      (partB && (rawKey === _wbFbsKizScanKey(partB) || digits === partB.replace(/\D+/g, "")))
    ) {
      matches.push(row);
    }
  }
  if (matches.length === 1) return { row: matches[0], ambiguous: false };
  if (matches.length > 1) {
    const exact = matches.find((r) => {
      const full = _wbFbsKizNormalizeScan(r.sticker_number);
      return _wbFbsKizScanKey(full) === rawKey || full.replace(/\D+/g, "") === digits;
    });
    if (exact) return { row: exact, ambiguous: false };
    return { row: null, ambiguous: true, matches };
  }
  return { row: null, ambiguous: false };
}

function onWbFbsKizStickerScanKey(event) {
  if (!event || event.key !== "Enter") return;
  event.preventDefault();
  if (_wbFbsKizRuLayoutModalOpen()) return;
  const input = event.target;
  if (input && (input.readOnly || input.disabled || !wbFbsKizState.rowsReady)) return;
  const rawTyped = String(input?.value || "").replace(/\s+/g, "").trim();
  if (!rawTyped) return;
  // Cyrillic first — before sticker↔order match and further checks.
  if (_wbFbsKizHasCyrillic(rawTyped)) {
    _wbFbsKizBlockRuLayout(input);
    return;
  }
  const scan = _wbFbsKizNormalizeScan(rawTyped);
  if (!scan) return;
  _wbFbsKizCollectFromDom();
  const found = _wbFbsKizFindBySticker(scan);
  if (found.ambiguous) {
    const ids = (found.matches || []).map((r) => r.order_id).slice(0, 5).join(", ");
    _wbFbsKizSetInfo(
      `Код стикера совпадает у нескольких заказов (${ids}${
        (found.matches || []).length > 5 ? "…" : ""
      }). Отсканируйте QR стикера ещё раз.`
    );
    if (input) input.select();
    return;
  }
  if (!found.row) {
    _wbFbsKizSetInfo(
      `Заказ со стикером «${scan}» не найден среди товаров с маркировкой. Возможно, это товар без маркировки.`
    );
    if (input) input.select();
    return;
  }
  _wbFbsKizSetInfo("");
  if (input) input.value = "";
  beginWbFbsKizMarkScan(Number(found.row.order_id));
}
window.onWbFbsKizStickerScanKey = onWbFbsKizStickerScanKey;

function beginWbFbsKizMarkScan(orderId) {
  const oid = Number(orderId);
  const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
  if (!row) return;
  wbFbsKizState.pendingOrderId = oid;
  // Fast path: toggle is-active only. Full render if the row is filtered out of DOM.
  if (!_wbFbsKizSetPendingHighlight(oid)) {
    renderWbFbsKizTable({ skipCollect: true });
  }
  const meta = document.getElementById("wbFbsKizScanPromptMeta");
  if (meta) {
    meta.textContent = `Заказ ${oid} · стикер ${row.sticker_number || "—"}`;
  }
  setModalVisibility("wbFbsKizScanPrompt", true);
  const mark = document.getElementById("wbFbsKizMarkScan");
  if (mark) {
    mark.value = "";
    setTimeout(() => mark.focus(), 40);
  }
}

function cancelWbFbsKizMarkScan() {
  setModalVisibility("wbFbsKizScanPrompt", false);
  wbFbsKizState.pendingOrderId = null;
  _wbFbsKizClearPendingHighlight();
  const sticker = document.getElementById("wbFbsKizStickerScan");
  if (sticker) setTimeout(() => sticker.focus(), 40);
}
window.cancelWbFbsKizMarkScan = cancelWbFbsKizMarkScan;

function onWbFbsKizMarkScanKey(event) {
  if (!event || event.key !== "Enter") return;
  event.preventDefault();
  if (_wbFbsKizRuLayoutModalOpen()) return;
  const oid = Number(wbFbsKizState.pendingOrderId);
  const input = event.target;
  const rawTyped = String(input?.value || "");
  if (!oid || !String(rawTyped || "").replace(/\s+/g, "")) return;
  // Cyrillic first — before GTIN / order checks and accepting the code.
  if (_wbFbsKizHasCyrillic(rawTyped)) {
    _wbFbsKizBlockRuLayout(input);
    return;
  }
  const mark = _wbFbsKizNormalizeMark(rawTyped);
  if (!mark) return;
  _wbFbsKizCollectFromDom();
  const row = wbFbsKizState.rows.find((r) => Number(r.order_id) === oid);
  if (!row) {
    cancelWbFbsKizMarkScan();
    return;
  }
  const check = _wbFbsKizValidateMarkForOrder(mark, row);
  if (!check.ok) {
    _wbFbsKizSetInfo(check.error || "Маркировка не подходит к ШК товара в заказе");
    if (input) input.select();
    return;
  }
  const dup = _wbFbsKizFindExistingMark(mark);
  if (dup) {
    const dupOid = Number(dup.order_id);
    _wbFbsKizSetInfo(
      dupOid === oid
        ? `Этот КИЗ уже просканирован в заказ ${oid} — повторно не добавляем`
        : `Этот КИЗ уже просканирован в заказ ${dupOid} — в заказ ${oid} не добавляем`
    );
    if (input) input.select();
    return;
  }
  if (!Array.isArray(row.kiz_codes) || !row.kiz_codes.length) row.kiz_codes = [""];
  let placedIdx = -1;
  for (let i = 0; i < row.kiz_codes.length; i += 1) {
    if (!String(row.kiz_codes[i] || "").trim()) {
      row.kiz_codes[i] = mark;
      placedIdx = i;
      break;
    }
  }
  let addedSlot = false;
  if (placedIdx < 0) {
    row.kiz_codes.push(mark);
    placedIdx = row.kiz_codes.length - 1;
    addedSlot = true;
  }
  delete wbFbsKizState.errors[oid];
  setModalVisibility("wbFbsKizScanPrompt", false);
  wbFbsKizState.pendingOrderId = null;
  // Show the filled row even if «Незаполненные» filter was on.
  const emptyFilter = document.getElementById("wbFbsKizFilterEmpty");
  const emptyFilterWasOn = !!emptyFilter?.checked;
  if (emptyFilter) emptyFilter.checked = false;
  // Full render when filter set changes or a new input slot appears; otherwise patch one cell.
  if (emptyFilterWasOn || addedSlot || !_wbFbsKizPatchScannedCode(oid, placedIdx, mark)) {
    renderWbFbsKizTable({ skipCollect: true });
  }
  _wbFbsKizSetInfo(
    `КИЗ добавлен в строку заказа ${oid}. Нажмите «Сохранить», чтобы отправить в WB.`,
    true
  );
  _wbFbsKizScheduleLocalAutosave(oid);
  const rowEl = document.querySelector(`#wbFbsKizTbody tr[data-order-id="${oid}"]`);
  if (rowEl) rowEl.scrollIntoView({ block: "nearest", behavior: "smooth" });
  const sticker = document.getElementById("wbFbsKizStickerScan");
  if (sticker) {
    sticker.value = "";
    setTimeout(() => sticker.focus(), 40);
  }
}
window.onWbFbsKizMarkScanKey = onWbFbsKizMarkScanKey;

function downloadWbFbsKizTemplate() {
  _wbFbsKizCollectFromDom();
  const lines = ["order_id;sticker_number;kiz"];
  for (const row of wbFbsKizState.rows) {
    const codes = (Array.isArray(row.kiz_codes) ? row.kiz_codes : [])
      .map((c) => String(c || "").trim())
      .filter(Boolean);
    if (!codes.length) {
      lines.push(`${row.order_id};${row.sticker_number || ""};`);
    } else {
      for (const code of codes) {
        lines.push(`${row.order_id};${row.sticker_number || ""};${code}`);
      }
    }
  }
  const blob = new Blob(["\uFEFF" + lines.join("\n")], { type: "text/csv;charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `kiz_${wbFbsDetailState.supplyId || "supply"}.csv`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}
window.downloadWbFbsKizTemplate = downloadWbFbsKizTemplate;

async function uploadWbFbsKizTemplate(event) {
  const file = event?.target?.files?.[0];
  if (event?.target) event.target.value = "";
  if (!file) return;
  _wbFbsKizCollectFromDom();
  try {
    const text = await file.text();
    const lines = String(text || "").replace(/^\uFEFF/, "").split(/\r?\n/).filter((l) => l.trim());
    if (lines.length < 2) throw new Error("Файл пуст");
    const byOrder = {};
    for (const line of lines.slice(1)) {
      const parts = line.includes(";") ? line.split(";") : line.split(",");
      const oid = Number(String(parts[0] || "").trim());
      const kiz = _wbFbsKizNormalizeMark(parts[2] ?? parts[1] ?? "");
      if (!Number.isFinite(oid)) continue;
      if (!byOrder[oid]) byOrder[oid] = [];
      if (kiz) byOrder[oid].push(kiz);
    }
    let applied = 0;
    let skippedEmpty = 0;
    let rejected = 0;
    for (const row of wbFbsKizState.rows) {
      const oid = Number(row.order_id);
      if (!Object.prototype.hasOwnProperty.call(byOrder, oid)) continue;
      // Empty kiz column must not wipe already filled codes.
      if (!byOrder[oid].length) {
        skippedEmpty += 1;
        continue;
      }
      const accepted = [];
      let rowErr = "";
      for (const code of byOrder[oid]) {
        const check = _wbFbsKizValidateMarkForOrder(code, row);
        if (!check.ok) {
          rejected += 1;
          rowErr = check.error || "GTIN не совпадает с ШК товара";
          continue;
        }
        accepted.push(code);
      }
      if (!accepted.length) {
        wbFbsKizState.errors[oid] = rowErr || "Коды КИЗ не прошли сверку с ШК";
        continue;
      }
      row.kiz_codes = accepted;
      delete wbFbsKizState.errors[oid];
      applied += 1;
    }
    renderWbFbsKizTable({ skipCollect: true });
    if (applied) {
      const notes = [];
      if (skippedEmpty) notes.push(`пустых: ${skippedEmpty}`);
      if (rejected) notes.push(`отклонено по ШК: ${rejected}`);
      _wbFbsKizSetInfo(
        `Загружено строк: ${applied}${notes.length ? ` (${notes.join(", ")})` : ""}`,
        true
      );
    } else if (rejected) {
      _wbFbsKizSetInfo("Коды из файла не совпали с ШК товаров в заказах");
    } else if (skippedEmpty) {
      _wbFbsKizSetInfo("В файле нет кодов КИЗ — текущие значения не изменены");
    } else {
      _wbFbsKizSetInfo("В файле нет совпадений с заказами поставки");
    }
  } catch (e) {
    _wbFbsKizSetInfo(String(e.message || e));
  }
}
window.uploadWbFbsKizTemplate = uploadWbFbsKizTemplate;

async function saveWbFbsKizModal() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || wbFbsKizState.saving) return;
  const btn = document.getElementById("wbFbsKizSaveBtn");
  wbFbsKizState.saving = true;
  if (btn) btn.disabled = true;
  // Let silent local autosaves finish so expected_saved_at / baseline are current.
  try {
    await _wbFbsKizAwaitLocalAutosaves();
  } catch (_e) {
    /* continue — Save still pushes current DOM codes */
  }
  _wbFbsKizCollectFromDom();
  // Save: local DB first, then WB. Modal stays open; retry WB on next Save.
  // Skip rows whose КИЗ list is unchanged vs baseline (unless WB sync pending).
  const items = [];
  let gtinErrors = 0;
  let skippedUnchanged = 0;
  wbFbsKizState.errors = {};
  for (const r of wbFbsKizState.rows) {
    const oid = Number(r.order_id);
    const codes = _wbFbsKizNormalizeCodesList(r.kiz_codes);
    const wasBound = !!r.kiz_bound;
    const hadLocal = !!r.kiz_local;
    const isCancelled = !!String(r.cancel_reason_label || "").trim();
    if (!codes.length && !wasBound && !hadLocal) continue;
    // Cancelled + empty: still save locally via API (backend skips WB), no UI error.
    if (!codes.length && isCancelled) {
      delete wbFbsKizState.errors[oid];
      r.kiz_status = "empty";
      const unchangedEmpty = _wbFbsKizBaselineEquals(oid, codes);
      if (unchangedEmpty && r.kiz_wb_synced !== false) {
        skippedUnchanged += 1;
        continue;
      }
      items.push({
        order_id: oid,
        kiz_codes: [],
        clear: !!(wasBound || hadLocal),
        expected_saved_at: String(r.kiz_saved_at || ""),
        force: !!(wbFbsKizState.forceSaveByOrder && wbFbsKizState.forceSaveByOrder[oid]),
      });
      continue;
    }
    if (codes.length) {
      let bad = "";
      for (const code of codes) {
        const check = _wbFbsKizValidateMarkForOrder(code, r);
        if (!check.ok) {
          bad = check.error || "GTIN не совпадает с ШК товара";
          break;
        }
      }
      if (bad) {
        wbFbsKizState.errors[oid] = bad;
        gtinErrors += 1;
        continue; // skip bad row; still save the rest
      }
    }
    const unchanged = _wbFbsKizBaselineEquals(oid, codes);
    // Keep retrying failed WB pushes even when the code list looks the same.
    // Cancelled rows with codes still need the friendly cancelled save result.
    const needsWbRetry = r.kiz_wb_synced === false;
    if (unchanged && !needsWbRetry) {
      skippedUnchanged += 1;
      continue;
    }
    items.push({
      order_id: oid,
      kiz_codes: codes,
      clear: !codes.length && (wasBound || hadLocal),
      expected_saved_at: String(r.kiz_saved_at || ""),
      force: !!(wbFbsKizState.forceSaveByOrder && wbFbsKizState.forceSaveByOrder[oid]),
    });
  }
  if (!items.length) {
    wbFbsKizState.saving = false;
    if (btn) btn.disabled = false;
    renderWbFbsKizTable({ skipCollect: true });
    if (gtinErrors) {
      _wbFbsKizSetInfo(
        `Нет строк для сохранения: у ${gtinErrors} заказ(ов) GTIN не совпадает с ШК товара`
      );
    } else if (skippedUnchanged) {
      _wbFbsKizSetInfo("Нет изменений для сохранения — неизменённые КИЗ не отправлялись", true);
    } else {
      _wbFbsKizSetInfo("Нет изменений для сохранения");
    }
    return;
  }
  _wbFbsKizStartSaveProgress(items.length);
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/kiz?${params}`,
      {
        method: "PUT",
        headers: jsonHeaders(),
        body: JSON.stringify({ items }),
      }
    );
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    _wbFbsKizStopSaveProgress();
    wbFbsKizState.errors = {};
    const cancelledIds = [];
    const otherFailNotes = [];
    const conflictIds = [];
    for (const r of data.results || []) {
      const oid = Number(r.order_id);
      const row = wbFbsKizState.rows.find((x) => Number(x.order_id) === oid);
      if (r.conflict) {
        conflictIds.push(oid);
        if (row) {
          const localChanged = !_wbFbsKizBaselineEquals(
            oid,
            _wbFbsKizNormalizeCodesList(row.kiz_codes),
          );
          row.kiz_saved_at = String(r.kiz_saved_at || row.kiz_saved_at || "");
          if (!localChanged && Array.isArray(r.kiz_codes)) {
            row.kiz_codes = r.kiz_codes.length ? r.kiz_codes.slice() : [""];
            row.kiz_local = true;
            if (!wbFbsKizState.baselineByOrder) wbFbsKizState.baselineByOrder = {};
            wbFbsKizState.baselineByOrder[oid] = _wbFbsKizNormalizeCodesList(r.kiz_codes);
            if (wbFbsKizState.forceSaveByOrder) delete wbFbsKizState.forceSaveByOrder[oid];
          } else if (!wbFbsKizState.forceSaveByOrder) {
            wbFbsKizState.forceSaveByOrder = { [oid]: true };
          } else {
            wbFbsKizState.forceSaveByOrder[oid] = true;
          }
        }
        wbFbsKizState.errors[oid] = r.error
          || "Заказ уже сохранён другим оператором — проверьте КИЗ и сохраните снова";
        otherFailNotes.push(`заказ ${oid}: конфликт с другим оператором`);
        continue;
      }
      if (row && r.kiz_saved_at) row.kiz_saved_at = String(r.kiz_saved_at);
      if (row && wbFbsKizState.forceSaveByOrder) delete wbFbsKizState.forceSaveByOrder[oid];
      if (row && Array.isArray(r.kiz_codes)) {
        row.kiz_codes = r.kiz_codes.length ? r.kiz_codes.slice() : [""];
        if (r.local_ok) {
          // Keep draft flag even for empty clear so retry still sends clear.
          row.kiz_local = true;
        }
        if (r.wb_ok) {
          row.kiz_bound = r.kiz_codes.length > 0;
          row.kiz_wb_synced = true;
          row.kiz_local = r.kiz_codes.length > 0;
          row.kiz_status = r.kiz_codes.length ? "pending" : "empty";
          row.kiz_decision = r.kiz_codes.length ? "required" : "";
          // Advance baseline only after WB accepted the write.
          if (!wbFbsKizState.baselineByOrder) wbFbsKizState.baselineByOrder = {};
          wbFbsKizState.baselineByOrder[oid] = _wbFbsKizNormalizeCodesList(r.kiz_codes);
        } else if (r.local_ok) {
          row.kiz_wb_synced = false;
          row.kiz_status = r.kiz_codes.length ? "pending" : "empty";
        }
      }
      if (r.cancelled || r.cancel_reason_label) {
        const label = String(r.cancel_reason_label || "Отменен").trim() || "Отменен";
        const codesNow = Array.isArray(r.kiz_codes)
          ? r.kiz_codes.filter((c) => String(c || "").trim())
          : [];
        if (row) {
          row.cancel_reason_label = label;
          row.wb_status = String(r.wb_status || row.wb_status || "");
          row.supplier_status = String(r.supplier_status || row.supplier_status || "");
        }
        // Empty clear on cancelled order is not a save error.
        if (r.skipped_empty || (r.wb_ok && !codesNow.length)) {
          if (row) {
            row.kiz_status = "empty";
            row.kiz_wb_synced = true;
            row.kiz_bound = false;
          }
          delete wbFbsKizState.errors[oid];
          continue;
        }
        if (row) row.kiz_status = "error";
        if (Number.isFinite(oid) && oid > 0) cancelledIds.push(oid);
        wbFbsKizState.errors[oid] = `Заказ отменен (${label})`;
        continue;
      }
      if (!r.wb_ok) {
        const err = r.error || "Ошибка записи в WB";
        wbFbsKizState.errors[oid] = err;
        otherFailNotes.push(`заказ ${oid}: ${err}`);
        if (row && Array.isArray(r.kiz_codes) && r.kiz_codes.length) {
          // Save/API failure on a filled code → show error under the code.
          row.kiz_status = "error";
        }
      }
    }
    renderWbFbsKizTable({ skipCollect: true });
    const savedWb = Number(data.saved || 0);
    const failed = Number(data.failed || 0);
    const gtinNote = gtinErrors ? ` Пропущено по GTIN/ШК: ${gtinErrors}.` : "";
    const skipNote = skippedUnchanged
      ? ` Без изменений не отправлялось: ${skippedUnchanged}.`
      : "";
    let resultMsg = "";
    let resultOk = false;
    let resultHtml = false;
    if (failed) {
      const onlyCancelled = cancelledIds.length > 0 && !otherFailNotes.length;
      const nFail = onlyCancelled ? cancelledIds.length : failed;
      const word = _wbFbsKizOrdersWord(nFail);
      let html = `Сохранено в FeedPilot. В WB не записалось ${nFail} ${word}:`;
      if (cancelledIds.length) {
        html += `<br>${_wbFbsKizFormatCancelledSaveHtml(cancelledIds)}`;
      }
      if (otherFailNotes.length) {
        const detail = otherFailNotes.slice(0, 3).join("; ");
        const more = otherFailNotes.length > 3 ? "…" : "";
        html += `<br>${_wbFbsEsc(detail + more)}`;
      }
      if (!onlyCancelled) {
        html += `<br>Окно не закрыто — нажмите «Сохранить» ещё раз, чтобы повторить отправку в WB.`;
      } else {
        html += `<br>Окно не закрыто — отменённые заказы остаются в поставке.`;
      }
      if (gtinNote) html += ` ${_wbFbsEsc(gtinNote.trim())}`;
      if (skipNote) html += ` ${_wbFbsEsc(skipNote.trim())}`;
      resultMsg = html;
      resultOk = false;
      resultHtml = true;
    } else {
      resultMsg =
        `Всё успешно: КИЗ сохранены в FeedPilot и отправлены в WB (${savedWb}).` +
        `${gtinNote}${skipNote}`;
      resultOk = !gtinErrors;
      resultHtml = false;
    }
    // Soft-refresh detail badges; keep cancelled labels in open supply detail.
    _wbFbsKizRefreshDetailBadges(data.results || []);
    _wbFbsKizSetInfo("Обновляем статусы проверки маркировки…");
    try { await refreshWbFbsKizStatus(); } catch (_) {}
    _wbFbsKizSetInfo(resultMsg, resultOk, resultHtml ? { html: true } : undefined);
  } catch (e) {
    _wbFbsKizStopSaveProgress();
    _wbFbsKizSetInfo(String(e.message || e));
  } finally {
    _wbFbsKizStopSaveProgress();
    wbFbsKizState.saving = false;
    if (btn) btn.disabled = false;
  }
}

function _wbFbsKizRefreshDetailBadges(results) {
  if (!Array.isArray(results) || !wbFbsDetailState.supply) return;
  const orders = wbFbsDetailState.supply.orders;
  if (!Array.isArray(orders)) return;
  let changed = false;
  for (const r of results) {
    if (!r) continue;
    const oid = Number(r.order_id);
    const order = orders.find((o) => Number(o.order_id) === oid);
    if (!order) continue;
    if (r.cancelled || r.cancel_reason_label) {
      order.cancel_reason_label = String(r.cancel_reason_label || "Отменен").trim() || "Отменен";
      if (r.wb_status) order.wb_status = String(r.wb_status);
      if (r.supplier_status) order.supplier_status = String(r.supplier_status);
      changed = true;
      continue;
    }
    if (!r.wb_ok) continue;
    const codes = Array.isArray(r.kiz_codes)
      ? r.kiz_codes.filter((c) => String(c || "").trim())
      : [];
    order.kiz_codes = codes;
    order.kiz_bound = codes.length > 0;
    // After successful WB write: «на проверке» until next sync gets filled/invalid.
    order.kiz_status = codes.length ? "pending" : "empty";
    order.kiz_decision = codes.length ? "required" : "";
    changed = true;
  }
  if (changed) {
    try {
      renderWbFbsSupplyDetail(wbFbsDetailState.supply);
    } catch (_) {
      /* ignore render glitches while KIZ modal is open */
    }
  }
}
window.saveWbFbsKizModal = saveWbFbsKizModal;

// ── WB FBS: Проверка ШК (товары без КИЗ) — отдельный инструмент, не Маркировка ──
const wbFbsPickState = {
  rows: [],
  errors: {},
  pendingOrderId: null,
  saving: false,
  rowsReady: false,
  baselineByOrder: {},
  /** After optimistic-concurrency conflict, next save for these order_ids is forced. */
  forceSaveByOrder: {},
  /**
   * Silent FeedPilot autosave after scan/clear (pick-verify is local-only).
   * Same queue pattern as Маркировка — never blocks the scan UI path.
   */
  localAutosaveChain: Promise.resolve(),
  localAutosaveSeqByOrder: {},
  localAutosaveInflight: 0,
};

function _wbFbsSyncPickVerifyBtn() {
  const btn = document.getElementById("wbFbsSupplyDetailPickVerifyBtn");
  if (!btn) return;
  // Owner-only + only when supply has at least one order without КИЗ.
  const supply = wbFbsDetailState.supply || {};
  const orders = Array.isArray(supply.orders) ? supply.orders : [];
  const hasPlain = orders.some((o) => o && !o.kiz_required);
  const can = isTenantOwner() && _wbFbsSupplyDetailActionsReady() && hasPlain;
  btn.hidden = !can;
  btn.style.display = can ? "" : "none";
}

function _wbFbsPickSetInfo(text, ok) {
  const el = document.getElementById("wbFbsPickInfo");
  if (!el) return;
  const msg = String(text || "").trim();
  if (!msg) {
    el.hidden = true;
    el.textContent = "";
    el.classList.remove("is-ok");
    return;
  }
  el.hidden = false;
  el.textContent = msg;
  el.classList.toggle("is-ok", !!ok);
}

function _wbFbsPickResetFilters() {
  const filled = document.getElementById("wbFbsPickFilterFilled");
  const empty = document.getElementById("wbFbsPickFilterEmpty");
  const errors = document.getElementById("wbFbsPickFilterErrors");
  const cancelled = document.getElementById("wbFbsPickFilterCancelled");
  const search = document.getElementById("wbFbsPickSearchFilter");
  if (filled) filled.checked = false;
  if (empty) empty.checked = false;
  if (errors) errors.checked = false;
  if (cancelled) cancelled.checked = false;
  if (search) search.value = "";
}

/**
 * Disable pick-verify filters + sticker scan until rows are loaded.
 * Same wait UX as Маркировка (`_wbFbsKizSetFiltersReady`).
 */
function _wbFbsPickSetFiltersReady(ready) {
  wbFbsPickState.rowsReady = !!ready;
  const tip = "Дождитесь загрузки заказов";
  const filled = document.getElementById("wbFbsPickFilterFilled");
  const empty = document.getElementById("wbFbsPickFilterEmpty");
  const errors = document.getElementById("wbFbsPickFilterErrors");
  const cancelled = document.getElementById("wbFbsPickFilterCancelled");
  const filledLabel = document.getElementById("wbFbsPickFilterFilledLabel")
    || (filled && filled.closest("label"));
  const emptyLabel = document.getElementById("wbFbsPickFilterEmptyLabel")
    || (empty && empty.closest("label"));
  const errorsLabel = document.getElementById("wbFbsPickFilterErrorsLabel")
    || (errors && errors.closest("label"));
  const cancelledLabel = document.getElementById("wbFbsPickFilterCancelledLabel")
    || (cancelled && cancelled.closest("label"));
  const search = document.getElementById("wbFbsPickSearchFilter");
  const sticker = document.getElementById("wbFbsPickStickerScan");

  const setLabelWait = (label, on) => {
    if (!label) return;
    if (on) {
      if (label.dataset.waitTitleSaved === undefined) {
        label.dataset.waitTitleSaved = label.getAttribute("title") || "";
      }
      label.classList.add("is-wait-rows");
      label.setAttribute("title", tip);
    } else {
      label.classList.remove("is-wait-rows");
      const saved = label.dataset.waitTitleSaved;
      if (saved !== undefined) {
        if (saved) label.setAttribute("title", saved);
        else label.removeAttribute("title");
        delete label.dataset.waitTitleSaved;
      }
    }
  };

  const setInputWait = (input, on) => {
    if (!input) return;
    if (on) {
      if (input.dataset.waitTitleSaved === undefined) {
        input.dataset.waitTitleSaved = input.getAttribute("title") || "";
      }
      input.readOnly = true;
      input.setAttribute("aria-disabled", "true");
      input.classList.add("is-wait-rows");
      input.setAttribute("title", tip);
      input.tabIndex = -1;
      if (document.activeElement === input) {
        try { input.blur(); } catch (_) {}
      }
    } else {
      input.readOnly = false;
      input.removeAttribute("aria-disabled");
      input.classList.remove("is-wait-rows");
      input.removeAttribute("tabindex");
      const saved = input.dataset.waitTitleSaved;
      if (saved !== undefined) {
        if (saved) input.setAttribute("title", saved);
        else input.removeAttribute("title");
        delete input.dataset.waitTitleSaved;
      }
    }
  };

  if (filled) filled.disabled = !ready;
  if (empty) empty.disabled = !ready;
  if (errors) errors.disabled = !ready;
  if (cancelled) cancelled.disabled = !ready;
  setLabelWait(filledLabel, !ready);
  setLabelWait(emptyLabel, !ready);
  setLabelWait(errorsLabel, !ready);
  setLabelWait(cancelledLabel, !ready);
  setInputWait(search, !ready);
  setInputWait(sticker, !ready);
}

function onWbFbsPickFilterFilledChange() {
  const filled = document.getElementById("wbFbsPickFilterFilled");
  const empty = document.getElementById("wbFbsPickFilterEmpty");
  if (filled?.checked && empty) empty.checked = false;
  renderWbFbsPickVerifyTable();
}
window.onWbFbsPickFilterFilledChange = onWbFbsPickFilterFilledChange;

function onWbFbsPickFilterEmptyChange() {
  const filled = document.getElementById("wbFbsPickFilterFilled");
  const empty = document.getElementById("wbFbsPickFilterEmpty");
  if (empty?.checked && filled) filled.checked = false;
  renderWbFbsPickVerifyTable();
}
window.onWbFbsPickFilterEmptyChange = onWbFbsPickFilterEmptyChange;

function clearWbFbsPickScanField(inputId) {
  const el = document.getElementById(String(inputId || ""));
  if (!el || el.readOnly || el.disabled) return;
  el.value = "";
  el.focus();
}
window.clearWbFbsPickScanField = clearWbFbsPickScanField;

/** Same live RU-layout guard as Маркировка (`onWbFbsKizScanInputCheck`). */
function onWbFbsPickScanInputCheck(event) {
  onWbFbsKizScanInputCheck(event);
}
window.onWbFbsPickScanInputCheck = onWbFbsPickScanInputCheck;

async function closeWbFbsPickVerifyModal(opts) {
  const force = !!(opts && opts.force);
  if (!force) {
    try {
      await _wbFbsPickAwaitLocalAutosaves();
    } catch (_e) {
      /* keep going — confirm below if still dirty */
    }
  }
  if (!force && _wbFbsPickModalIsOpen() && _wbFbsPickHasUnsavedChanges()) {
    if (!confirm("Есть несохранённые изменения. Закрыть без сохранения?")) {
      return false;
    }
  }
  cancelWbFbsPickSkuScan();
  document.removeEventListener("keydown", _wbFbsKizRuLayoutSwallowKeys, true);
  setModalVisibility("wbFbsKizRuLayoutModal", false);
  setModalVisibility("wbFbsPickScanPrompt", false);
  setModalVisibility("wbFbsPickVerifyModal", false);
  wbFbsPickState.rows = [];
  wbFbsPickState.errors = {};
  wbFbsPickState.pendingOrderId = null;
  wbFbsPickState.baselineByOrder = {};
  wbFbsPickState.forceSaveByOrder = {};
  wbFbsPickState.localAutosaveSeqByOrder = {};
  _wbFbsPickResetFilters();
  _wbFbsPickSetFiltersReady(false);
  _wbFbsPickSetInfo("");
  return true;
}
window.closeWbFbsPickVerifyModal = closeWbFbsPickVerifyModal;

async function openWbFbsPickVerifyModal() {
  if (!isTenantOwner()) {
    alert("Проверка ШК доступна только главному пользователю");
    return;
  }
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || !_wbFbsSupplyDetailActionsReady()) return;
  setModalVisibility("wbFbsPickVerifyModal", true);
  wbFbsPickState.rows = [];
  wbFbsPickState.errors = {};
  wbFbsPickState.pendingOrderId = null;
  wbFbsPickState.baselineByOrder = {};
  wbFbsPickState.forceSaveByOrder = {};
  wbFbsPickState.localAutosaveSeqByOrder = {};
  _wbFbsPickResetFilters();
  _wbFbsPickSetFiltersReady(false);
  _wbFbsPickSetInfo("");
  const tbody = document.getElementById("wbFbsPickTbody");
  if (tbody) tbody.innerHTML = `<tr><td colspan="3" class="wb-fbs-empty">Загрузка…</td></tr>`;
  const saveBtn = document.getElementById("wbFbsPickVerifySaveBtn");
  if (saveBtn) saveBtn.disabled = true;
  const scan = document.getElementById("wbFbsPickStickerScan");
  if (scan) scan.value = "";
  let loadOk = false;
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/pick-verify?${params}`
    );
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    wbFbsPickState.rows = Array.isArray(data.rows) ? data.rows.map((r) => ({ ...r })) : [];
    _wbFbsPickCaptureBaseline();
    renderWbFbsPickVerifyTable();
    if (!wbFbsPickState.rows.length) {
      _wbFbsPickSetInfo("В поставке нет заказов без маркировки КИЗ", true);
    }
    loadOk = true;
  } catch (e) {
    if (tbody) {
      tbody.innerHTML = `<tr><td colspan="3" class="wb-fbs-empty" style="color:#b91c1c">${_wbFbsEsc(e.message || e)}</td></tr>`;
    }
    _wbFbsPickSetInfo(String(e.message || e));
  } finally {
    if (saveBtn) saveBtn.disabled = false;
    if (document.getElementById("wbFbsPickVerifyModal")
      && !document.getElementById("wbFbsPickVerifyModal").classList.contains("hidden")) {
      _wbFbsPickSetFiltersReady(true);
      if (loadOk && scan) {
        setTimeout(() => {
          try { scan.focus(); } catch (_) {}
        }, 50);
      }
    }
  }
}
window.openWbFbsPickVerifyModal = openWbFbsPickVerifyModal;

function _wbFbsPickCaptureBaseline() {
  const map = {};
  for (const r of wbFbsPickState.rows) {
    const oid = Number(r.order_id);
    if (!Number.isFinite(oid)) continue;
    map[oid] = {
      pick_verified: !!r.pick_verified,
      pick_barcode: String(r.pick_barcode || "").trim(),
    };
  }
  wbFbsPickState.baselineByOrder = map;
}

function _wbFbsPickModalIsOpen() {
  const modal = document.getElementById("wbFbsPickVerifyModal");
  return !!(modal && !modal.classList.contains("hidden"));
}

/** True when pick_verified / pick_barcode differ from last load/save baseline. */
function _wbFbsPickHasUnsavedChanges() {
  if (!Array.isArray(wbFbsPickState.rows) || !wbFbsPickState.rows.length) return false;
  if (!wbFbsPickState.baselineByOrder || !Object.keys(wbFbsPickState.baselineByOrder).length) {
    return false;
  }
  for (const r of wbFbsPickState.rows) {
    const oid = Number(r.order_id);
    if (!Number.isFinite(oid)) continue;
    if (!Object.prototype.hasOwnProperty.call(wbFbsPickState.baselineByOrder, oid)) continue;
    const base = wbFbsPickState.baselineByOrder[oid] || {};
    const verified = !!r.pick_verified && !!String(r.pick_barcode || "").trim();
    const barcode = String(r.pick_barcode || "").trim();
    const baseVerified = !!base.pick_verified && !!String(base.pick_barcode || "").trim();
    const baseBarcode = String(base.pick_barcode || "").trim();
    if (verified !== baseVerified || barcode !== baseBarcode) return true;
  }
  return false;
}

function _wbFbsPickBaselineEquals(orderId, verified, barcode) {
  const oid = Number(orderId);
  const base = wbFbsPickState.baselineByOrder?.[oid] || {};
  const baseVerified = !!base.pick_verified && !!String(base.pick_barcode || "").trim();
  const baseBarcode = String(base.pick_barcode || "").trim();
  const v = !!verified && !!String(barcode || "").trim();
  const b = String(barcode || "").trim();
  return v === baseVerified && b === baseBarcode;
}

/**
 * Queue a silent FeedPilot save for one pick-verify order (no UI spinner).
 * Coalesces rapid scans; never awaits in the scan path.
 */
function _wbFbsPickScheduleLocalAutosave(orderId) {
  const oid = Number(orderId);
  if (!Number.isFinite(oid) || oid <= 0) return;
  if (!wbFbsPickState.localAutosaveSeqByOrder) wbFbsPickState.localAutosaveSeqByOrder = {};
  const seq = (Number(wbFbsPickState.localAutosaveSeqByOrder[oid]) || 0) + 1;
  wbFbsPickState.localAutosaveSeqByOrder[oid] = seq;
  const run = () => _wbFbsPickFlushLocalAutosave(oid, seq);
  wbFbsPickState.localAutosaveChain = (wbFbsPickState.localAutosaveChain || Promise.resolve())
    .then(run, run)
    .catch(() => {});
}

function _wbFbsPickAwaitLocalAutosaves() {
  return (async () => {
    for (let i = 0; i < 40; i += 1) {
      const tip = wbFbsPickState.localAutosaveChain || Promise.resolve();
      try {
        await tip;
      } catch (_e) {
        /* ignore — Save/close confirm still cover drafts */
      }
      const latest = wbFbsPickState.localAutosaveChain || tip;
      const inflight = Number(wbFbsPickState.localAutosaveInflight) || 0;
      if (tip === latest && inflight <= 0) return;
    }
  })();
}

async function _wbFbsPickFlushLocalAutosave(orderId, seq, attempt = 0) {
  const oid = Number(orderId);
  if (!Number.isFinite(oid)) return;
  if ((Number(wbFbsPickState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
  if (!_wbFbsPickModalIsOpen()) return;
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId) return;
  const row = (wbFbsPickState.rows || []).find((r) => Number(r.order_id) === oid);
  if (!row) return;
  const verified = !!row.pick_verified && !!String(row.pick_barcode || "").trim();
  const barcode = String(row.pick_barcode || "").trim();
  const base = wbFbsPickState.baselineByOrder?.[oid] || {};
  const baseVerified = !!base.pick_verified && !!String(base.pick_barcode || "").trim();
  if (_wbFbsPickBaselineEquals(oid, verified, barcode)) return;
  // Empty never-saved row — nothing to clear on server.
  if (!verified && !baseVerified) return;

  let item;
  if (verified) {
    const check = _wbFbsPickValidateEanForOrder(barcode, row);
    if (!check.ok) {
      // Keep draft; operator sees error chip from scan path. Do not PUT bad EAN.
      return;
    }
    item = {
      order_id: oid,
      pick_verified: true,
      pick_barcode: check.barcode,
      barcodes: Array.isArray(row.barcodes) ? row.barcodes : [],
      expected_verified_at: String(row.pick_verified_at || ""),
      force: !!(wbFbsPickState.forceSaveByOrder && wbFbsPickState.forceSaveByOrder[oid]),
    };
  } else {
    item = {
      order_id: oid,
      pick_verified: false,
      pick_barcode: "",
      clear: true,
      expected_verified_at: String(row.pick_verified_at || ""),
      force: !!(wbFbsPickState.forceSaveByOrder && wbFbsPickState.forceSaveByOrder[oid]),
    };
  }

  wbFbsPickState.localAutosaveInflight = (Number(wbFbsPickState.localAutosaveInflight) || 0) + 1;
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/pick-verify?${params}`,
      {
        method: "PUT",
        headers: jsonHeaders(),
        body: JSON.stringify({ items: [item] }),
        keepalive: true,
      }
    );
    if ((Number(wbFbsPickState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    const result = (data.results || []).find((r) => Number(r.order_id) === oid) || null;
    if (!result) return;
    if (result.conflict) {
      row.pick_verified_at = String(result.pick_verified_at || row.pick_verified_at || "");
      if (!wbFbsPickState.forceSaveByOrder) wbFbsPickState.forceSaveByOrder = {};
      wbFbsPickState.forceSaveByOrder[oid] = true;
      _wbFbsPickSetInfo(
        result.error
          || "Заказ уже сохранён другим оператором — проверьте ШК и сохраните снова"
      );
      return;
    }
    if (!result.ok) {
      if (attempt < 1) {
        await new Promise((r) => setTimeout(r, 120));
        if ((Number(wbFbsPickState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
        return _wbFbsPickFlushLocalAutosave(oid, seq, attempt + 1);
      }
      return;
    }
    row.pick_verified = !!result.pick_verified;
    row.pick_barcode = String(result.pick_barcode || "").trim();
    if (result.pick_verified_at) row.pick_verified_at = String(result.pick_verified_at);
    if (!wbFbsPickState.baselineByOrder) wbFbsPickState.baselineByOrder = {};
    wbFbsPickState.baselineByOrder[oid] = {
      pick_verified: !!result.pick_verified,
      pick_barcode: String(result.pick_barcode || "").trim(),
    };
    if (wbFbsPickState.forceSaveByOrder) delete wbFbsPickState.forceSaveByOrder[oid];
    delete wbFbsPickState.errors[oid];
  } catch (_e) {
    if (attempt < 1) {
      await new Promise((r) => setTimeout(r, 120));
      if ((Number(wbFbsPickState.localAutosaveSeqByOrder?.[oid]) || 0) !== seq) return;
      return _wbFbsPickFlushLocalAutosave(oid, seq, attempt + 1);
    }
  } finally {
    wbFbsPickState.localAutosaveInflight = Math.max(
      0,
      (Number(wbFbsPickState.localAutosaveInflight) || 1) - 1
    );
  }
}

function _wbFbsPickStickerHtml(row) {
  const partA = String(row?.sticker_part_a || "").trim();
  const partB = String(row?.sticker_part_b || "").trim();
  const full = String(row?.sticker_number || "").trim();
  let head = partA;
  let tail = partB;
  if ((!head || !tail) && full) {
    if (full.length > 4) {
      head = full.slice(0, -4);
      tail = full.slice(-4);
    } else {
      head = "";
      tail = full;
    }
  }
  if (!head && !tail) return `<div class="wb-fbs-kiz-sticker">—</div>`;
  if (!tail) return `<div class="wb-fbs-kiz-sticker">${_wbFbsEsc(head)}</div>`;
  return `<div class="wb-fbs-kiz-sticker">` +
    (head ? `<span class="wb-fbs-kiz-sticker-head">${_wbFbsEsc(head)}</span>` : "") +
    `<span class="wb-fbs-kiz-sticker-tail">${_wbFbsEsc(tail)}</span>` +
    `</div>`;
}

function _wbFbsPickUpdateScanCounter() {
  const el = document.getElementById("wbFbsPickScanCount");
  if (!el) return;
  let filled = 0;
  const total = wbFbsPickState.rows.length;
  for (const row of wbFbsPickState.rows) {
    if (row.pick_verified && String(row.pick_barcode || "").trim()) filled += 1;
  }
  el.textContent = `Проверено ${filled} из ${total}`;
}

function _wbFbsPickRowMatchesSearch(row, q) {
  const needle = String(q || "").trim().toLowerCase();
  if (!needle) return true;
  const parts = [
    row.order_id,
    row.sticker_number,
    row.sticker_barcode,
    row.product_name,
    row.article,
    row.brand,
    row.pick_barcode,
    ...(Array.isArray(row.barcodes) ? row.barcodes : []),
  ];
  return parts.some((p) => String(p || "").toLowerCase().includes(needle));
}

function _wbFbsPickStatusHtml(row) {
  const oid = Number(row.order_id);
  const err = String(wbFbsPickState.errors[oid] || "").trim();
  const verified = !!row.pick_verified && !!String(row.pick_barcode || "").trim();
  let body = "";
  if (err) {
    body = `<div class="wb-fbs-pick-status is-error">${_wbFbsEsc(err)}</div>`;
  } else if (verified) {
    body = `<div class="wb-fbs-pick-status is-ok">✓ ${_wbFbsEsc(row.pick_barcode)}</div>`;
  } else {
    body = `<div class="wb-fbs-pick-status is-empty">Не проверено</div>`;
  }
  const showClear = verified || !!err;
  const clearBtn = showClear
    ? `<button type="button" class="wb-fbs-kiz-remove" title="Сбросить проверку"
               aria-label="Сбросить проверку"
               onclick="clearWbFbsPickVerify(${oid})">×</button>`
    : "";
  return `<div class="wb-fbs-pick-status-row">${body}${clearBtn}</div>`;
}

function clearWbFbsPickVerify(orderId) {
  const oid = Number(orderId);
  const row = wbFbsPickState.rows.find((r) => Number(r.order_id) === oid);
  if (!row || !Number.isFinite(oid)) return;
  row.pick_verified = false;
  row.pick_barcode = "";
  delete wbFbsPickState.errors[oid];
  if (!_wbFbsPickPatchStatusCell(oid)) {
    renderWbFbsPickVerifyTable();
  }
  _wbFbsPickSetInfo(`Заказ ${oid}: проверка сброшена.`, true);
  _wbFbsPickScheduleLocalAutosave(oid);
}
window.clearWbFbsPickVerify = clearWbFbsPickVerify;

function _wbFbsPickClearPendingHighlight() {
  document.querySelectorAll("#wbFbsPickTbody tr.wb-fbs-kiz-row.is-active").forEach((tr) => {
    tr.classList.remove("is-active");
  });
}

/** Fast path: highlight pending row without full table re-render (same idea as KIZ). */
function _wbFbsPickSetPendingHighlight(orderId) {
  _wbFbsPickClearPendingHighlight();
  const oid = Number(orderId);
  if (!Number.isFinite(oid)) return false;
  const tr = document.querySelector(`#wbFbsPickTbody tr.wb-fbs-kiz-row[data-order-id="${oid}"]`);
  if (!tr) return false;
  tr.classList.add("is-active");
  return true;
}

/**
 * Patch one status cell after a successful / failed SKU scan.
 * Returns false when the row is not in the DOM → caller should full-render.
 */
function _wbFbsPickPatchStatusCell(orderId) {
  const oid = Number(orderId);
  if (!Number.isFinite(oid)) return false;
  const tr = document.querySelector(`#wbFbsPickTbody tr.wb-fbs-kiz-row[data-order-id="${oid}"]`);
  if (!tr) return false;
  const cell = tr.querySelector(".wb-fbs-kiz-col-kiz");
  const row = wbFbsPickState.rows.find((r) => Number(r.order_id) === oid);
  if (!cell || !row) return false;
  cell.innerHTML = _wbFbsPickStatusHtml(row);
  _wbFbsPickClearPendingHighlight();
  _wbFbsPickUpdateScanCounter();
  return true;
}

function renderWbFbsPickVerifyTable() {
  const tbody = document.getElementById("wbFbsPickTbody");
  if (!tbody) return;
  const filledOn = !!document.getElementById("wbFbsPickFilterFilled")?.checked;
  const emptyOn = !!document.getElementById("wbFbsPickFilterEmpty")?.checked;
  const errorsOn = !!document.getElementById("wbFbsPickFilterErrors")?.checked;
  const cancelledOn = !!document.getElementById("wbFbsPickFilterCancelled")?.checked;
  const searchQ = document.getElementById("wbFbsPickSearchFilter")?.value || "";
  const pending = wbFbsPickState.pendingOrderId;
  let rows = wbFbsPickState.rows.slice();
  if (filledOn) rows = rows.filter((r) => !!r.pick_verified && String(r.pick_barcode || "").trim());
  if (emptyOn) rows = rows.filter((r) => !(r.pick_verified && String(r.pick_barcode || "").trim()));
  if (errorsOn) {
    rows = rows.filter((r) => wbFbsPickState.errors[Number(r.order_id)]);
  }
  if (cancelledOn) {
    rows = rows.filter((r) => String(r.cancel_reason_label || "").trim());
  }
  rows = rows.filter((r) => _wbFbsPickRowMatchesSearch(r, searchQ));
  _wbFbsPickUpdateScanCounter();
  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="3" class="wb-fbs-empty">${
      wbFbsPickState.rows.length ? "Нет строк по выбранным фильтрам" : "Нет заказов без КИЗ"
    }</td></tr>`;
    return;
  }
  tbody.innerHTML = rows.map((r) => {
    const oid = Number(r.order_id);
    const photo = r.product_photo
      ? `<img class="wb-fbs-product-photo" src="${_wbFbsEsc(r.product_photo)}" alt="" width="56" height="56" loading="lazy">`
      : `<span class="wb-fbs-product-ph" aria-hidden="true"></span>`;
    const brandArt = [r.brand, r.article ? `Арт. ${r.article}` : ""].filter(Boolean).join(" · ");
    const barcodes = Array.isArray(r.barcodes) ? r.barcodes : [];
    const barcodeHtml = barcodes.length
      ? `<div class="wb-fbs-kiz-barcodes" title="Штрихкод товара">${barcodes.map((b) =>
          `<div class="wb-fbs-kiz-barcode">${_wbFbsEsc(b)}</div>`
        ).join("")}</div>`
      : "";
    const cancelBadgeHtml = _wbFbsKizCancelBadgeHtml(r);
    const pendingCls = pending != null && Number(pending) === oid ? " is-active" : "";
    const stickerHtml = _wbFbsPickStickerHtml(r);
    return `<tr class="wb-fbs-kiz-row${pendingCls}" data-order-id="${oid}">
      <td>
        <div class="wb-fbs-kiz-order-id">${_wbFbsEsc(oid)}</div>
        <div class="wb-fbs-kiz-order-sticker">${stickerHtml}</div>
        <div class="wb-fbs-kiz-order-date">от ${_wbFbsEsc(r.created_date || "—")}</div>
      </td>
      <td>
        <div class="wb-fbs-product">
          ${photo}
          <div class="wb-fbs-product-text">
            <div class="wb-fbs-product-name" title="${_wbFbsEsc(r.product_name || r.article || "")}">${_wbFbsEsc(r.product_name || r.article || "—")}</div>
            <div class="wb-fbs-product-sub">${_wbFbsEsc(brandArt || "—")}</div>
            ${barcodeHtml}
            ${cancelBadgeHtml}
          </div>
        </div>
      </td>
      <td class="wb-fbs-kiz-col-kiz">${_wbFbsPickStatusHtml(r)}</td>
    </tr>`;
  }).join("");
}
window.renderWbFbsPickVerifyTable = renderWbFbsPickVerifyTable;

function _wbFbsPickNormalizeScan(value) {
  return _wbFbsFixRuKeyboardLayout(String(value || "").replace(/\s+/g, "")).trim();
}

function _wbFbsPickOrderSkuSet(row) {
  const set = new Set();
  for (const b of row?.barcodes || []) {
    const raw = String(b || "").trim();
    if (raw) set.add(raw);
    const digits = raw.replace(/\D/g, "");
    if (digits) {
      set.add(digits);
      if (digits.length === 14 && digits.startsWith("0")) set.add(digits.slice(1));
      if (digits.length === 13) set.add(`0${digits}`);
    }
  }
  return set;
}

/** Equivalence keys for EAN/GTIN (13↔14 with leading 0, etc.). */
function _wbFbsPickBarcodeKeys(value) {
  const raw = _wbFbsPickNormalizeScan(value);
  const digits = raw.replace(/\D/g, "");
  const set = new Set();
  if (raw) set.add(raw);
  if (digits) {
    set.add(digits);
    if (digits.length === 14 && digits.startsWith("0")) set.add(digits.slice(1));
    if (digits.length === 13) set.add(`0${digits}`);
  }
  return set;
}

function _wbFbsPickBarcodesMatch(a, b) {
  const left = _wbFbsPickBarcodeKeys(a);
  if (!left.size) return false;
  for (const k of _wbFbsPickBarcodeKeys(b)) {
    if (left.has(k)) return true;
  }
  return false;
}

function _wbFbsPickValidateEanForOrder(scan, row) {
  const raw = _wbFbsPickNormalizeScan(scan);
  const digits = raw.replace(/\D/g, "");
  if (!digits) {
    return { ok: false, error: "Отсканируйте штрихкод товара (EAN-13)" };
  }
  if (![8, 12, 13, 14].includes(digits.length)) {
    return {
      ok: false,
      error: `Ожидается EAN/GTIN (8–14 цифр), получено ${digits.length}`,
    };
  }
  const orderSkus = _wbFbsPickOrderSkuSet(row);
  if (!orderSkus.size) {
    return {
      ok: false,
      error: "У заказа нет штрихкодов товара — нельзя сверить ШК",
    };
  }
  const candidates = new Set([digits, raw]);
  if (digits.length === 14 && digits.startsWith("0")) candidates.add(digits.slice(1));
  if (digits.length === 13) candidates.add(`0${digits}`);
  let matched = false;
  for (const c of candidates) {
    if (orderSkus.has(c)) {
      matched = true;
      break;
    }
  }
  if (!matched) {
    const shown = digits.length === 14 && digits.startsWith("0") ? digits.slice(1) : digits;
    const skuList = [...orderSkus].filter((s) => /^\d+$/.test(s)).slice(0, 6).join(", ");
    return {
      ok: false,
      error: `ШК ${shown} не совпадает ни с одним ШК товара в заказе${skuList ? ` (${skuList})` : ""}.`,
    };
  }
  const normalized = digits.length === 14 && digits.startsWith("0") ? digits.slice(1) : digits;
  return { ok: true, barcode: normalized };
}

function _wbFbsPickScanKey(value) {
  // Same as Маркировка (_wbFbsKizScanKey): scanners may flip letter case.
  return _wbFbsKizNormalizeScan(value).toLocaleLowerCase("en-US");
}

function _wbFbsPickFindBySticker(scan) {
  // Same algorithm as _wbFbsKizFindBySticker, but over non-КИЗ pick rows only.
  const raw = _wbFbsKizNormalizeScan(scan);
  if (!raw) return { row: null, ambiguous: false };
  const rawKey = _wbFbsPickScanKey(raw);
  // Primary: QR / 1D scan value from WB stickers.barcode (e.g. !uKEtQZVx).
  const byBarcode = [];
  for (const row of wbFbsPickState.rows) {
    const bc = _wbFbsKizNormalizeScan(row.sticker_barcode);
    if (bc && _wbFbsPickScanKey(bc) === rawKey) byBarcode.push(row);
  }
  if (byBarcode.length === 1) return { row: byBarcode[0], ambiguous: false };
  if (byBarcode.length > 1) {
    return { row: null, ambiguous: true, matches: byBarcode };
  }

  // Fallback: human-readable partA+partB / partB (portal sticker number).
  const digits = raw.replace(/\D+/g, "");
  const matches = [];
  for (const row of wbFbsPickState.rows) {
    const full = _wbFbsKizNormalizeScan(row.sticker_number);
    const partA = _wbFbsKizNormalizeScan(row.sticker_part_a);
    const partB = _wbFbsKizNormalizeScan(row.sticker_part_b);
    if (
      (full && (rawKey === _wbFbsPickScanKey(full) || digits === full.replace(/\D+/g, ""))) ||
      (partA && partB && digits === `${partA}${partB}`.replace(/\D+/g, "")) ||
      (partB && (rawKey === _wbFbsPickScanKey(partB) || digits === partB.replace(/\D+/g, "")))
    ) {
      matches.push(row);
    }
  }
  if (matches.length === 1) return { row: matches[0], ambiguous: false };
  if (matches.length > 1) {
    const exact = matches.find((r) => {
      const full = _wbFbsKizNormalizeScan(r.sticker_number);
      return _wbFbsPickScanKey(full) === rawKey || full.replace(/\D+/g, "") === digits;
    });
    if (exact) return { row: exact, ambiguous: false };
    return { row: null, ambiguous: true, matches };
  }
  return { row: null, ambiguous: false };
}

function onWbFbsPickStickerScanKey(event) {
  if (!event || event.key !== "Enter") return;
  event.preventDefault();
  if (_wbFbsKizRuLayoutModalOpen()) return;
  const input = event.target;
  if (input && (input.readOnly || input.disabled || !wbFbsPickState.rowsReady)) return;
  const rawTyped = String(input?.value || "").replace(/\s+/g, "").trim();
  if (!rawTyped) return;
  // Cyrillic first — before sticker↔order match (same as Маркировка).
  if (_wbFbsKizHasCyrillic(rawTyped)) {
    _wbFbsKizBlockRuLayout(input);
    return;
  }
  const scan = _wbFbsKizNormalizeScan(rawTyped);
  if (!scan) return;
  const found = _wbFbsPickFindBySticker(scan);
  if (found.ambiguous) {
    const ids = (found.matches || []).map((r) => r.order_id).slice(0, 5).join(", ");
    _wbFbsPickSetInfo(
      `Код стикера совпадает у нескольких заказов (${ids}${
        (found.matches || []).length > 5 ? "…" : ""
      }). Отсканируйте QR стикера ещё раз.`
    );
    if (input) input.select();
    return;
  }
  if (!found.row) {
    _wbFbsPickSetInfo(
      `Заказ со стикером «${scan}» не найден среди товаров без маркировки. Возможно, это товар с маркировкой.`
    );
    if (input) input.select();
    return;
  }
  _wbFbsPickSetInfo("");
  if (input) input.value = "";
  beginWbFbsPickSkuScan(Number(found.row.order_id));
}
window.onWbFbsPickStickerScanKey = onWbFbsPickStickerScanKey;

function beginWbFbsPickSkuScan(orderId) {
  const oid = Number(orderId);
  const row = wbFbsPickState.rows.find((r) => Number(r.order_id) === oid);
  if (!row) return;
  wbFbsPickState.pendingOrderId = oid;
  // Fast path: toggle is-active only. Full render if the row is filtered out of DOM.
  if (!_wbFbsPickSetPendingHighlight(oid)) {
    renderWbFbsPickVerifyTable();
  }
  const meta = document.getElementById("wbFbsPickScanPromptMeta");
  if (meta) {
    meta.textContent = `Заказ ${oid} · стикер ${row.sticker_number || "—"}`;
  }
  setModalVisibility("wbFbsPickScanPrompt", true);
  const sku = document.getElementById("wbFbsPickSkuScan");
  if (sku) {
    sku.value = "";
    setTimeout(() => sku.focus(), 40);
  }
}

function cancelWbFbsPickSkuScan() {
  setModalVisibility("wbFbsPickScanPrompt", false);
  wbFbsPickState.pendingOrderId = null;
  _wbFbsPickClearPendingHighlight();
  const sticker = document.getElementById("wbFbsPickStickerScan");
  if (sticker) setTimeout(() => sticker.focus(), 40);
}
window.cancelWbFbsPickSkuScan = cancelWbFbsPickSkuScan;

function onWbFbsPickSkuScanKey(event) {
  if (!event || event.key !== "Enter") return;
  event.preventDefault();
  if (_wbFbsKizRuLayoutModalOpen()) return;
  const oid = Number(wbFbsPickState.pendingOrderId);
  const input = event.target;
  const rawTyped = String(input?.value || "");
  if (!oid || !String(rawTyped || "").replace(/\s+/g, "")) return;
  // Cyrillic first — same guard as Маркировка mark-scan.
  if (_wbFbsKizHasCyrillic(rawTyped)) {
    _wbFbsKizBlockRuLayout(input);
    return;
  }
  const row = wbFbsPickState.rows.find((r) => Number(r.order_id) === oid);
  if (!row) {
    cancelWbFbsPickSkuScan();
    return;
  }
  const check = _wbFbsPickValidateEanForOrder(rawTyped, row);
  if (!check.ok) {
    wbFbsPickState.errors[oid] = check.error || "ШК не подходит";
    _wbFbsPickSetInfo(check.error || "ШК не подходит к товару в заказе");
    if (input) input.select();
    // Patch status in-place when possible (errors filter may hide the row).
    if (!_wbFbsPickPatchStatusCell(oid)) {
      renderWbFbsPickVerifyTable();
    }
    return;
  }
  const existing = String(row.pick_barcode || "").trim();
  if (row.pick_verified && existing) {
    // Same as Маркировка: do not silently overwrite an already filled scan.
    if (_wbFbsPickBarcodesMatch(existing, check.barcode)) {
      _wbFbsPickSetInfo(
        `Этот ШК уже просканирован в заказ ${oid} — повторно не добавляем`
      );
    } else {
      _wbFbsPickSetInfo(
        `Заказ ${oid} уже проверен (ШК ${existing}). Сбросьте проверку (×), чтобы сканировать другой ШК.`
      );
    }
    if (input) input.select();
    return;
  }
  row.pick_verified = true;
  row.pick_barcode = check.barcode;
  delete wbFbsPickState.errors[oid];
  setModalVisibility("wbFbsPickScanPrompt", false);
  wbFbsPickState.pendingOrderId = null;
  // Show the filled row even if «Незаполненные» filter was on.
  const emptyFilter = document.getElementById("wbFbsPickFilterEmpty");
  const emptyFilterWasOn = !!emptyFilter?.checked;
  if (emptyFilter) emptyFilter.checked = false;
  _wbFbsPickSetInfo(`Заказ ${oid}: ШК ${check.barcode} совпал.`, true);
  // Full render when filter set changes; otherwise patch one status cell.
  if (emptyFilterWasOn || !_wbFbsPickPatchStatusCell(oid)) {
    renderWbFbsPickVerifyTable();
  }
  _wbFbsPickScheduleLocalAutosave(oid);
  const rowEl = document.querySelector(`#wbFbsPickTbody tr[data-order-id="${oid}"]`);
  if (rowEl) rowEl.scrollIntoView({ block: "nearest", behavior: "smooth" });
  const sticker = document.getElementById("wbFbsPickStickerScan");
  if (sticker) {
    sticker.value = "";
    setTimeout(() => sticker.focus(), 40);
  }
}
window.onWbFbsPickSkuScanKey = onWbFbsPickSkuScanKey;

async function saveWbFbsPickVerifyModal() {
  const sid = String(wbFbsDetailState.supplyId || "").trim();
  if (!sid || !wbFbsState.sourceId || wbFbsPickState.saving) return;
  if (!isTenantOwner()) {
    alert("Проверка ШК доступна только главному пользователю");
    return;
  }
  const saveBtn = document.getElementById("wbFbsPickVerifySaveBtn");
  wbFbsPickState.saving = true;
  if (saveBtn) saveBtn.disabled = true;
  try {
    await _wbFbsPickAwaitLocalAutosaves();
  } catch (_e) {
    /* continue — Save still pushes remaining dirty rows */
  }
  const items = [];
  wbFbsPickState.errors = {};
  for (const r of wbFbsPickState.rows) {
    const oid = Number(r.order_id);
    if (!Number.isFinite(oid)) continue;
    const base = wbFbsPickState.baselineByOrder?.[oid] || {};
    const verified = !!r.pick_verified && !!String(r.pick_barcode || "").trim();
    const barcode = String(r.pick_barcode || "").trim();
    const baseVerified = !!base.pick_verified && !!String(base.pick_barcode || "").trim();
    const baseBarcode = String(base.pick_barcode || "").trim();
    if (verified === baseVerified && barcode === baseBarcode) continue;
    if (verified) {
      const check = _wbFbsPickValidateEanForOrder(barcode, r);
      if (!check.ok) {
        wbFbsPickState.errors[oid] = check.error || "ШК не прошёл сверку";
        continue;
      }
      items.push({
        order_id: oid,
        pick_verified: true,
        pick_barcode: check.barcode,
        barcodes: Array.isArray(r.barcodes) ? r.barcodes : [],
        expected_verified_at: String(r.pick_verified_at || ""),
        force: !!(wbFbsPickState.forceSaveByOrder && wbFbsPickState.forceSaveByOrder[oid]),
      });
    } else if (baseVerified) {
      items.push({
        order_id: oid,
        pick_verified: false,
        pick_barcode: "",
        clear: true,
        expected_verified_at: String(r.pick_verified_at || ""),
        force: !!(wbFbsPickState.forceSaveByOrder && wbFbsPickState.forceSaveByOrder[oid]),
      });
    }
  }
  if (Object.keys(wbFbsPickState.errors).length) {
    wbFbsPickState.saving = false;
    if (saveBtn) saveBtn.disabled = false;
    renderWbFbsPickVerifyTable();
    _wbFbsPickSetInfo("Исправьте ошибки сверки ШК перед сохранением");
    return;
  }
  if (!items.length) {
    wbFbsPickState.saving = false;
    if (saveBtn) saveBtn.disabled = false;
    _wbFbsPickSetInfo("Нет изменений для сохранения", true);
    return;
  }
  _wbFbsPickSetInfo(`Сохранение ${items.length}…`, true);
  try {
    const params = new URLSearchParams({ source_id: String(wbFbsState.sourceId) });
    const res = await fetch(
      `/api/wb-fbs/supplies/${encodeURIComponent(sid)}/pick-verify?${params}`,
      {
        method: "PUT",
        headers: jsonHeaders(),
        body: JSON.stringify({ items }),
      }
    );
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    let okN = 0;
    let errN = 0;
    let conflictN = 0;
    for (const row of data.results || []) {
      const oid = Number(row.order_id);
      if (!Number.isFinite(oid)) continue;
      const local = wbFbsPickState.rows.find((x) => Number(x.order_id) === oid);
      if (row.conflict) {
        conflictN += 1;
        errN += 1;
        if (local) {
          const base = wbFbsPickState.baselineByOrder?.[oid] || {};
          const localVerified = !!local.pick_verified && !!String(local.pick_barcode || "").trim();
          const localBarcode = String(local.pick_barcode || "").trim();
          const baseVerified = !!base.pick_verified && !!String(base.pick_barcode || "").trim();
          const baseBarcode = String(base.pick_barcode || "").trim();
          const localChanged = localVerified !== baseVerified || localBarcode !== baseBarcode;
          local.pick_verified_at = String(row.pick_verified_at || local.pick_verified_at || "");
          if (!localChanged) {
            local.pick_verified = !!row.pick_verified;
            local.pick_barcode = String(row.pick_barcode || "").trim();
            if (!wbFbsPickState.baselineByOrder) wbFbsPickState.baselineByOrder = {};
            wbFbsPickState.baselineByOrder[oid] = {
              pick_verified: !!row.pick_verified,
              pick_barcode: String(row.pick_barcode || "").trim(),
            };
            if (wbFbsPickState.forceSaveByOrder) delete wbFbsPickState.forceSaveByOrder[oid];
          } else if (!wbFbsPickState.forceSaveByOrder) {
            wbFbsPickState.forceSaveByOrder = { [oid]: true };
          } else {
            wbFbsPickState.forceSaveByOrder[oid] = true;
          }
        }
        wbFbsPickState.errors[oid] = String(
          row.error
          || "Заказ уже сохранён другим оператором — проверьте ШК и сохраните снова"
        );
        continue;
      }
      if (row.ok) {
        okN += 1;
        if (local) {
          local.pick_verified = !!row.pick_verified;
          local.pick_barcode = String(row.pick_barcode || "").trim();
          if (row.pick_verified_at) local.pick_verified_at = String(row.pick_verified_at);
        }
        if (!wbFbsPickState.baselineByOrder) wbFbsPickState.baselineByOrder = {};
        wbFbsPickState.baselineByOrder[oid] = {
          pick_verified: !!row.pick_verified,
          pick_barcode: String(row.pick_barcode || "").trim(),
        };
        if (wbFbsPickState.forceSaveByOrder) delete wbFbsPickState.forceSaveByOrder[oid];
        delete wbFbsPickState.errors[oid];
      } else {
        errN += 1;
        wbFbsPickState.errors[oid] = String(row.error || "Ошибка сохранения");
      }
    }
    renderWbFbsPickVerifyTable();
    if (conflictN) {
      _wbFbsPickSetInfo(
        `Конфликт с другим оператором: ${conflictN}. Проверьте отмеченные заказы и сохраните снова.`
      );
    } else if (errN) {
      _wbFbsPickSetInfo(`Сохранено ${okN}, ошибок ${errN}`);
    } else {
      _wbFbsPickSetInfo(
        `Сохранено: ${okN}. Данные только в FeedPilot (на WB не отправлялись).`,
        true
      );
    }
  } catch (e) {
    _wbFbsPickSetInfo(String(e.message || e));
  } finally {
    wbFbsPickState.saving = false;
    if (saveBtn) saveBtn.disabled = false;
  }
}
window.saveWbFbsPickVerifyModal = saveWbFbsPickVerifyModal;

