window.wbFbsPrintOneOrderStickerFromDetail = wbFbsPrintOneOrderStickerFromDetail;

function _wbFbsSupplyQrPayload(supplyId) {
  return String(supplyId || "").trim();
}

function _wbFbsSupplyQrMeta(supplyId) {
  const sid = _wbFbsSupplyQrPayload(supplyId);
  const detail = wbFbsDetailState.supply;
  if (detail && String(detail.supply_id || "").trim() === sid) {
    const qty = Number(detail.order_count);
    return {
      orderCount: Number.isFinite(qty) && qty > 0 ? Math.round(qty) : 0,
      city: String(detail.warehouse_label || "").trim(),
    };
  }
  // Supply-list rows (assembly/delivery) carry order_count / order_ids.
  const supplyRow = (wbFbsState.items || []).find(
    (x) => String(x?.supply_id || "").trim() === sid && (
      x.order_count != null || Array.isArray(x.order_ids)
    )
  );
  if (supplyRow) {
    const qty = Number(supplyRow.order_count);
    const fromIds = Array.isArray(supplyRow.order_ids) ? supplyRow.order_ids.length : 0;
    return {
      orderCount: Number.isFinite(qty) && qty > 0 ? Math.round(qty) : fromIds,
      city: String(
        supplyRow.warehouse_label
        || supplyRow.warehouse_name
        || supplyRow.office_name
        || ""
      ).trim(),
    };
  }
  // Order-list rows: count unique orders for this supply id.
  const orderRows = (wbFbsState.items || []).filter(
    (x) => String(x?.supply_id || "").trim() === sid && x.order_id != null
  );
  const orderIds = new Set(
    orderRows.map((r) => Number(r.order_id)).filter((n) => Number.isFinite(n) && n > 0)
  );
  const first = orderRows[0] || {};
  return {
    orderCount: orderIds.size,
    city: String(
      first.warehouse_label
      || first.warehouse_name
      || first.office_name
      || ""
    ).trim(),
  };
}

function _wbFbsMakeQrDataUrl(text, size) {
  const value = String(text || "").trim();
  if (!value) return Promise.reject(new Error("Нет кода поставки для QR"));
  if (typeof QRCode === "undefined") {
    return Promise.reject(new Error("Библиотека QR ещё загружается. Попробуйте снова."));
  }
  const px = Math.max(128, Math.min(1024, Number(size) || 512));
  const host = document.createElement("div");
  host.style.cssText = "position:fixed;left:-9999px;top:0;width:0;height:0;overflow:hidden;";
  document.body.appendChild(host);
  try {
    // qrcodejs draws canvas synchronously for modern browsers.
    new QRCode(host, {
      text: value,
      width: px,
      height: px,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: QRCode.CorrectLevel.M,
    });
    const canvas = host.querySelector("canvas");
    if (canvas && typeof canvas.toDataURL === "function") {
      return Promise.resolve(canvas.toDataURL("image/png"));
    }
    const img = host.querySelector("img");
    if (img && img.src) return Promise.resolve(img.src);
    return Promise.reject(new Error("Не удалось сформировать QR-код поставки"));
  } catch (e) {
    return Promise.reject(e);
  } finally {
    try { host.remove(); } catch (_) {}
  }
}

function _wbFbsSupplyQrPrintHtml(sid, qrDataUrl, qtyLabel, city) {
  // Official WB supply sticker: 58×40, QR center, id left / qty+city right (vertical).
  // Side rails reserve space so rotated text never overlaps the quiet zone.
  const rightLines = [qtyLabel, city].filter(Boolean)
    .map((t) => `<div>${_wbFbsEsc(t)}</div>`)
    .join("");
  return `<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><title>QR поставки ${_wbFbsEsc(sid)}</title>
<style>
@page { size: 58mm 40mm; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { margin: 0; padding: 0; background: #fff; color: #000;
  font-family: Arial, Helvetica, sans-serif; }
.toolbar { padding: 8px 12px; }
.toolbar button {
  font: 14px/1.2 Arial, Helvetica, sans-serif; padding: 6px 12px; cursor: pointer;
}
.toolbar span { margin-left: 8px; color: #64748b; font-size: 13px; }
.sheet {
  width: 58mm; height: 40mm; overflow: hidden;
  display: grid;
  grid-template-columns: 11mm 1fr 11mm;
  align-items: center;
  column-gap: 1.5mm;
  padding: 2mm 1.5mm;
}
.rail {
  height: 36mm; width: 11mm;
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.rail-inner {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 1.2mm;
  transform: rotate(-90deg);
  white-space: nowrap;
  font-weight: 700; font-size: 3.1mm; line-height: 1.1;
  letter-spacing: 0.02em; text-align: center;
}
.qr-wrap {
  height: 36mm;
  display: flex; align-items: center; justify-content: center;
}
.qr {
  width: 28mm; height: 28mm;
  object-fit: contain;
  display: block;
}
@media print {
  .toolbar { display: none !important; }
  html, body { width: 58mm; height: 40mm; overflow: hidden; }
}
</style></head><body>
<div class="toolbar">
  <button type="button" onclick="window.print()">Печать</button>
  <span>QR поставки · ${_wbFbsEsc(sid)} · 58×40 мм</span>
</div>
<section class="sheet">
  <div class="rail"><div class="rail-inner">${_wbFbsEsc(sid)}</div></div>
  <div class="qr-wrap"><img class="qr" alt="QR ${_wbFbsEsc(sid)}" src="${qrDataUrl}" /></div>
  <div class="rail"><div class="rail-inner">${rightLines}</div></div>
</section>
<script>
window.addEventListener("load", function () {
  setTimeout(function () { window.print(); }, 300);
});
<\/script>
</body></html>`;
}

/**
 * Local supply QR sticker from WB-GI id (no WB /barcode API).
 * Layout matches portal sticker: QR + left id + right qty/city.
 * Opens in a new tab like other stickers (no sized popup window).
 */
async function wbFbsOpenSupplyQr(supplyId, opts) {
  _wbFbsCloseRowMenus();
  const sid = _wbFbsSupplyQrPayload(supplyId || wbFbsDetailState.supplyId);
  if (!sid) return;
  // Prefer a pre-opened tab (multi-print); otherwise open now in the click stack.
  // No window features → browser opens a tab (same as stickers-print).
  let win = opts && opts.win ? opts.win : null;
  if (!win) {
    win = window.open("", "_blank");
  }
  if (!win) {
    throw new Error("Разрешите всплывающие окна, чтобы открыть QR-код поставки");
  }
  try {
    win.document.write("<!DOCTYPE html><title>QR…</title><body style=\"font:14px sans-serif;padding:16px\">Формируем QR…</body>");
    win.document.close();
  } catch (_) {}
  try {
    const meta = _wbFbsSupplyQrMeta(sid);
    const qty = Number(meta.orderCount) || 0;
    const city = String(meta.city || "").trim();
    const qtyLabel = qty > 0 ? `${qty} шт.` : "";
    const qrDataUrl = await _wbFbsMakeQrDataUrl(sid, 640);
    const html = _wbFbsSupplyQrPrintHtml(sid, qrDataUrl, qtyLabel, city);
    win.document.open();
    win.document.write(html);
    win.document.close();
  } catch (e) {
    try { win.close(); } catch (_) {}
    throw e;
  }
}
window.wbFbsOpenSupplyQr = wbFbsOpenSupplyQr;

