async function openWbFbsAutoSyncSettings() {
  if (!_wbFbsCanViewOwnerTabs()) {
    alert("Настройки автоматики доступны только главному пользователю");
    return;
  }
  const modal = document.getElementById("wbFbsAutoSyncModal");
  if (!modal) return;
  modal.classList.remove("hidden");
  _wbFbsAutoSyncSetInfo("");
  _wbFbsAutoSyncSetLast(null, null);
  _wbFbsAutoCollectSetLast(null, null, "");
  const saveBtn = document.getElementById("wbFbsAutoSyncSaveBtn");
  const enabledEl = document.getElementById("wbFbsAutoSyncEnabled");
  const intervalEl = document.getElementById("wbFbsAutoSyncInterval");
  const lookbackEl = document.getElementById("wbFbsAutoSyncLookback");
  const syncFromEl = document.getElementById("wbFbsAutoSyncFrom");
  const syncToEl = document.getElementById("wbFbsAutoSyncTo");
  const collectEnabledEl = document.getElementById("wbFbsAutoCollectEnabled");
  const collectIntervalEl = document.getElementById("wbFbsAutoCollectInterval");
  const collectFromEl = document.getElementById("wbFbsAutoCollectFrom");
  const collectToEl = document.getElementById("wbFbsAutoCollectTo");
  if (saveBtn) saveBtn.disabled = true;
  try {
    const res = await fetch("/api/wb-fbs/auto-sync-settings");
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || `Ошибка ${res.status}`);
    if (enabledEl) enabledEl.checked = !!data.enabled;
    // Prefer minutes; fall back from legacy hours (1→60, 2→120, …).
    let syncMinutes = Number(data.interval_minutes);
    if (!Number.isFinite(syncMinutes) || syncMinutes <= 0) {
      const legacyHours = Number(data.interval_hours);
      syncMinutes = Number.isFinite(legacyHours) && legacyHours > 0
        ? Math.round(legacyHours * 60)
        : 60;
    }
    _wbFbsSetSelectValue(intervalEl, syncMinutes, 60);
    if (lookbackEl) {
      const minD = Number(data.lookback_days_min) || 1;
      const maxD = Number(data.lookback_days_max) || 30;
      lookbackEl.min = String(minD);
      lookbackEl.max = String(maxD);
      let days = Number(data.lookback_days);
      if (!Number.isFinite(days)) days = 3;
      lookbackEl.value = String(Math.min(maxD, Math.max(minD, Math.round(days))));
    }
    if (syncFromEl) syncFromEl.value = String(data.active_from || "12:00");
    if (syncToEl) syncToEl.value = String(data.active_to || "06:00");
    if (collectEnabledEl) collectEnabledEl.checked = !!data.collect_mgt_enabled;
    let collectMinutes = Number(data.collect_mgt_interval_minutes);
    if (!Number.isFinite(collectMinutes) || collectMinutes <= 0) {
      const legacyCollectHours = Number(data.collect_mgt_interval_hours);
      collectMinutes = Number.isFinite(legacyCollectHours) && legacyCollectHours > 0
        ? Math.round(legacyCollectHours * 60)
        : 60;
    }
    _wbFbsSetSelectValue(collectIntervalEl, collectMinutes, 60);
    if (collectFromEl) collectFromEl.value = String(data.collect_mgt_active_from || "12:00");
    if (collectToEl) collectToEl.value = String(data.collect_mgt_active_to || "06:00");
    _wbFbsAutoSyncSetLast(data.last_synced_at, data.last_auto_synced_at);
    _wbFbsAutoCollectSetLast(
      data.last_collect_mgt_at || data.collect_mgt_last_run_at,
      data.collect_mgt_last_run_at,
      data.collect_mgt_last_status,
      data.collect_mgt_last_detail
    );
    const canEdit = data.can_edit !== false;
    if (enabledEl) enabledEl.disabled = !canEdit;
    if (collectEnabledEl) collectEnabledEl.disabled = !canEdit;
    if (saveBtn) {
      saveBtn.disabled = !canEdit;
      saveBtn.title = canEdit ? "" : "Недостаточно прав для изменения настроек";
    }
    if (!canEdit) {
      _wbFbsAutoSyncSetInfo("Просмотр настроек. Изменять может только владелец кабинета.");
    }
    _wbFbsAutoSyncApplyEnabledUi();
    _wbFbsAutoCollectApplyEnabledUi();
    if (!canEdit) {
      if (intervalEl) intervalEl.disabled = true;
      if (lookbackEl) lookbackEl.disabled = true;
      if (syncFromEl) syncFromEl.disabled = true;
      if (syncToEl) syncToEl.disabled = true;
      if (collectIntervalEl) collectIntervalEl.disabled = true;
      if (collectFromEl) collectFromEl.disabled = true;
      if (collectToEl) collectToEl.disabled = true;
    }
    _wbFbsAutoSyncMarkGear(!!data.enabled, !!data.collect_mgt_enabled);
  } catch (e) {
    _wbFbsAutoSyncSetInfo(String(e.message || e), "error");
  }
}
window.openWbFbsAutoSyncSettings = openWbFbsAutoSyncSettings;

function closeWbFbsAutoSyncSettings() {
  const modal = document.getElementById("wbFbsAutoSyncModal");
  if (modal) modal.classList.add("hidden");
}
window.closeWbFbsAutoSyncSettings = closeWbFbsAutoSyncSettings;

function _wbFbsNormTimeInput(value, fallback) {
  const raw = String(value || "").trim();
  const m = raw.match(/^(\d{1,2}):(\d{2})/);
  if (!m) return String(fallback || "12:00");
  const hh = String(Math.min(23, Math.max(0, Number(m[1])))).padStart(2, "0");
  const mm = String(Math.min(59, Math.max(0, Number(m[2])))).padStart(2, "0");
  return `${hh}:${mm}`;
}

async function saveWbFbsAutoSyncSettings() {
  if (!_wbFbsCanViewOwnerTabs()) {
    alert("Настройки автоматики доступны только главному пользователю");
    return;
  }
  const enabled = !!document.getElementById("wbFbsAutoSyncEnabled")?.checked;
  const intervalMinutes = Number(document.getElementById("wbFbsAutoSyncInterval")?.value || 60);
  const lookbackRaw = Number(document.getElementById("wbFbsAutoSyncLookback")?.value);
  const lookbackDays = Number.isFinite(lookbackRaw) ? Math.round(lookbackRaw) : 3;
  if (lookbackDays < 1 || lookbackDays > 30) {
    _wbFbsAutoSyncSetInfo("Глубина загрузки заказов: от 1 до 30 дней", "error");
    return;
  }
  const syncFrom = _wbFbsNormTimeInput(
    document.getElementById("wbFbsAutoSyncFrom")?.value,
    "12:00"
  );
  const syncTo = _wbFbsNormTimeInput(
    document.getElementById("wbFbsAutoSyncTo")?.value,
    "06:00"
  );
  const collectEnabled = !!document.getElementById("wbFbsAutoCollectEnabled")?.checked;
  const collectIntervalMinutes = Number(
    document.getElementById("wbFbsAutoCollectInterval")?.value || 60
  );
  const collectFrom = _wbFbsNormTimeInput(
    document.getElementById("wbFbsAutoCollectFrom")?.value,
    "12:00"
  );
  const collectTo = _wbFbsNormTimeInput(
    document.getElementById("wbFbsAutoCollectTo")?.value,
    "06:00"
  );
  const saveBtn = document.getElementById("wbFbsAutoSyncSaveBtn");
  if (saveBtn) saveBtn.disabled = true;
  _wbFbsAutoSyncSetInfo("Сохранение…");
  try {
    const res = await fetch("/api/wb-fbs/auto-sync-settings", {
      method: "PUT",
      headers: jsonHeaders(),
      body: JSON.stringify({
        enabled,
        interval_minutes: intervalMinutes,
        lookback_days: lookbackDays,
        active_from: syncFrom,
        active_to: syncTo,
        collect_mgt_enabled: collectEnabled,
        collect_mgt_interval_minutes: collectIntervalMinutes,
        collect_mgt_active_from: collectFrom,
        collect_mgt_active_to: collectTo,
      }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data.ok) {
      throw new Error(data.detail || data.message || `Ошибка ${res.status}`);
    }
    const settings = data.settings || {};
    _wbFbsAutoSyncMarkGear(!!settings.enabled, !!settings.collect_mgt_enabled);
    _wbFbsAutoSyncSetLast(settings.last_synced_at, settings.last_auto_synced_at);
    _wbFbsAutoCollectSetLast(
      settings.last_collect_mgt_at || settings.collect_mgt_last_run_at,
      settings.collect_mgt_last_run_at,
      settings.collect_mgt_last_status,
      settings.collect_mgt_last_detail
    );
    _wbFbsAutoSyncSetInfo("Сохранено", "ok");
    setTimeout(() => closeWbFbsAutoSyncSettings(), 400);
  } catch (e) {
    _wbFbsAutoSyncSetInfo(String(e.message || e), "error");
    if (saveBtn) saveBtn.disabled = false;
  }
}
window.saveWbFbsAutoSyncSettings = saveWbFbsAutoSyncSettings;

async function _wbFbsRefreshAutoSyncGear() {
  if (!_wbFbsCanViewOwnerTabs()) {
    _wbFbsSyncOwnerOnlyGear();
    return;
  }
  try {
    const res = await fetch("/api/wb-fbs/auto-sync-settings");
    if (!res.ok) return;
    const data = await res.json().catch(() => ({}));
    _wbFbsAutoSyncMarkGear(!!data.enabled, !!data.collect_mgt_enabled);
  } catch (_) {}
}

async function syncWbFbs() {
  // Sync every FBS source shown in the picker (name contains ФБС/FBS).
  if (!wbFbsState.sources.length) {
    alert("Нет источников с «ФБС» в названии");
    return;
  }
  const syncBtn = document.getElementById("wbFbsSyncBtn");
  const stopBtn = document.getElementById("wbFbsStopBtn");
  if (syncBtn) syncBtn.disabled = true;
  if (stopBtn) stopBtn.classList.remove("hidden");
  const n = wbFbsState.sources.length;
  _wbFbsSetSyncInfo(`Запуск синхронизации… источников: ${n}`);
  try {
    const res = await fetch("/api/wb-fbs/sync", {
      method: "POST",
      headers: jsonHeaders(),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data.ok) {
      _wbFbsSetSyncInfo(data.message || data.detail || `Ошибка ${res.status || "сети"}`, "error");
      if (syncBtn) syncBtn.disabled = false;
      if (stopBtn) stopBtn.classList.add("hidden");
      return;
    }
    if (data.message) _wbFbsSetSyncInfo(String(data.message));
    _wbFbsPollSync();
  } catch (e) {
    _wbFbsSetSyncInfo(String(e.message || e), "error");
    if (syncBtn) syncBtn.disabled = false;
    if (stopBtn) stopBtn.classList.add("hidden");
  }
}
window.syncWbFbs = syncWbFbs;

async function stopWbFbsSync() {
  try {
    await fetch("/api/wb-fbs/sync/stop", { method: "POST", headers: jsonHeaders() });
  } catch (_) {}
}
window.stopWbFbsSync = stopWbFbsSync;

function _wbFbsPollSync() {
  if (wbFbsState.pollTimer) clearInterval(wbFbsState.pollTimer);
  wbFbsState.pollTimer = setInterval(async () => {
    try {
      const res = await fetch("/api/wb-fbs/sync/status");
      const st = await res.json();
      const msg = String(st.message || "");
      const scopeMsg = /нет ни одного источника с нужным api/i.test(msg);
      const errs = scopeMsg
        ? ""
        : (st.errors || [])
            .map((e) => String(e || "").trim())
            .filter((e) => e && !/WB FBS HTTP|token scope not allowed|s2s-api-auth-marketplace|\{|"code":/i.test(e))
            .slice(0, 2)
            .join("; ");
      const text = `${msg}${errs ? " · " + errs : ""}`.trim();
      let kind = "";
      if (!st.in_progress) {
        // Keep prior coloring: any errors / «с ошибками» → red; clean success → green.
        // Pallet lines still render for any «Готово…» message (see _wbFbsSetSyncInfo).
        if (scopeMsg || (st.errors || []).length || /ошибк/i.test(msg)) kind = "error";
        else if (/готово/i.test(msg) || /остановлено/i.test(msg)) kind = "ok";
      }
      const pallets = (!st.in_progress && Array.isArray(st.pallet_summary))
        ? st.pallet_summary
        : null;
      _wbFbsSetSyncInfo(text, kind, pallets);
      if (!st.in_progress) {
        clearInterval(wbFbsState.pollTimer);
        wbFbsState.pollTimer = null;
        const syncBtn = document.getElementById("wbFbsSyncBtn");
        const stopBtn = document.getElementById("wbFbsStopBtn");
        if (syncBtn) syncBtn.disabled = false;
        if (stopBtn) stopBtn.classList.add("hidden");
        loadWbFbsOrders(false);
      }
    } catch (_) {}
  }, 1000);
}

function _wbFbsOpenBase64Images(stickers, filenamePrefix) {
  const files = (stickers || []).map((s, i) => {
    const b64 = s.file || s.barcode || "";
    const part = s.partA && s.partB ? `${s.partA}${s.partB}` : (s.orderId || s.barcode || i);
    return { name: `${filenamePrefix}_${part}.png`, b64 };
  }).filter((x) => x.b64);
  if (!files.length) {
    alert("WB не вернул файлы стикеров. Проверьте статус заказа (нужны «На сборке» / «В доставке»).");
    return;
  }
  files.forEach((f) => {
    const a = document.createElement("a");
    a.href = `data:image/png;base64,${f.b64}`;
    a.download = f.name;
    document.body.appendChild(a);
    a.click();
    a.remove();
  });
}

async function wbFbsPrintOrderStickers() {
  const ids = _wbFbsIsSuppliesTab()
    ? _wbFbsSelectedOrderIdsFromSupplies()
    : [...wbFbsState.selected].map((x) => Number(x)).filter((n) => Number.isFinite(n));
  if (!ids.length || !wbFbsState.sourceId) {
    if (_wbFbsIsSuppliesTab()) {
      alert("У выбранных поставок нет списка заказов. Синхронизируйте источник ещё раз.");
    }
    return;
  }
  const res = await fetch("/api/wb-fbs/stickers/orders", {
    method: "POST",
    headers: jsonHeaders(),
    body: JSON.stringify({ source_id: wbFbsState.sourceId, order_ids: ids, type: "png" }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    alert(data.detail || "Ошибка стикеров");
    return;
  }
  _wbFbsOpenBase64Images(data.stickers, "order");
}
window.wbFbsPrintOrderStickers = wbFbsPrintOrderStickers;

async function wbFbsPrintOneOrderSticker(orderId) {
  _wbFbsCloseRowMenus();
  const oid = Number(orderId);
  wbFbsState.selected = new Set([oid]);
  const row = wbFbsState.items.find((x) => Number(x.order_id) === oid);
  wbFbsState.selectedMeta = {};
  if (row) _wbFbsRememberMeta(row);
  _wbFbsUpdateBottomBar();
  await wbFbsPrintOrderStickers();
}
window.wbFbsPrintOneOrderSticker = wbFbsPrintOneOrderSticker;

async function wbFbsPrintSupplySticker() {
  const supplyIds = _wbFbsSelectedSupplyIds();
  if (!supplyIds.length) {
    alert(_wbFbsIsSuppliesTab()
      ? "Выберите поставку."
      : "У выбранных заказов нет ID поставки.");
    return;
  }
  const jobs = supplyIds.map((sid) => ({
    sid,
    win: window.open("", "_blank"),
  }));
  for (const job of jobs) {
    if (!job.win) {
      alert(`${job.sid}: разрешите всплывающие окна для QR поставки`);
      continue;
    }
    try {
      await wbFbsOpenSupplyQr(job.sid, { win: job.win });
    } catch (e) {
      alert(`${job.sid}: ${e.message || e}`);
    }
  }
}
window.wbFbsPrintSupplySticker = wbFbsPrintSupplySticker;

async function wbFbsPrintBoxStickers() {
  if (!wbFbsState.sourceId) return;
  const supplyIds = _wbFbsSelectedSupplyIds();
  if (!supplyIds.length) {
    alert(_wbFbsIsSuppliesTab()
      ? "Выберите поставку."
      : "У выбранных заказов нет ID поставки — короба недоступны.");
    return;
  }
  for (const sid of supplyIds) {
    const res = await fetch("/api/wb-fbs/stickers/boxes", {
      method: "POST",
      headers: jsonHeaders(),
      body: JSON.stringify({ source_id: wbFbsState.sourceId, supply_id: sid, type: "png" }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      alert(data.detail || `Ошибка стикеров коробов для ${sid}`);
      continue;
    }
    _wbFbsOpenBase64Images(data.stickers, `box_${sid}`);
  }
}
window.wbFbsPrintBoxStickers = wbFbsPrintBoxStickers;

window.initWbFbsSection = initWbFbsSection;
